    private final class OtpEditText extends EditText {
        private Runnable onEmptyDeleteListener;

        OtpEditText() {
            super(MainActivity.this);
        }

        void setOnEmptyDeleteListener(Runnable listener) {
            onEmptyDeleteListener = listener;
        }

        private boolean handleEmptyDelete() {
            if (length() == 0 && onEmptyDeleteListener != null) {
                onEmptyDeleteListener.run();
                return true;
            }
            return false;
        }

        @Override
        public boolean onKeyDown(int keyCode, android.view.KeyEvent event) {
            if (keyCode == android.view.KeyEvent.KEYCODE_DEL && handleEmptyDelete()) {
                return true;
            }
            return super.onKeyDown(keyCode, event);
        }

        @Override
        public android.view.inputmethod.InputConnection onCreateInputConnection(
                android.view.inputmethod.EditorInfo outAttrs) {
            android.view.inputmethod.InputConnection target = super.onCreateInputConnection(outAttrs);
            if (target == null) return null;
            return new android.view.inputmethod.InputConnectionWrapper(target, true) {
                @Override
                public boolean deleteSurroundingText(int beforeLength, int afterLength) {
                    if (beforeLength == 1 && afterLength == 0 && handleEmptyDelete()) return true;
                    return super.deleteSurroundingText(beforeLength, afterLength);
                }

                @Override
                public boolean deleteSurroundingTextInCodePoints(int beforeLength, int afterLength) {
                    if (beforeLength == 1 && afterLength == 0 && handleEmptyDelete()) return true;
                    return super.deleteSurroundingTextInCodePoints(beforeLength, afterLength);
                }
            };
        }
    }

