    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        FirebaseCrashlytics crashlytics = FirebaseCrashlytics.getInstance();
        crashlytics.setCustomKey("screen", "splash");
        crashlytics.setCustomKey("app_version", BuildConfig.VERSION_NAME);
        crashlytics.setCustomKey("app_version_code", BuildConfig.VERSION_CODE);
        crashlytics.setCustomKey("android_sdk", Build.VERSION.SDK_INT);
        WindowCompat.setDecorFitsSystemWindows(getWindow(), false);
        applyLightSystemBarIcons();
        getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);
        setContentView(splashScreen());
        carouselHandler.postDelayed(this::startAfterSplash, SPLASH_DELAY_MS);
    }

    private void startAfterSplash() {
        if (isFinishing() || isDestroyed()) {
            return;
        }
        setContentView(R.layout.activity_main);
        services = ServiceCatalog.services();
        bookingStore = new BookingStore(this);
        markLegacyBookingMigrationDone();
        firebaseAuth = FirebaseAuth.getInstance();
        googleSignInClient = buildGoogleSignInClient();
        firestore = FirebaseFirestore.getInstance("default");
        realtimeDatabase = FirebaseDatabase.getInstance("https://apna-servo-default-rtdb.firebaseio.com");
        firebaseStorage = FirebaseStorage.getInstance();
        backendClient = new BackendClient(this);
        backendClient.warmUp();
        appControlRepository = new AppControlRepository(this, backendClient);
        appControl = appControlRepository.cached();
        backendSocketClient = new BackendSocketClient(backendClient);
        latestBackendBookingId = secureString(KEY_BACKEND_BOOKING_ID, "");
        loggedIn = getSharedPreferences(PREFS, MODE_PRIVATE).getBoolean("logged_in", false);
        FirebaseCrashlytics.getInstance().setCustomKey("authenticated", loggedIn);
        FirebaseCrashlytics.getInstance().setCustomKey("low_ram_device", isLowRamDevice());
        ensureBookingCacheBelongsToCurrentPhone();
        restoreLatestActiveBookingFromStore();
        capturePushHintFromIntent(getIntent());

        mainScroll = findViewById(R.id.mainScroll);
        screenContent = findViewById(R.id.screenContent);
        bottomNav = findViewById(R.id.bottomNav);
        floatingFooter = findViewById(R.id.floatingFooter);
        supportInputDock = findViewById(R.id.supportInputDock);
        configureRootWindowInsets();
        footerAvatar = findViewById(R.id.footerAvatar);
        footerTitle = findViewById(R.id.footerTitle);
        footerSubtitle = findViewById(R.id.footerSubtitle);
        footerAction = findViewById(R.id.footerAction);
        footerClose = findViewById(R.id.footerClose);
        navHome = findViewById(R.id.navHome);
        navBookings = findViewById(R.id.navBookings);
        navAdd = findViewById(R.id.navAdd);
        navOffers = findViewById(R.id.navOffers);
        navProfile = findViewById(R.id.navProfile);
        navOffers.setVisibility(View.GONE);
        screenContent.setClipChildren(false);
        mainScroll.setClipChildren(false);
        mainScroll.setClipToPadding(false);
        setupBottomNavItems();

        navHome.setOnClickListener(view -> showHome());
        navBookings.setOnClickListener(view -> showBookingsList());
        navOffers.setOnClickListener(view -> showHome());
        navProfile.setOnClickListener(view -> showProfile());
        navAdd.setVisibility(View.GONE);
        bottomNav.setElevation(dp(16));
        floatingFooter.setElevation(dp(18));
        footerAction.setElevation(dp(7));
        footerAction.setLineSpacing(dp(2), 1f);
        footerAction.setShadowLayer(dp(5), 0f, dp(1), Color.argb(95, 0, 0, 0));
        footerClose.setBackground(round(Color.rgb(249, 232, 231), dp(17)));
        TextView[] navButtons = {navHome, navBookings, navOffers, navProfile};
        for (TextView navButton : navButtons) {
            addPressAnimation(navButton);
        }
        floatingFooter.setOnClickListener(view -> openCurrentBookingStage());
        footerClose.setOnClickListener(view -> floatingFooter.setVisibility(View.GONE));
        addPressAnimation(floatingFooter);
        addPressAnimation(footerAction);
        addPressAnimation(footerClose);
        installKeyboardLift();
        registerBackHandler();
        registerNetworkSync();
        selectedService = serviceById("ac");
        if (loggedIn) {
            recoverCustomerIdentityFromFirebase();
            showHome();
            carouselHandler.postDelayed(this::startLoggedInBackgroundSync, 120);
            carouselHandler.postDelayed(this::applyPendingAdminDeepLink, 1200);
        } else {
            showLogin();
            carouselHandler.postDelayed(this::requestNotificationPermission, 700);
        }
        applyAppControlUpdatePrompt();
        refreshAppControl(false);
    }

    private void configureRootWindowInsets() {
        View root = findViewById(R.id.appRoot);
        if (root == null) return;
        ViewCompat.setOnApplyWindowInsetsListener(root, (view, windowInsets) -> {
            Insets systemBars = windowInsets.getInsets(
                    WindowInsetsCompat.Type.systemBars() | WindowInsetsCompat.Type.displayCutout());
            Insets ime = windowInsets.getInsets(WindowInsetsCompat.Type.ime());
            boolean imeVisible = windowInsets.isVisible(WindowInsetsCompat.Type.ime());
            boolean loginScreen = "login".equals(currentScreen);
            int bottomInset = imeVisible && !loginScreen
                    ? Math.max(systemBars.bottom, ime.bottom)
                    : systemBars.bottom;
            view.setPadding(systemBars.left, systemBars.top, systemBars.right, bottomInset);
            if (loginScreen) {
                loginImeBottom = imeVisible ? ime.bottom : 0;
                view.post(this::updateLoginKeyboardLift);
            } else if (imeVisible) {
                view.post(this::ensureFocusedInputVisible);
            }
            return windowInsets;
        });
        ViewCompat.requestApplyInsets(root);
    }

    private void applyLightSystemBarIcons() {
        WindowInsetsControllerCompat controller = WindowCompat.getInsetsController(
                getWindow(), getWindow().getDecorView());
        controller.setAppearanceLightStatusBars(true);
        controller.setAppearanceLightNavigationBars(true);
    }

    private SecurePrefs securePrefs() {
        if (securePrefs == null) {
            securePrefs = new SecurePrefs(this, PREFS);
        }
        return securePrefs;
    }

    private String secureString(String key, String fallback) {
        android.content.SharedPreferences legacy = getSharedPreferences(PREFS, MODE_PRIVATE);
        String legacyValue = legacy.getString(key, null);
        String value = securePrefs().getString(key, legacyValue == null ? fallback : legacyValue);
        if (legacyValue != null) {
            securePrefs().putString(key, legacyValue);
            legacy.edit().remove(key).apply();
            return legacyValue;
        }
        return value;
    }

    private void putSecureString(String key, String value) {
        securePrefs().putString(key, value == null ? "" : value);
        getSharedPreferences(PREFS, MODE_PRIVATE).edit().remove(key).apply();
    }

    private void removeSecureString(String key) {
        securePrefs().remove(key);
        getSharedPreferences(PREFS, MODE_PRIVATE).edit().remove(key).apply();
    }

