    private void registerBackHandler() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            getOnBackInvokedDispatcher().registerOnBackInvokedCallback(
                    OnBackInvokedDispatcher.PRIORITY_DEFAULT,
                    this::handleBackNavigation
            );
        }
    }

    private void setCurrentScreen(String screen) {
        FirebaseCrashlytics.getInstance().setCustomKey(
                "screen",
                TextUtils.isEmpty(screen) ? "unknown" : screen
        );
        if (TextUtils.equals(currentScreen, screen)) {
            return;
        }
        if ("bookings".equals(currentScreen) && !"bookings".equals(screen)) {
            clearBookingListStatusListeners();
        }
        if ("login".equals(screen)) {
            screenHistory.clear();
            currentScreen = screen;
            return;
        }
        if (!restoringScreen && !TextUtils.isEmpty(currentScreen) && !"login".equals(currentScreen)) {
            screenHistory.add(currentScreen);
            if (screenHistory.size() > 30) {
                screenHistory.remove(0);
            }
        }
        currentScreen = screen;
    }

    private void handleBackNavigation() {
        if (startupLocationGateActive) {
            finishStartupLocationGate(false);
            return;
        }
        if ("login_otp".equals(currentScreen)) {
            showLogin();
            return;
        }
        while (!screenHistory.isEmpty()) {
            String previous = screenHistory.remove(screenHistory.size() - 1);
            if (TextUtils.isEmpty(previous) || previous.equals(currentScreen)) {
                continue;
            }
            showPreviousScreen(previous);
            return;
        }
        if ("login".equals(currentScreen) || "home".equals(currentScreen)) {
            finish();
        } else {
            showHome();
        }
    }

    private void showPreviousScreen(String screen) {
        boolean wasRestoring = restoringScreen;
        restoringScreen = true;
        try {
            switch (screen) {
                case "home":
                    showHome();
                    break;
                case "all":
                    showAllServices(navigationService().getCategory());
                    break;
                case "detail":
                    showDetail(navigationService());
                    break;
                case "booking":
                    showBooking(navigationService());
                    break;
                case "confirm":
                    showBookingConfirm(navigationService());
                    break;
                case "bookings":
                    showBookingsList();
                    break;
                case "booking_history_details":
                    if (latestBooking != null) showBookingHistoryDetails(latestBooking); else showBookingsList();
                    break;
                case "track":
                    showTrack();
                    break;
                case "profile":
                    showProfile();
                    break;
                case "support":
                    showSupportChat();
                    break;
                case "booking_chat":
                    showBookingChat(latestBooking);
                    break;
                case "notifications":
                    showNotifications();
                    break;
                case "commercial":
                    showCommercialServicesPage();
                    break;
                case "commercial_preparing":
                    showCommercialServicePreparing();
                    break;
                case "commercial_form1":
                    showCommercialFormOne();
                    break;
                case "commercial_form2":
                    showCommercialFormTwo();
                    break;
                case "commercial_submitted":
                    showCommercialSubmitted();
                    break;
                case "commercial_inspection":
                    showCommercialInspectionScheduled();
                    break;
                case "commercial_quote":
                    showCommercialQuotationReady();
                    break;
                case "commercial_approved":
                    showCommercialQuotationApproved();
                    break;
                case "commercial_team":
                    showCommercialTeamAssigned();
                    break;
                case "commercial_plan":
                    showCommercialProjectPlan();
                    break;
                case "commercial_progress":
                    showCommercialProjectProgress();
                    break;
                case "commercial_update":
                    showCommercialProgressUpdate();
                    break;
                case "commercial_quality":
                    showCommercialQualityInspection();
                    break;
                case "commercial_completed":
                    showCommercialProjectCompleted();
                    break;
                case "commercial_amc":
                    showCommercialAmcDashboard();
                    break;
                case "commercial_raise":
                    showCommercialRaiseRequest();
                    break;
                case "assigning":
                    showPartnerAssignmentWait();
                    break;
                case "login":
                    showLogin();
                    break;
                default:
                    showHome();
                    break;
            }
        } finally {
            restoringScreen = wasRestoring;
        }
    }

