    @Override
    public void onRequestPermissionsResult(int requestCode, String[] permissions, int[] grantResults) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults);
        if (requestCode == SUPPORT_CAMERA_PERMISSION_REQUEST) {
            boolean granted = grantResults.length > 0 && grantResults[0] == PackageManager.PERMISSION_GRANTED;
            if (granted) {
                launchSupportCamera();
            } else {
                Toast.makeText(this, "Camera permission required for support photo.", Toast.LENGTH_SHORT).show();
            }
            return;
        }
        if (requestCode != LOCATION_PERMISSION_REQUEST) {
            return;
        }
        boolean granted = false;
        for (int result : grantResults) {
            if (result == PackageManager.PERMISSION_GRANTED) {
                granted = true;
                break;
            }
        }
        if (startupLocationGateActive) {
            if (granted) {
                startStartupLocationDetection();
            } else {
                showStartupLocationPermissionState("Location permission was denied. Allow it to auto-detect, or continue with Guwahati as default.");
            }
            return;
        }
        if (granted) {
            fetchCurrentLocation();
        } else {
            setManualLocationFallback("Permission denied. Please type the service address manually.");
        }
    }

    private void showStartupLocationGate() {
        startupLocationGateActive = true;
        startupLocationWaitingForSettings = false;
        currentScreen = "location_detect";
        stopBannerCarousel();
        if (startupLocationTimeoutRunnable != null) {
            carouselHandler.removeCallbacks(startupLocationTimeoutRunnable);
            startupLocationTimeoutRunnable = null;
        }
        if (supportInputDock != null) {
            supportInputDock.removeAllViews();
            supportInputDock.setTranslationY(0f);
            supportInputDock.setVisibility(View.GONE);
        }
        bottomNav.setVisibility(View.GONE);
        floatingFooter.setVisibility(View.GONE);
        mainScroll.setFillViewport(true);
        mainScroll.setPadding(0, 0, 0, 0);
        mainScroll.setOnTouchListener((view, event) -> event.getAction() == MotionEvent.ACTION_MOVE);
        mainScroll.post(() -> mainScroll.scrollTo(0, 0));
        screenContent.removeAllViews();
        screenContent.setPadding(dp(22), 0, dp(22), 0);
        screenContent.setBackgroundColor(BG);
        screenContent.setMinimumHeight(getResources().getDisplayMetrics().heightPixels);

        applyLightSystemBarIcons();

        FrameLayout shell = new FrameLayout(this);
        shell.setClipChildren(false);
        shell.setClipToPadding(false);

        LinearLayout card = vertical();
        card.setGravity(Gravity.CENTER_HORIZONTAL);
        card.setPadding(dp(22), dp(26), dp(22), dp(24));
        card.setBackground(locationGateSurfaceDrawable());
        card.setElevation(dp(12));
        card.setTranslationZ(dp(3));

        card.addView(brandImageWordmark(214, 70), margin(214, 70, 0, 0, 0, 16));
        card.addView(startupLocationPulseView(), margin(174, 174, 0, 0, 0, 18));

        startupLocationTitle = text("Detecting your location", 22, BLACK, true);
        startupLocationTitle.setGravity(Gravity.CENTER);
        startupLocationTitle.setIncludeFontPadding(false);
        card.addView(startupLocationTitle, margin(-1, -2, 0, 0, 0, 8));

        startupLocationStatus = text("Finding the best service area near you...", 13, MUTED, false);
        startupLocationStatus.setGravity(Gravity.CENTER);
        startupLocationStatus.setLineSpacing(dp(2), 1f);
        card.addView(startupLocationStatus, margin(-1, -2, 4, 0, 4, 20));

        startupLocationActions = horizontal();
        startupLocationActions.setGravity(Gravity.CENTER);
        card.addView(startupLocationActions, margin(-1, -2, 0, 0, 0, 0));

        TextView privacy = text("Location is used only to show nearby services and booking support.", 11, Color.rgb(130, 123, 120), false);
        privacy.setGravity(Gravity.CENTER);
        card.addView(privacy, margin(-1, -2, 0, 18, 0, 0));

        FrameLayout.LayoutParams cardParams = new FrameLayout.LayoutParams(-1, -2, Gravity.CENTER);
        shell.addView(card, cardParams);
        int shellHeight = Math.max(dp(620), getResources().getDisplayMetrics().heightPixels - dp(24));
        screenContent.addView(shell, margin(-1, shellHeight, 0, 0, 0, 0));
        animateIn(shell, 20);
        carouselHandler.postDelayed(this::startStartupLocationDetection, 450);
    }

