    private void startStartupLocationDetection() {
        if (!startupLocationGateActive) {
            return;
        }
        updateStartupLocationState("Detecting your location", "Finding the best service area near you...", ORANGE);
        clearStartupLocationActions();
        if (!hasStartupLocationPermission()) {
            if (requestStartupLocationPermissionIfAvailable(false)) {
                return;
            }
            showStartupLocationPermissionState("Allow location permission to detect your service area automatically.");
            return;
        }

        LocationManager manager = (LocationManager) getSystemService(LOCATION_SERVICE);
        if (manager == null) {
            showStartupLocationOffState("Location service is unavailable on this device.");
            return;
        }
        if (!isDeviceLocationEnabled(manager)) {
            showStartupLocationOffState("Device location is off. Turn it on to detect your area.");
            return;
        }

        Location bestLocation = bestLastKnownLocation(manager);
        if (bestLocation != null) {
            completeStartupLocationDetected(bestLocation);
            return;
        }

        String provider = startupLocationProvider(manager);
        if (TextUtils.isEmpty(provider)) {
            showStartupLocationOffState("Location provider is unavailable. Turn on GPS or network location.");
            return;
        }

        startupLocationTimeoutRunnable = () -> {
            if (startupLocationGateActive) {
                showStartupLocationRetryState("Location is taking longer than expected. You can retry or continue with Guwahati as default.");
            }
        };
        carouselHandler.postDelayed(startupLocationTimeoutRunnable, 6500);
        try {
            manager.requestSingleUpdate(provider, new LocationListener() {
                @Override
                public void onLocationChanged(Location location) {
                    if (startupLocationTimeoutRunnable != null) {
                        carouselHandler.removeCallbacks(startupLocationTimeoutRunnable);
                        startupLocationTimeoutRunnable = null;
                    }
                    completeStartupLocationDetected(location);
                }
            }, Looper.getMainLooper());
        } catch (SecurityException exception) {
            showStartupLocationPermissionState("Location permission is blocked. Allow it to auto-detect, or continue with Guwahati as default.");
        } catch (IllegalArgumentException exception) {
            showStartupLocationRetryState("Location provider failed. You can retry or continue with Guwahati as default.");
        }
    }

    private boolean hasStartupLocationPermission() {
        return Build.VERSION.SDK_INT < Build.VERSION_CODES.M
                || checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION) == PackageManager.PERMISSION_GRANTED
                || checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION) == PackageManager.PERMISSION_GRANTED;
    }

    private boolean isDeviceLocationEnabled(LocationManager manager) {
        try {
            return manager.isProviderEnabled(LocationManager.GPS_PROVIDER)
                    || manager.isProviderEnabled(LocationManager.NETWORK_PROVIDER);
        } catch (Exception ignored) {
            return false;
        }
    }

    private String startupLocationProvider(LocationManager manager) {
        try {
            if (manager.isProviderEnabled(LocationManager.GPS_PROVIDER)) {
                return LocationManager.GPS_PROVIDER;
            }
            if (manager.isProviderEnabled(LocationManager.NETWORK_PROVIDER)) {
                return LocationManager.NETWORK_PROVIDER;
            }
        } catch (Exception ignored) {
            return null;
        }
        return null;
    }

    private void showStartupLocationPermissionState(String message) {
        updateStartupLocationState("Allow location access", message, ORANGE);
        clearStartupLocationActions();
        addStartupLocationAction("Continue", Color.WHITE, ORANGE, view -> {
            if (!requestStartupLocationPermissionIfAvailable(true)) {
                openAppLocationPermissionSettings();
            }
        });
        addStartupLocationAction("Skip", MUTED, Color.WHITE, view -> finishStartupLocationGate(false));
    }

    private boolean requestStartupLocationPermissionIfAvailable(boolean userInitiated) {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.M || hasStartupLocationPermission()) {
            return false;
        }
        boolean requestedBefore = getSharedPreferences(PREFS, MODE_PRIVATE)
                .getBoolean(KEY_LOCATION_PERMISSION_REQUESTED, false);
        boolean canAskAgain = shouldShowRequestPermissionRationale(Manifest.permission.ACCESS_FINE_LOCATION)
                || shouldShowRequestPermissionRationale(Manifest.permission.ACCESS_COARSE_LOCATION);
        if (requestedBefore && !canAskAgain) {
            return false;
        }
        getSharedPreferences(PREFS, MODE_PRIVATE).edit()
                .putBoolean(KEY_LOCATION_PERMISSION_REQUESTED, true)
                .apply();
        requestPermissions(
                new String[]{Manifest.permission.ACCESS_FINE_LOCATION, Manifest.permission.ACCESS_COARSE_LOCATION},
                LOCATION_PERMISSION_REQUEST
        );
        return true;
    }

    private void openAppLocationPermissionSettings() {
        startupLocationWaitingForSettings = true;
        try {
            Intent intent = new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS);
            intent.setData(Uri.parse("package:" + getPackageName()));
            startActivity(intent);
        } catch (Exception ignored) {
            startActivity(new Intent(Settings.ACTION_LOCATION_SOURCE_SETTINGS));
        }
    }

    private void showStartupLocationOffState(String message) {
        updateStartupLocationState("Turn on device location", message, ORANGE);
        clearStartupLocationActions();
        addStartupLocationAction("Open Settings", Color.WHITE, ORANGE, view -> {
            startupLocationWaitingForSettings = true;
            updateStartupLocationState("Waiting for location", "Turn on location, then return to ApnaServo.", ORANGE);
            try {
                startActivity(new Intent(Settings.ACTION_LOCATION_SOURCE_SETTINGS));
            } catch (Exception exception) {
                Toast.makeText(this, "Location settings unavailable", Toast.LENGTH_SHORT).show();
            }
        });
        addStartupLocationAction("Continue", MUTED, Color.WHITE, view -> finishStartupLocationGate(false));
    }

    private void showStartupLocationRetryState(String message) {
        updateStartupLocationState("Location not found yet", message, ORANGE);
        clearStartupLocationActions();
        addStartupLocationAction("Retry", Color.WHITE, ORANGE, view -> startStartupLocationDetection());
        addStartupLocationAction("Continue", MUTED, Color.WHITE, view -> finishStartupLocationGate(false));
    }

    private void completeStartupLocationDetected(Location location) {
        if (!startupLocationGateActive || location == null) {
            return;
        }
        serviceLat = location.getLatitude();
        serviceLng = location.getLongitude();
        hasServiceLocation = true;
        updateStartupLocationState("Location detected", "Nearby ApnaServo services are ready.", GREEN);
        clearStartupLocationActions();
        carouselHandler.postDelayed(() -> finishStartupLocationGate(true), 650);
    }

    private void finishStartupLocationGate(boolean detected) {
        if (!startupLocationGateActive) {
            return;
        }
        startupLocationGateActive = false;
        startupLocationWaitingForSettings = false;
        if (startupLocationTimeoutRunnable != null) {
            carouselHandler.removeCallbacks(startupLocationTimeoutRunnable);
            startupLocationTimeoutRunnable = null;
        }
        View gate = screenContent.getChildCount() > 0 ? screenContent.getChildAt(0) : null;
        Runnable openHome = () -> {
            screenHistory.clear();
            currentScreen = "login";
            screenContent.setMinimumHeight(0);
            showHome();
            carouselHandler.postDelayed(this::startLoggedInBackgroundSync, 120);
            carouselHandler.postDelayed(this::requestNotificationPermission, detected ? 650 : 900);
        };
        if (gate == null) {
            openHome.run();
            return;
        }
        gate.animate()
                .alpha(0f)
                .translationY(-dp(18))
                .setDuration(320)
                .setInterpolator(new AccelerateDecelerateInterpolator())
                .withEndAction(openHome)
                .start();
    }

    private void updateStartupLocationState(String title, String status, int color) {
        if (startupLocationTitle != null) {
            startupLocationTitle.setText(title);
        }
        if (startupLocationStatus != null) {
            startupLocationStatus.setText(status);
            startupLocationStatus.setTextColor(color == GREEN ? Color.rgb(58, 116, 87) : MUTED);
        }
        if (startupLocationIcon != null) {
            startupLocationIcon.setText(color == GREEN ? "OK" : "GPS");
            startupLocationIcon.setBackground(round(color, dp(46)));
        }
    }

    private void clearStartupLocationActions() {
        if (startupLocationActions != null) {
            startupLocationActions.removeAllViews();
        }
    }

    private void addStartupLocationAction(String label, int textColor, int backgroundColor, View.OnClickListener listener) {
        if (startupLocationActions == null) {
            return;
        }
        TextView action = text(label, 13, textColor, true);
        action.setGravity(Gravity.CENTER);
        int strokeColor = backgroundColor == Color.WHITE ? Color.rgb(232, 213, 213) : backgroundColor;
        action.setBackground(stroke(backgroundColor, strokeColor, dp(15)));
        action.setOnClickListener(listener);
        addPressAnimation(action);
        startupLocationActions.addView(action, margin(0, 48, 5, 0, 5, 0, 1));
    }

    private GradientDrawable locationGateSurfaceDrawable() {
        GradientDrawable drawable = new GradientDrawable(
                GradientDrawable.Orientation.TL_BR,
                new int[]{Color.WHITE, Color.rgb(255, 250, 249), Color.rgb(255, 238, 242)}
        );
        drawable.setCornerRadius(dp(28));
        drawable.setStroke(dp(1), Color.rgb(244, 215, 218));
        return drawable;
    }

    private void refreshAppControl(boolean force) {
        if (appControlRepository == null || activityDestroyed) return;
        appControlRepository.refreshIfDue(force, (config, fromNetwork) -> {
            if (activityDestroyed || isFinishing() || isDestroyed()) return;
            AppControlConfig previous = appControl;
            appControl = config == null ? AppControlConfig.DEFAULT : config;
            applyAppControlUpdatePrompt();
            if (navBookings != null) {
                navBookings.setVisibility(featureEnabled(FeatureRegistry.BOOKING_HISTORY) ? View.VISIBLE : View.GONE);
            }
            // A published maintenance state blocks a booking attempt, not the
            // whole home screen. This keeps the status modal in context.
            if (appControl.mode == AppControlConfig.AppMode.LIVE && appStatusDialog != null
                    && appStatusDialog.isShowing()) {
                appStatusDialog.dismiss();
            }
            if ("home".equals(currentScreen)
                    && (!TextUtils.equals(previous.version, appControl.version)
                    || previous.mode != appControl.mode)) {
                showHome();
            }
        });
    }

    private void showGlobalAppStatus() {
        if (isFinishing() || isDestroyed()) return;
        if (appStatusDialog != null && appStatusDialog.isShowing()) return;

        final boolean maintenance = appControl.mode == AppControlConfig.AppMode.MAINTENANCE;
        final boolean areaUnavailable = appControl.mode == AppControlConfig.AppMode.PARTIALLY_UNAVAILABLE;
        final int illustration = maintenance ? R.drawable.app_status_maintenance
                : areaUnavailable ? R.drawable.app_status_area_unavailable
                : R.drawable.app_status_high_demand;
        final String title = maintenance ? "ApnaServo is Under Maintenance"
                : areaUnavailable ? "We're Not Available in Your Area"
                : "App is facing high demand";
        final String message = maintenance
                ? "We are currently performing some maintenance to improve your experience."
                : areaUnavailable
                ? "Sorry, ApnaServo services are not currently available in your area."
                : "We are currently receiving a high number of service requests.";
        final String secondary = maintenance || !areaUnavailable
                ? "Please try again after some time."
                : "We're working to expand our services and reach you soon.";

        AlertDialog dialog = new AlertDialog.Builder(this).create();
        appStatusDialog = dialog;
        dialog.setCanceledOnTouchOutside(true);
        dialog.setOnDismissListener(ignored -> appStatusDialog = null);
        LinearLayout card = vertical();
        card.setGravity(Gravity.CENTER_HORIZONTAL);
        card.setPadding(dp(28), dp(24), dp(28), dp(28));
        card.setBackground(round(Color.WHITE, dp(30)));

        ImageView artwork = new ImageView(this);
        artwork.setImageResource(illustration);
        artwork.setScaleType(ImageView.ScaleType.CENTER_INSIDE);
        card.addView(artwork, new LinearLayout.LayoutParams(-1, dp(185)));

        TextView heading = text(title, 27, Color.rgb(29, 37, 57), true);
        heading.setGravity(Gravity.CENTER);
        heading.setLineSpacing(dp(2), 1f);
        card.addView(heading, margin(-1, -2, 0, 12, 0, 0));
        TextView accent = text("────  •  ────", 14, BOOKING_THEME, true);
        accent.setGravity(Gravity.CENTER);
        card.addView(accent, margin(-1, -2, 0, 12, 0, 0));
        TextView body = text(message + "\n\n" + secondary, 16, Color.rgb(74, 80, 96), false);
        body.setGravity(Gravity.CENTER);
        body.setLineSpacing(dp(4), 1f);
        card.addView(body, margin(-1, -2, 0, 0, 0, areaUnavailable ? 18 : 24));

        if (areaUnavailable) {
            LinearLayout info = horizontal();
            info.setGravity(Gravity.CENTER_VERTICAL);
            info.setPadding(dp(16), dp(12), dp(16), dp(12));
            info.setBackground(round(Color.rgb(255, 239, 243), dp(14)));
            TextView pin = text("⌖", 30, BOOKING_THEME, true);
            pin.setGravity(Gravity.CENTER);
            info.addView(pin, new LinearLayout.LayoutParams(dp(45), dp(50)));
            LinearLayout copy = vertical();
            copy.addView(text("Service unavailable in your location", 15, Color.rgb(41, 48, 67), true));
            copy.addView(text("We'll be coming to more areas soon.", 13, Color.rgb(82, 88, 105), false), margin(-1, -2, 0, 4, 0, 0));
            info.addView(copy, new LinearLayout.LayoutParams(0, -2, 1));
            card.addView(info, margin(-1, -2, 0, 0, 0, 22));
        }

        TextView action = orangeButton(maintenance || areaUnavailable ? "Okay, Got It" : "Okay");
        action.setOnClickListener(view -> dialog.dismiss());
        card.addView(action, new LinearLayout.LayoutParams(-1, dp(58)));
        if (areaUnavailable) {
            FrameLayout modal = new FrameLayout(this);
            modal.addView(card, new FrameLayout.LayoutParams(-1, -2));
            TextView close = text("×", 31, BOOKING_THEME, false);
            close.setGravity(Gravity.CENTER);
            close.setBackground(round(Color.rgb(255, 239, 243), dp(22)));
            close.setOnClickListener(view -> dialog.dismiss());
            FrameLayout.LayoutParams closeParams = new FrameLayout.LayoutParams(dp(44), dp(44), Gravity.TOP | Gravity.END);
            closeParams.topMargin = dp(14);
            closeParams.rightMargin = dp(14);
            modal.addView(close, closeParams);
            dialog.setView(modal);
        } else {
            dialog.setView(card);
        }
        dialog.setOnShowListener(ignored -> {
            Window window = dialog.getWindow();
            if (window == null) return;
            window.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));
            window.setDimAmount(0.72f);
            window.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);
            window.setLayout((int) (getResources().getDisplayMetrics().widthPixels * 0.86f), WindowManager.LayoutParams.WRAP_CONTENT);
        });
        dialog.show();
    }

    private void applyAppControlUpdatePrompt() {
        if (screenContent == null || appControl == null) return;
        if (!appControl.update.enabled) {
            dismissAppUpdateDialog();
            return;
        }
        AppControlConfig.Update update = appControl.update;
        boolean belowMinimum = !TextUtils.isEmpty(update.minimumVersion)
                && AppControlConfig.compareVersions(BuildConfig.VERSION_NAME, update.minimumVersion) < 0;
        boolean belowLatest = !TextUtils.isEmpty(update.latestVersion)
                && AppControlConfig.compareVersions(BuildConfig.VERSION_NAME, update.latestVersion) < 0;
        boolean force = belowMinimum || (update.force && belowLatest);
        if (!force && !belowLatest) {
            dismissAppUpdateDialog();
            return;
        }
        if (!force && softUpdateDismissedThisSession) return;
        if (appUpdateDialog != null && appUpdateDialog.isShowing()) return;

        AlertDialog dialog = new AlertDialog.Builder(this).create();
        appUpdateDialog = dialog;
        dialog.setCancelable(!force);
        appUpdateDialog.setCanceledOnTouchOutside(!force);
        appUpdateDialog.setOnDismissListener(dismissed -> {
            if (!force) softUpdateDismissedThisSession = true;
            appUpdateDialog = null;
        });

        LinearLayout card = vertical();
        card.setGravity(Gravity.CENTER_HORIZONTAL);
        card.setPadding(dp(force ? 24 : 20), dp(force ? 18 : 20), dp(force ? 24 : 20), dp(force ? 18 : 16));
        card.setBackground(round(Color.WHITE, dp(18)));

        if (!force) {
            TextView updateIcon = text("\u2191", 23, Color.WHITE, true);
            updateIcon.setGravity(Gravity.CENTER);
            updateIcon.setBackground(round(Color.rgb(246, 76, 112), dp(10)));
            card.addView(updateIcon, new LinearLayout.LayoutParams(dp(48), dp(48)));
        }

        String fallbackTitle = force ? "Update Required" : "A new version is available!";
        TextView title = text(TextUtils.isEmpty(update.title) ? fallbackTitle : update.title,
                force ? 18 : 19, Color.rgb(25, 25, 29), true);
        title.setGravity(Gravity.CENTER);
        card.addView(title, margin(-1, -2, 0, force ? 0 : 14, 0, 0));

        String fallbackMessage = force
                ? "You must update to continue using ApnaServo."
                : "We've improved performance, fixed bugs, and added exciting new features.\nPlease update now to get the best experience.";
        TextView message = text(TextUtils.isEmpty(update.message) ? fallbackMessage : update.message,
                force ? 13 : 13, Color.rgb(75, 75, 80), false);
        message.setGravity(Gravity.CENTER);
        message.setLineSpacing(dp(2), 1f);
        card.addView(message, margin(-1, -2, 0, force ? 8 : 12, 0, force ? 18 : 20));

        TextView updateNow = text(TextUtils.isEmpty(update.buttonText) ? "Update Now" : update.buttonText,
                14, Color.WHITE, true);
        updateNow.setGravity(Gravity.CENTER);
        updateNow.setBackground(round(Color.rgb(244, 67, 105), dp(9)));
        addPressAnimation(updateNow);
        card.addView(updateNow, new LinearLayout.LayoutParams(-1, dp(force ? 46 : 48)));
        updateNow.setOnClickListener(view -> {
            boolean opened = openValidatedExternalUrl(update.storeUrl);
            if (opened && !force) dialog.dismiss();
        });

        if (!force) {
            TextView later = text("Not Now", 13, Color.rgb(225, 44, 83), false);
            later.setGravity(Gravity.CENTER);
            later.setOnClickListener(view -> {
                softUpdateDismissedThisSession = true;
                dialog.dismiss();
            });
            card.addView(later, new LinearLayout.LayoutParams(-1, dp(42)));
        }

        dialog.setView(card);
        dialog.setOnShowListener(ignored -> {
            Window window = dialog.getWindow();
            if (window == null) return;
            window.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));
            window.setDimAmount(0.62f);
            window.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);
            window.setLayout((int) (getResources().getDisplayMetrics().widthPixels * (force ? 0.82f : 0.90f)),
                    WindowManager.LayoutParams.WRAP_CONTENT);
        });
        dialog.show();
    }

    private boolean openValidatedExternalUrl(String rawUrl) {
        try {
            String safeUrl = AppControlConfig.isAllowedPlayStoreUrl(rawUrl, BuildConfig.APPLICATION_ID)
                    ? rawUrl.trim()
                    : "https://play.google.com/store/apps/details?id=" + BuildConfig.APPLICATION_ID;
            Intent playStore = new Intent(Intent.ACTION_VIEW,
                    Uri.parse("market://details?id=" + BuildConfig.APPLICATION_ID));
            playStore.setPackage("com.android.vending");
            try {
                startActivity(playStore);
            } catch (Exception noPlayStore) {
                startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse(safeUrl)));
            }
            return true;
        } catch (Exception error) {
            Toast.makeText(this, "Unable to open the update link.", Toast.LENGTH_LONG).show();
            return false;
        }
    }

    private void dismissAppUpdateDialog() {
        AlertDialog dialog = appUpdateDialog;
        appUpdateDialog = null;
        if (dialog != null && dialog.isShowing()) dialog.dismiss();
    }

    private void addAdminContent(List<AppControlConfig.ContentItem> items, boolean dismissable) {
        if (items == null || items.isEmpty() || !featureEnabled(FeatureRegistry.HOME_BANNERS)) return;
        int shown = 0;
        for (AppControlConfig.ContentItem item : items) {
            if (shown >= (dismissable ? 3 : 2) || (dismissable && isAdminContentDismissed(item))) continue;
            LinearLayout card = vertical();
            card.setPadding(dp(18), dp(15), dp(18), dp(15));
            card.setBackground(stroke(Color.WHITE, Color.rgb(247, 211, 216), dp(18)));
            card.setElevation(dp(2));

            if (isSafeRemoteImageUrl(item.imageUrl)) {
                ImageView remoteArtwork = new ImageView(this);
                remoteArtwork.setScaleType(ImageView.ScaleType.CENTER_CROP);
                remoteArtwork.setVisibility(View.GONE);
                card.addView(remoteArtwork, new LinearLayout.LayoutParams(-1, dp(132)));
                loadBoundedAdminImage(remoteArtwork, item.imageUrl);
            }

            LinearLayout heading = horizontal();
            heading.setGravity(Gravity.CENTER_VERTICAL);
            TextView title = text(TextUtils.isEmpty(item.title) ? "ApnaServo Update" : item.title,
                    16, BLACK, true);
            heading.addView(title, new LinearLayout.LayoutParams(0, -2, 1));
            if (dismissable) {
                TextView close = text("×", 24, MUTED, false);
                close.setGravity(Gravity.CENTER);
                heading.addView(close, new LinearLayout.LayoutParams(dp(38), dp(38)));
                close.setOnClickListener(view -> {
                    markAdminContentDismissed(item);
                    ViewParentCompat.remove(card);
                });
            }
            card.addView(heading);
            if (!TextUtils.isEmpty(item.message)) {
                TextView message = text(item.message, 13, MUTED, false);
                message.setLineSpacing(dp(3), 1f);
                card.addView(message, margin(-1, -2, 0, 7, 0, 0));
            }
            if (!TextUtils.isEmpty(item.ctaText) && isAllowedAdminAction(item.ctaAction)) {
                TextView cta = text(item.ctaText + "  →", 13, BOOKING_THEME, true);
                cta.setOnClickListener(view -> runAdminAction(item));
                card.addView(cta, margin(-1, 42, 0, 10, 0, 0));
            }
            screenContent.addView(card, margin(-1, -2, 18, 10, 18, 4));
            shown++;
        }
    }

    private boolean isAdminContentDismissed(AppControlConfig.ContentItem item) {
        return getSharedPreferences(PREFS, MODE_PRIVATE).getBoolean(
                "admin_content_" + appControl.version + "_" + item.id, false);
    }

    private void markAdminContentDismissed(AppControlConfig.ContentItem item) {
        getSharedPreferences(PREFS, MODE_PRIVATE).edit().putBoolean(
                "admin_content_" + appControl.version + "_" + item.id, true).apply();
    }

    private boolean isAllowedAdminAction(String action) {
        String value = action == null ? "" : action.trim().toLowerCase(Locale.US);
        return value.equals("home") || value.equals("support") || value.equals("bookings")
                || value.startsWith("service:");
    }

    private boolean isSafeRemoteImageUrl(String rawUrl) {
        try {
            Uri uri = Uri.parse(rawUrl == null ? "" : rawUrl.trim());
            return "https".equalsIgnoreCase(uri.getScheme()) && !TextUtils.isEmpty(uri.getHost());
        } catch (Exception ignored) { return false; }
    }

    private void loadBoundedAdminImage(ImageView target, String rawUrl) {
        if (activityDestroyed || target == null || !isSafeRemoteImageUrl(rawUrl)) return;
        RequestOptions options = new RequestOptions()
                .override(isLowRamDevice() ? 640 : 1200, isLowRamDevice() ? 640 : 1200)
                .format(DecodeFormat.PREFER_RGB_565)
                .diskCacheStrategy(DiskCacheStrategy.AUTOMATIC)
                .dontAnimate();
        Glide.with(target)
                .load(rawUrl)
                .apply(options)
                .listener(new RequestListener<Drawable>() {
                    @Override public boolean onLoadFailed(GlideException error, Object model,
                            Target<Drawable> requestTarget, boolean firstResource) {
                        target.setVisibility(View.GONE);
                        return false;
                    }

                    @Override public boolean onResourceReady(Drawable resource, Object model,
                            Target<Drawable> requestTarget, DataSource source, boolean firstResource) {
                        target.setVisibility(View.VISIBLE);
                        return false;
                    }
                })
                .into(target);
    }

    private void runAdminAction(AppControlConfig.ContentItem item) {
        String action = item.ctaAction == null ? "" : item.ctaAction.trim().toLowerCase(Locale.US);
        if ("support".equals(action)) showSupportChat();
        else if ("bookings".equals(action)) showBookingsList();
        else if (action.startsWith("service:")) {
            String id = action.substring("service:".length()).trim();
            Service service = serviceByIdOrNull(id);
            if (service != null) showBooking(service);
        } else if ("home".equals(action)) showHome();
    }

    private Service serviceByIdOrNull(String id) {
        if (services == null || TextUtils.isEmpty(id)) return null;
        for (Service service : services) if (id.equalsIgnoreCase(service.getId())) return service;
        return null;
    }

    private static final class ViewParentCompat {
        static void remove(View view) {
            if (view != null && view.getParent() instanceof ViewGroup) {
                ((ViewGroup) view.getParent()).removeView(view);
            }
        }
    }

    private void showHome() {
        setCurrentScreen("home");
        showAppChrome();
        setActiveNav(navHome);
        resetScreen();
        restoreLatestActiveBookingFromStore();
        showLatestBookingFooter(false);
        if (appControl.uiSectionVisible("hero")) addHeroBanner();
        if (appControl.uiSectionVisible("announcements")) { addAdminContent(appControl.banners, false); addAdminContent(appControl.announcements, true); }
        if (appControl.uiSectionVisible("quick_services")) addQuickServiceStrip();
        if (appControl.uiSectionVisible("commercial") && featureEnabled(FeatureRegistry.COMMERCIAL_SERVICES)) addCommercialServicesCard();

        if (appControl.uiSectionVisible("popular_services")) addServiceShowcaseSection(
                "Popular Services",
                new String[]{"ac", "electrician", "plumbing", "carpenter", "cleaning", "laundry"}
        );
        if (appControl.uiSectionVisible("more_services")) addServiceShowcaseSection(
                "More Services",
                new String[]{"roadside", "painting", "interior", "ro", "pest", "appliances"}
        );

        if (appControl.uiSectionVisible("feature_strip")) addFeatureStrip();
    }

