    private void installLoginKeyboardVisibility(EditText input) {
        input.setOnFocusChangeListener((view, hasFocus) -> {
            if (!hasFocus) return;
            view.post(this::ensureFocusedInputVisible);
        });
    }

    private void ensureFocusedInputVisible() {
        if (mainScroll == null) return;
        if ("login".equals(currentScreen)) {
            updateLoginKeyboardLift();
            return;
        }
        View focused = getCurrentFocus();
        if (!(focused instanceof EditText) || !focused.isShown()) return;
        Rect fieldBounds = new Rect();
        focused.getDrawingRect(fieldBounds);
        focused.requestRectangleOnScreen(fieldBounds, false);
    }

    private void updateLoginKeyboardLift() {
        if (mainScroll == null || loginActionsCard == null || !"login".equals(currentScreen)) return;
        mainScroll.scrollTo(0, 0);
        float targetTranslation = 0f;
        View focused = getCurrentFocus();
        if (loginImeBottom > 0 && focused instanceof EditText && focused.isShown()) {
            View root = findViewById(R.id.appRoot);
            if (root != null) {
                int[] rootLocation = new int[2];
                int[] cardLocation = new int[2];
                root.getLocationOnScreen(rootLocation);
                loginActionsCard.getLocationOnScreen(cardLocation);
                int unshiftedCardTop = Math.round(
                        cardLocation[1] - loginActionsCard.getTranslationY());
                int availableTop = rootLocation[1] + root.getPaddingTop();
                targetTranslation = Math.min(0f, availableTop - unshiftedCardTop);
            }
        }
        loginActionsCard.animate()
                .translationY(targetTranslation)
                .setDuration(220L)
                .start();
    }

    private void fitLoginContentToViewport(View hero) {
        if (mainScroll == null || screenContent == null || hero == null || !"login".equals(currentScreen)) return;
        mainScroll.scrollTo(0, 0);
        int overflow = screenContent.getHeight() - mainScroll.getHeight();
        if (overflow <= 0) return;
        ViewGroup.LayoutParams params = hero.getLayoutParams();
        int fittedHeight = Math.max(dp(190), params.height - overflow);
        if (fittedHeight < params.height) {
            params.height = fittedHeight;
            hero.setLayoutParams(params);
            hero.requestLayout();
            mainScroll.post(() -> mainScroll.scrollTo(0, 0));
        }
    }

