    private void configureOtpBoxes(EditText[] boxes, int activeColor, int inactiveColor, int radiusDp) {
        for (int i = 0; i < boxes.length; i++) {
            EditText box = boxes[i];
            final int index = i;
            box.setImeOptions(i == boxes.length - 1
                    ? android.view.inputmethod.EditorInfo.IME_ACTION_DONE
                    : android.view.inputmethod.EditorInfo.IME_ACTION_NEXT);
            box.setOnFocusChangeListener((view, hasFocus) ->
                    refreshOtpBoxBorders(boxes, activeColor, inactiveColor, radiusDp));
            box.addTextChangedListener(new TextWatcher() {
                @Override public void beforeTextChanged(CharSequence s, int start, int count, int after) {}

                @Override
                public void onTextChanged(CharSequence s, int start, int before, int count) {
                    refreshOtpBoxBorders(boxes, activeColor, inactiveColor, radiusDp);
                    if (s != null && s.length() == 1 && index < boxes.length - 1) {
                        EditText next = boxes[index + 1];
                        next.requestFocus();
                        next.setSelection(next.length());
                    }
                }

                @Override public void afterTextChanged(Editable s) {}
            });
            if (box instanceof OtpEditText) {
                ((OtpEditText) box).setOnEmptyDeleteListener(() -> {
                    if (index <= 0) return;
                    EditText previous = boxes[index - 1];
                    previous.requestFocus();
                    previous.setText("");
                    previous.setSelection(0);
                    refreshOtpBoxBorders(boxes, activeColor, inactiveColor, radiusDp);
                });
            }
        }
        refreshOtpBoxBorders(boxes, activeColor, inactiveColor, radiusDp);
    }

    private void startCustomerOtpRetriever(EditText[] boxes) {
        stopCustomerOtpRetriever();
        activeCustomerOtpBoxes = boxes;
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            for (EditText box : boxes) box.setAutofillHints("smsOTPCode");
        }
        customerOtpReceiver = new BroadcastReceiver() {
            @Override public void onReceive(android.content.Context context, Intent intent) {
                if (intent == null || !SmsRetriever.SMS_RETRIEVED_ACTION.equals(intent.getAction())) return;
                Bundle extras = intent.getExtras();
                Status status = extras == null ? null : (Status) extras.get(SmsRetriever.EXTRA_STATUS);
                if (status == null || status.getStatusCode() != CommonStatusCodes.SUCCESS) return;
                String message = extras.getString(SmsRetriever.EXTRA_SMS_MESSAGE, "");
                if (TextUtils.isEmpty(message)) {
                    Intent consentIntent = extras.getParcelable(SmsRetriever.EXTRA_CONSENT_INTENT);
                    if (consentIntent != null) {
                        try { startActivityForResult(consentIntent, OTP_SMS_CONSENT_REQUEST); } catch (Exception ignored) { }
                    }
                    return;
                }
                java.util.regex.Matcher matcher = java.util.regex.Pattern.compile("(?<!\\d)(\\d{6})(?!\\d)").matcher(message);
                if (matcher.find()) fillCustomerOtp(matcher.group(1));
            }
        };
        IntentFilter filter = new IntentFilter(SmsRetriever.SMS_RETRIEVED_ACTION);
        try {
            ContextCompat.registerReceiver(
                    this,
                    customerOtpReceiver,
                    filter,
                    SmsRetriever.SEND_PERMISSION,
                    null,
                    ContextCompat.RECEIVER_EXPORTED
            );
            SmsRetriever.getClient(this).startSmsRetriever();
            SmsRetriever.getClient(this).startSmsUserConsent(null);
        } catch (Exception error) {
            stopCustomerOtpRetriever();
            Log.w("ApnaServoOtp", "SMS Retriever could not start", error);
        }
    }

    private void fillCustomerOtp(String otp) {
        if (activeCustomerOtpBoxes == null || otp == null || !otp.matches("\\d{6}")) return;
        for (int i = 0; i < activeCustomerOtpBoxes.length && i < otp.length(); i++) {
            EditText box = activeCustomerOtpBoxes[i];
            if (box != null) box.setText(String.valueOf(otp.charAt(i)));
        }
        EditText last = activeCustomerOtpBoxes[activeCustomerOtpBoxes.length - 1];
        if (last != null) {
            last.requestFocus();
            last.setSelection(last.length());
        }
    }

    private void stopCustomerOtpRetriever() {
        if (customerOtpReceiver != null) {
            try { unregisterReceiver(customerOtpReceiver); } catch (Exception ignored) { }
        }
        customerOtpReceiver = null;
        activeCustomerOtpBoxes = null;
    }

    private void refreshOtpBoxBorders(EditText[] boxes, int activeColor, int inactiveColor, int radiusDp) {
        for (EditText box : boxes) {
            boolean highlighted = box.hasFocus() || box.length() > 0;
            box.setBackground(stroke(Color.WHITE, highlighted ? activeColor : inactiveColor, dp(radiusDp)));
        }
    }

    private String groupedCustomerPhone(String phone) {
        String clean = normalizeCustomerPhoneInput(phone);
        if (clean.length() != 10) return clean;
        return clean.substring(0, 5) + " " + clean.substring(5);
    }

    private void startCustomerOtpCountdown(TextView timer, TextView resend, String name, String phone) {
        int sequence = ++customerOtpTimerSequence;
        resend.setEnabled(false);
        resend.setAlpha(0.55f);
        Runnable[] ticker = new Runnable[1];
        final int[] seconds = {118};
        ticker[0] = () -> {
            if (sequence != customerOtpTimerSequence || !"login_otp".equals(currentScreen)) return;
            int minutePart = seconds[0] / 60;
            int secondPart = seconds[0] % 60;
            timer.setText(String.format(Locale.US, "%02d:%02d", minutePart, secondPart));
            if (seconds[0] <= 0) {
                resend.setEnabled(true);
                resend.setAlpha(1f);
                return;
            }
            seconds[0]--;
            carouselHandler.postDelayed(ticker[0], 1000);
        };
        resend.setOnClickListener(view -> {
            if (!resend.isEnabled()) return;
            pendingCustomerOtpRequestId = "";
            sendCustomerOtpRequest(normalizeCustomerPhoneInput(phone));
            startCustomerOtpCountdown(timer, resend, name, phone);
        });
        ticker[0].run();
    }

