    private void verifyCustomerOtp(String name, String phone, String otp, AlertDialog dialog, View verifyButton) {
        if (TextUtils.isEmpty(pendingCustomerOtpRequestId)) {
            Toast.makeText(this, "Please request a new OTP.", Toast.LENGTH_SHORT).show();
            return;
        }
        setOtpVerifyLoading(verifyButton, true);
        backendClient.verifyOtp(phone, "user", pendingCustomerOtpRequestId, otp, new BackendClient.JsonCallback() {
            @Override
            public void onSuccess(JSONObject object) {
                String customToken = object.optString("customToken", "");
                if (TextUtils.isEmpty(customToken)) {
                    setOtpVerifyLoading(verifyButton, false);
                    Toast.makeText(MainActivity.this, "OTP verified, but login session was not created.", Toast.LENGTH_LONG).show();
                    return;
                }
                if (firebaseAuth == null) firebaseAuth = FirebaseAuth.getInstance();
                firebaseAuth.signInWithCustomToken(customToken)
                        .addOnSuccessListener(result -> {
                            if (dialog != null) dialog.dismiss();
                            completeLogin(name, phone);
                        })
                        .addOnFailureListener(error -> {
                            setOtpVerifyLoading(verifyButton, false);
                            Toast.makeText(
                                    MainActivity.this,
                                    otpUserError(error == null ? "Firebase login failed" : error.getMessage()),
                                    Toast.LENGTH_LONG
                            ).show();
                        });
            }

            @Override
            public void onError(String message) {
                setOtpVerifyLoading(verifyButton, false);
                Toast.makeText(MainActivity.this, otpUserError(message), Toast.LENGTH_LONG).show();
            }
        });
    }

    private void setOtpVerifyLoading(View button, boolean loading) {
        if (!(button instanceof FrameLayout)) return;
        FrameLayout frame = (FrameLayout) button;
        frame.setEnabled(!loading);
        frame.setClickable(!loading);
        frame.setAlpha(loading ? 0.92f : 1f);
        TextView title = frame.getChildCount() > 0 && frame.getChildAt(0) instanceof TextView
                ? (TextView) frame.getChildAt(0) : null;
        View arrow = frame.getChildCount() > 1 ? frame.getChildAt(1) : null;
        if (title != null) title.setText(loading ? "Verifying OTP..." : "Verify OTP");
        if (arrow != null) arrow.setVisibility(loading ? View.INVISIBLE : View.VISIBLE);
        View oldSpinner = frame.findViewWithTag("otp_verify_spinner");
        if (!loading) {
            if (oldSpinner != null) frame.removeView(oldSpinner);
            return;
        }
        if (oldSpinner == null) {
            ProgressBar spinner = new ProgressBar(this, null, android.R.attr.progressBarStyleSmall);
            spinner.setTag("otp_verify_spinner");
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
                spinner.getIndeterminateDrawable().setTint(Color.WHITE);
            }
            FrameLayout.LayoutParams params = new FrameLayout.LayoutParams(dp(22), dp(22), Gravity.RIGHT | Gravity.CENTER_VERTICAL);
            params.setMargins(0, 0, dp(28), 0);
            frame.addView(spinner, params);
        }
    }

    private String maskCustomerPhone(String phone) {
        String clean = normalizeCustomerPhoneInput(phone);
        if (clean.length() < 4) return clean;
        return clean.substring(0, Math.min(2, clean.length())) + "XXXXXX" + clean.substring(clean.length() - 2);
    }

    private void completeLogin(String name, String phone) {
        String cleanPhone = normalizeCustomerPhoneInput(phone);
        String cleanName = name == null ? "" : name.trim();
        if ("google".equalsIgnoreCase(phone)) {
            cleanPhone = "";
        }
        String previousPhone = normalizeCustomerPhoneInput(secureString(KEY_CUSTOMER_PHONE, ""));
        boolean switchedPhoneAccount = isValidCustomerMobile(cleanPhone)
                && !TextUtils.isEmpty(previousPhone)
                && !cleanPhone.equals(previousPhone);
        boolean legacyUnscopedBookings = isValidCustomerMobile(cleanPhone)
                && TextUtils.isEmpty(previousPhone)
                && bookingStore != null
                && !bookingStore.load().isEmpty();
        if (switchedPhoneAccount || legacyUnscopedBookings) {
            clearLocalBookingSession();
        }
        loggedIn = true;
        getSharedPreferences(PREFS, MODE_PRIVATE).edit().putBoolean("logged_in", true).apply();
        if (!TextUtils.isEmpty(cleanName)) {
            putSecureString(KEY_CUSTOMER_NAME, cleanName);
            FirebaseUser currentUser = firebaseAuth == null ? null : firebaseAuth.getCurrentUser();
            if (currentUser != null && !cleanName.equals(currentUser.getDisplayName())) {
                currentUser.updateProfile(new UserProfileChangeRequest.Builder()
                        .setDisplayName(cleanName)
                        .build());
            }
        }
        if (isValidCustomerMobile(cleanPhone)) {
            putSecureString(KEY_CUSTOMER_PHONE, cleanPhone);
            putSecureString(KEY_BOOKING_OWNER_PHONE, cleanPhone);
            if (TextUtils.isEmpty(cleanName) && TextUtils.isEmpty(secureString(KEY_CUSTOMER_NAME, ""))) {
                putSecureString(KEY_CUSTOMER_NAME, "Customer " + cleanPhone.substring(Math.max(0, cleanPhone.length() - 4)));
            }
        }
        if (isValidCustomerMobile(cleanPhone)) {
            finishLoginAfterMobileReady(false);
            return;
        }
        finishLoginAfterMobileReady(false);
    }

    private void finishLoginAfterMobileReady(boolean continueWithLocationGate) {
        Toast.makeText(this, "Welcome to ApnaServo", Toast.LENGTH_SHORT).show();
        showHome();
        carouselHandler.postDelayed(this::startLoggedInBackgroundSync, 120);
        carouselHandler.postDelayed(this::applyPendingAdminDeepLink, 900);
    }

