    private class LoginHouseIllustrationView extends View {
        private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final Path path = new Path();

        LoginHouseIllustrationView(Activity activity) {
            super(activity);
            setLayerType(View.LAYER_TYPE_SOFTWARE, null);
        }

        @Override
        protected void onDraw(Canvas canvas) {
            super.onDraw(canvas);
            float w = getWidth();
            float h = getHeight();
            if (w <= 0 || h <= 0) {
                return;
            }

            paint.setStyle(Paint.Style.FILL);
            paint.setShader(new LinearGradient(0, 0, w, h, Color.rgb(255, 244, 246), Color.rgb(246, 205, 213), Shader.TileMode.CLAMP));
            canvas.drawCircle(w * 0.62f, h * 0.50f, Math.min(w, h) * 0.50f, paint);
            paint.setShader(null);

            paint.setColor(Color.rgb(255, 255, 255));
            paint.setShadowLayer(dp(6), 0, dp(3), Color.argb(40, 180, 72, 91));
            canvas.drawRoundRect(new RectF(w * 0.34f, h * 0.46f, w * 0.86f, h * 0.84f), dp(4), dp(4), paint);
            paint.clearShadowLayer();

            path.reset();
            path.moveTo(w * 0.28f, h * 0.48f);
            path.lineTo(w * 0.60f, h * 0.22f);
            path.lineTo(w * 0.92f, h * 0.48f);
            path.close();
            paint.setColor(Color.rgb(222, 58, 78));
            canvas.drawPath(path, paint);

            path.reset();
            path.moveTo(w * 0.34f, h * 0.48f);
            path.lineTo(w * 0.60f, h * 0.27f);
            path.lineTo(w * 0.86f, h * 0.48f);
            path.close();
            paint.setColor(Color.rgb(245, 106, 124));
            canvas.drawPath(path, paint);

            paint.setColor(Color.rgb(246, 229, 222));
            canvas.drawRoundRect(new RectF(w * 0.55f, h * 0.61f, w * 0.68f, h * 0.84f), dp(2), dp(2), paint);
            paint.setColor(Color.rgb(255, 193, 167));
            canvas.drawRoundRect(new RectF(w * 0.42f, h * 0.56f, w * 0.51f, h * 0.66f), dp(2), dp(2), paint);
            canvas.drawRoundRect(new RectF(w * 0.72f, h * 0.56f, w * 0.81f, h * 0.66f), dp(2), dp(2), paint);

            paint.setColor(Color.rgb(108, 194, 42));
            canvas.drawCircle(w * 0.20f, h * 0.61f, w * 0.10f, paint);
            canvas.drawCircle(w * 0.24f, h * 0.48f, w * 0.12f, paint);
            canvas.drawCircle(w * 0.29f, h * 0.61f, w * 0.10f, paint);
            paint.setColor(Color.rgb(96, 155, 58));
            canvas.drawRoundRect(new RectF(w * 0.235f, h * 0.62f, w * 0.265f, h * 0.86f), dp(2), dp(2), paint);

            paint.setColor(Color.argb(65, 216, 74, 99));
            canvas.drawOval(new RectF(w * 0.16f, h * 0.82f, w * 0.92f, h * 0.92f), paint);
        }
    }

