    private boolean isCurrentlyBookableService(String serviceId) {
        if (TextUtils.isEmpty(serviceId)) return false;
        String id = serviceId.trim().toLowerCase(Locale.US);
        return "ac".equals(id)
                || "electrician".equals(id)
                || "carpenter".equals(id)
                || "cleaning".equals(id)
                || "appliances".equals(id)
                || "plumbing".equals(id)
                || "laundry".equals(id);
    }

