    private boolean renderTrackBooking(Booking booking, Service primary, List<Booking> bookings) {
        screenContent.addView(trackBookingDetailsCard(booking, primary), margin(-1, -2, 20, 8, 20, 18));
        screenContent.addView(trackSectionTitle("Service Expert"), margin(-1, -2, 20, 0, 20, 10));
        screenContent.addView(trackServiceExpertCard(primary), margin(-1, -2, 20, 0, 20, 18));
        screenContent.addView(trackSectionTitle("Booking Progress"), margin(-1, -2, 20, 0, 20, 12));
        screenContent.addView(trackProgressTimeline(booking), margin(-1, -2, 20, 0, 20, 18));
        if ("on_the_way".equals(normalizeRemoteStatus(remoteBookingStatus))) {
            screenContent.addView(trackCoveredCard(), margin(-1, 88, 20, 0, 20, 18));
        }
        screenContent.addView(trackNeedHelpCard(), margin(-1, 76, 20, 0, 20, 22));
        return true;
    }

    private void renderBookingFlowContent(boolean freshConfirmed) {
        if (latestBooking == null) {
            addTrackTopBar();
            addEmptyBookingsState();
            return;
        }
        String status = bookingFlowStatus();
        boolean laundryBooking = "laundry".equals(latestBookingService().getId());
        boolean afterService = "completed".equals(status) && !"booking_completed".equals(currentScreen);
        bottomNav.setVisibility(afterService ? View.VISIBLE : View.GONE);
        floatingFooter.setVisibility(View.GONE);

        if ("pending".equals(status) && freshConfirmed && shouldShowBookingSuccessSplash()) {
            renderBookingSuccessSplash();
            return;
        }

        addBookingFlowTopBar();

        if (laundryBooking && !"pending".equals(status)) {
            renderLaundryOrderScreen(status);
            return;
        }

        if ("cleaning".equals(latestBookingService().getId())
                && !"pending".equals(status)
                && !"completed".equals(status)
                && !"amount_pending".equals(status)) {
            renderCleaningOrderScreen(status);
            return;
        }

        if ("completed".equals(status) && "booking_completed".equals(currentScreen)) {
            renderPaymentSuccessContent();
            return;
        }
        if ("completed".equals(status)) {
            renderAfterServiceContent();
            return;
        }
        if ("amount_pending".equals(status)) {
            if (isPaymentVerificationWaiting()) {
                renderPaymentVerificationWaitingContent();
                return;
            }
            renderServiceCompletedPaymentDueContent();
            return;
        }
        if ("pending".equals(status)) {
            renderPendingBookingFlow(freshConfirmed);
            return;
        }

        renderActiveBookingFlow(status);
    }

    private String bookingFlowStatus() {
        String status = normalizeRemoteStatus(remoteBookingStatus);
        if (("pending".equals(status) || "sent_to_partner".equals(status)) && partnerAssigned) {
            return "accepted";
        }
        return status;
    }

    private boolean shouldShowBookingSuccessSplash() {
        String id = bookingDisplayId();
        return !TextUtils.isEmpty(id) && !id.equals(bookingSuccessSplashShownForId);
    }

    private void renderBookingSuccessSplash() {
        String id = bookingDisplayId();
        bookingSuccessSplashShownForId = id;
        mainScroll.setFillViewport(true);
        screenContent.setPadding(0, 0, 0, 0);
        screenContent.setBackgroundColor(Color.WHITE);

        FrameLayout page = new FrameLayout(this);
        GradientDrawable pageBackground = new GradientDrawable(
                GradientDrawable.Orientation.TOP_BOTTOM,
                new int[]{Color.WHITE, Color.WHITE, Color.rgb(246, 255, 248)}
        );
        page.setBackground(pageBackground);
        page.setMinimumHeight(Math.max(dp(640), getResources().getDisplayMetrics().heightPixels - dp(26)));

        LinearLayout wrap = vertical();
        wrap.setGravity(Gravity.CENTER_HORIZONTAL);
        wrap.setPadding(dp(28), 0, dp(28), dp(44));
        wrap.setClipChildren(false);
        wrap.setClipToPadding(false);

        FrameLayout celebration = bookingSuccessCelebration();
        wrap.addView(celebration, new LinearLayout.LayoutParams(dp(260), dp(190)));
        TextView title = text("Booking Confirmed!", 26, Color.rgb(5, 35, 23), true);
        title.setGravity(Gravity.CENTER);
        wrap.addView(title, margin(-1, -2, 0, 2, 0, 9));
        TextView subtitle = text("Your booking has been received successfully.", 14, MUTED, false);
        subtitle.setGravity(Gravity.CENTER);
        subtitle.setLineSpacing(dp(3), 1f);
        subtitle.setMaxWidth(dp(260));
        wrap.addView(subtitle, margin(-1, -2, 12, 0, 12, 0));

        FrameLayout.LayoutParams wrapParams = new FrameLayout.LayoutParams(-1, -2, Gravity.TOP);
        wrapParams.topMargin = Math.max(dp(126), getResources().getDisplayMetrics().heightPixels / 5);
        page.addView(wrap, wrapParams);
        screenContent.addView(page, new LinearLayout.LayoutParams(-1, -1));

        celebration.setScaleX(0.76f);
        celebration.setScaleY(0.76f);
        celebration.setAlpha(0f);
        celebration.animate().alpha(1f).scaleX(1f).scaleY(1f).setDuration(540)
                .setInterpolator(new AccelerateDecelerateInterpolator()).start();
        title.setAlpha(0f);
        subtitle.setAlpha(0f);
        title.animate().alpha(1f).translationY(0f).setStartDelay(220L).setDuration(360L).start();
        subtitle.animate().alpha(1f).setStartDelay(330L).setDuration(360L).start();

        carouselHandler.postDelayed(() -> {
            if (!"booking_confirmed".equals(currentScreen) || latestBooking == null || !id.equals(bookingDisplayId())) {
                return;
            }
            ObjectAnimator scaleX = ObjectAnimator.ofFloat(page, View.SCALE_X, 1f, 0.9f);
            ObjectAnimator scaleY = ObjectAnimator.ofFloat(page, View.SCALE_Y, 1f, 0.9f);
            ObjectAnimator alpha = ObjectAnimator.ofFloat(page, View.ALPHA, 1f, 0f);
            AnimatorSet set = new AnimatorSet();
            set.playTogether(scaleX, scaleY, alpha);
            set.setDuration(430);
            set.setInterpolator(new AccelerateDecelerateInterpolator());
            set.addListener(new Animator.AnimatorListener() {
                @Override public void onAnimationStart(Animator animation) {}
                @Override public void onAnimationRepeat(Animator animation) {}
                @Override public void onAnimationCancel(Animator animation) {}
                @Override public void onAnimationEnd(Animator animation) {
                    if ("booking_confirmed".equals(currentScreen)) {
                        resetScreen();
                        renderBookingFlowContent(false);
                    }
                }
            });
            set.start();
        }, 1700L);
    }

    private FrameLayout bookingSuccessCelebration() {
        FrameLayout frame = new FrameLayout(this);
        frame.setClipChildren(false);
        frame.setClipToPadding(false);
        int[][] dots = {
                {28, 36, 6, Color.rgb(20, 177, 91)}, {60, 22, 4, Color.rgb(255, 191, 34)},
                {204, 30, 5, Color.rgb(42, 184, 107)}, {226, 72, 7, Color.rgb(247, 87, 112)},
                {35, 122, 5, Color.rgb(255, 181, 28)}, {218, 134, 5, Color.rgb(27, 165, 82)},
                {78, 154, 4, Color.rgb(42, 181, 215)}, {186, 158, 4, Color.rgb(255, 156, 38)},
                {18, 82, 3, Color.rgb(50, 185, 103)}, {239, 106, 3, Color.rgb(63, 129, 235)}
        };
        for (int[] dot : dots) {
            View spark = new View(this);
            spark.setBackground(round(dot[3], dp(Math.max(1, dot[2] / 2))));
            FrameLayout.LayoutParams params = new FrameLayout.LayoutParams(dp(dot[2]), dp(dot[2]));
            params.leftMargin = dp(dot[0]);
            params.topMargin = dp(dot[1]);
            frame.addView(spark, params);
            startScalePulse(spark, 0.7f, 1.18f, 900 + dot[0]);
        }
        View badge = bookingConfirmedBadge();
        frame.addView(badge, new FrameLayout.LayoutParams(dp(148), dp(148), Gravity.CENTER));
        return frame;
    }

    private void addBookingFlowTopBar() {
        String flowStatus = bookingFlowStatus();
        boolean laundryOrderHeader = latestBooking != null
                && "laundry".equals(latestBookingService().getId())
                && !"pending".equals(flowStatus);
        boolean cleaningOrderHeader = latestBooking != null
                && "cleaning".equals(latestBookingService().getId())
                && !"pending".equals(flowStatus);
        boolean findingHeader = "pending".equals(flowStatus);
        boolean trackingHeader = laundryOrderHeader || "pending".equals(flowStatus)
                || "accepted".equals(flowStatus)
                || "on_the_way".equals(flowStatus)
                || "arrived".equals(flowStatus)
                || "started".equals(flowStatus);
        int findingTopInset = trackingHeader ? bookingFindingTopInsetPx() : 0;
        LinearLayout row = horizontal();
        row.setGravity(Gravity.CENTER_VERTICAL);
        row.setClipChildren(false);
        row.setClipToPadding(false);
        int horizontalPadding = findingHeader ? 16 : (trackingHeader ? 18 : 24);
        int topPadding = findingHeader ? 4 : (trackingHeader ? 8 : 18);
        int bottomPadding = findingHeader ? 2 : (trackingHeader ? 8 : 6);
        row.setPadding(dp(horizontalPadding), dp(topPadding) + findingTopInset,
                dp(horizontalPadding), dp(bottomPadding));

        FrameLayout back = findingHeader
                ? bookingFindingPlainHeaderButton(BookingFindingArtworkView.BACK)
                : bookingFindingHeaderButton(BookingFindingArtworkView.BACK);
        back.setOnClickListener(view -> {
            if ("booking_completed".equals(currentScreen)) {
                showBookingsList();
            } else {
                showHome();
            }
        });
        addPressAnimation(back);
        int headerButtonSize = findingHeader ? 44 : 52;
        row.addView(back, new LinearLayout.LayoutParams(dp(headerButtonSize), dp(headerButtonSize)));

        LinearLayout center = vertical();
        center.setGravity(Gravity.CENTER);
        TextView title = text(trackingHeader && !findingHeader
                        ? (laundryOrderHeader ? "Laundry Order" : (cleaningOrderHeader ? "Booking Details" : "Booking Status")) : "", 19,
                Color.rgb(14, 24, 38), true);
        title.setGravity(Gravity.CENTER);
        title.setSingleLine(true);
        center.addView(title, new LinearLayout.LayoutParams(-1, -2));
        if (trackingHeader && !findingHeader && !laundryOrderHeader) {
            TextView subtitle = text(cleaningOrderHeader ? "Track your cleaning service" : "Live updates about your service", 10, Color.rgb(111, 116, 124), false);
            subtitle.setGravity(Gravity.CENTER);
            subtitle.setSingleLine(true);
            center.addView(subtitle, margin(-1, -2, 0, 2, 0, 0));
        }
        row.addView(center, new LinearLayout.LayoutParams(0, -2, 1));

        LinearLayout help = findingHeader ? bookingFindingPlainHelpButton() : bookingFindingHelpButton();
        help.setOnClickListener(view -> showSupportChat("I need help with my booking " + bookingDisplayId() + "."));
        addPressAnimation(help);
        int helpWidth = findingHeader ? 78 : (trackingHeader ? 88 : 96);
        row.addView(help, new LinearLayout.LayoutParams(dp(helpWidth), dp(headerButtonSize)));
        screenContent.addView(row, new LinearLayout.LayoutParams(-1, -2));
    }

    private int bookingFindingTopInsetPx() {
        // The activity root consumes system-bar and display-cutout insets once.
        return dp(2);
    }

    private int bookingBottomInsetPx() {
        // The activity root already applies the navigation-bar inset.
        return 0;
    }

    private void renderPendingBookingFlow(boolean freshConfirmed) {
        mainScroll.setFillViewport(true);
        screenContent.setPadding(0, 0, 0, bookingBottomInsetPx() + dp(14));
        screenContent.setBackground(bookingFindingPageBackground());
        mainScroll.setOverScrollMode(View.OVER_SCROLL_NEVER);

        LinearLayout hero = vertical();
        hero.setGravity(Gravity.CENTER_HORIZONTAL);
        hero.setPadding(dp(20), 0, dp(20), 0);
        boolean laundry = "laundry".equals(latestBookingService().getId());
        if (!laundry) {
            View radar = new BookingFindingArtworkView(BookingFindingArtworkView.HERO);
            hero.addView(radar, new LinearLayout.LayoutParams(-1, dp(148)));
        }

        TextView heading = text(laundry ? "Finding the best\nlaundry service for you..." : "Finding the best service\nfor you...", 24, Color.rgb(6, 27, 47), true);
        if (laundry) {
            SpannableString styled = new SpannableString("Finding the best\nlaundry service for you...");
            int start = styled.toString().indexOf("laundry");
            styled.setSpan(new ForegroundColorSpan(BOOKING_THEME), start, start + "laundry service".length(), Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
            heading.setText(styled);
        }
        heading.setGravity(Gravity.CENTER);
        heading.setLineSpacing(dp(1), 1f);
        hero.addView(heading, margin(-1, -2, 0, 0, 0, 6));

        TextView subtitle = text(laundry ? "Searching nearby verified laundry services" : "Searching nearby verified services", 14, Color.rgb(74, 86, 99), false);
        subtitle.setGravity(Gravity.CENTER);
        hero.addView(subtitle);

        if (laundry) {
            View radar = new BookingFindingArtworkView(BookingFindingArtworkView.LAUNDRY_RADAR);
            hero.addView(radar, margin(-1, 300, 0, 8, 0, 2));
            hero.addView(laundryFindingLiveCard(), margin(-1, -2, 4, 0, 4, 8));
        } else {
            View city = new BookingFindingArtworkView(BookingFindingArtworkView.CITY);
            hero.addView(city, margin(-1, 82, 0, 5, 0, 0));
        }
        screenContent.addView(hero, margin(-1, -2, 0, 0, 0, 2));

        screenContent.addView(bookingFindingControlCard(), margin(-1, -2, 16, 0, 16, 6));
        if (laundry) {
            screenContent.addView(laundryFindingProgressBar(), margin(-1, -2, 16, 10, 16, 0));
        }
    }

