    private final class BookingFindingArtworkView extends View {
        private static final int HERO = 1;
        private static final int CITY = 2;
        private static final int SERVICE = 3;
        private static final int CALENDAR = 4;
        private static final int LOCATION = 5;
        private static final int COPY = 6;
        private static final int BELL = 7;
        private static final int SHIELD = 8;
        private static final int HEADSET = 9;
        private static final int BACK = 10;
        private static final int PARTNER_AVATAR = 11;
        private static final int PHONE = 12;
        private static final int CHAT = 13;
        private static final int CLOCK = 14;
        private static final int SCOOTER = 15;
        private static final int TOOLS = 16;
        private static final int LAUNDRY_RADAR = 17;
        private static final int RADAR_SIGNAL = 18;
        private static final int PICKUP_BAG = 19;
        private static final int HOME = 20;
        private static final int NO_TINT = Integer.MIN_VALUE;
        private final int artwork;
        private final int tintColor;
        private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final Path path = new Path();
        private ValueAnimator radarAnimator;
        private float radarPhase;

        BookingFindingArtworkView(int artwork) {
            this(artwork, NO_TINT);
        }

        BookingFindingArtworkView(int artwork, int tintColor) {
            super(MainActivity.this);
            this.artwork = artwork;
            this.tintColor = tintColor;
            setLayerType(View.LAYER_TYPE_SOFTWARE, null);
        }

        @Override
        protected void onAttachedToWindow() {
            super.onAttachedToWindow();
            if ((artwork != HERO && artwork != LAUNDRY_RADAR && artwork != SCOOTER && artwork != TOOLS) || radarAnimator != null) return;
            radarAnimator = ValueAnimator.ofFloat(0f, 360f);
            radarAnimator.setDuration(2600L);
            radarAnimator.setRepeatCount(ValueAnimator.INFINITE);
            radarAnimator.setInterpolator(new LinearInterpolator());
            radarAnimator.addUpdateListener(animation -> {
                radarPhase = (float) animation.getAnimatedValue();
                invalidate();
            });
            radarAnimator.start();
        }

        @Override
        protected void onDetachedFromWindow() {
            if (radarAnimator != null) {
                radarAnimator.cancel();
                radarAnimator.removeAllUpdateListeners();
                radarAnimator = null;
            }
            super.onDetachedFromWindow();
        }

        @Override
        protected void onDraw(Canvas canvas) {
            super.onDraw(canvas);
            float w = getWidth();
            float h = getHeight();
            if (w <= 0 || h <= 0) return;
            if (artwork == HERO) drawHero(canvas, w, h);
            else if (artwork == LAUNDRY_RADAR) drawLaundryRadar(canvas, w, h);
            else if (artwork == CITY) drawCity(canvas, w, h);
            else if (artwork == PARTNER_AVATAR) drawPartnerAvatar(canvas, w, h);
            else if (artwork == SCOOTER) drawScooterBadge(canvas, w, h);
            else if (artwork == TOOLS) drawToolsBadge(canvas, w, h);
            else drawLineIcon(canvas, w, h, artwork);
        }

        private void drawHero(Canvas canvas, float w, float h) {
            float cx = w * 0.50f;
            float cy = h * 0.48f;
            float base = Math.min(w, h);
            double radians = Math.toRadians(radarPhase);
            float pulse = (float) ((Math.sin(radians * 2d) + 1d) * 0.5d);

            paint.setStyle(Paint.Style.FILL);
            paint.setColor(Color.argb(22, 255, 63, 95));
            RectF sweepBounds = new RectF(cx - base * .43f, cy - base * .43f,
                    cx + base * .43f, cy + base * .43f);
            canvas.drawArc(sweepBounds, radarPhase - 42f, 50f, true, paint);

            paint.setStyle(Paint.Style.STROKE);
            paint.setStrokeWidth(Math.max(1f, base * 0.008f));
            paint.setColor(Color.argb(120 + Math.round(60 * pulse), 255, 164, 181));
            canvas.drawCircle(cx, cy, base * (.46f + .025f * pulse), paint);
            paint.setColor(Color.argb(105 + Math.round(55 * (1f - pulse)), 255, 203, 213));
            canvas.drawCircle(cx, cy, base * (.36f + .020f * (1f - pulse)), paint);
            paint.setColor(Color.argb(78, 255, 214, 222));
            canvas.drawCircle(cx, cy, base * .27f, paint);

            paint.setStyle(Paint.Style.FILL);
            paint.setColor(Color.rgb(255, 233, 237));
            paint.setShadowLayer(base * .035f, 0f, base * .018f, Color.argb(50, 224, 70, 95));
            canvas.drawCircle(cx, cy, base * 0.275f, paint);
            paint.clearShadowLayer();

            // Verified service professional.
            paint.setColor(Color.rgb(247, 186, 157));
            canvas.drawCircle(cx, cy - base * .055f, base * .072f, paint);
            paint.setColor(Color.rgb(247, 105, 124));
            path.reset();
            path.moveTo(cx - base * .092f, cy - base * .075f);
            path.quadTo(cx, cy - base * .17f, cx + base * .092f, cy - base * .075f);
            path.lineTo(cx + base * .082f, cy - base * .045f);
            path.lineTo(cx - base * .082f, cy - base * .045f);
            path.close();
            canvas.drawPath(path, paint);
            canvas.drawRoundRect(new RectF(cx - base * .125f, cy + base * .02f,
                    cx + base * .125f, cy + base * .185f), base * .04f, base * .04f, paint);

            paint.setColor(Color.WHITE);
            path.reset();
            path.moveTo(cx - base * .025f, cy - base * .104f);
            path.lineTo(cx - base * .005f, cy - base * .084f);
            path.lineTo(cx + base * .031f, cy - base * .125f);
            canvas.drawPath(path, paint);

            paint.setStyle(Paint.Style.STROKE);
            paint.setStrokeWidth(base * .024f);
            paint.setStrokeCap(Paint.Cap.ROUND);
            canvas.drawLine(cx - base * .082f, cy + base * .065f, cx + base * .082f, cy + base * .065f, paint);
            paint.setStrokeCap(Paint.Cap.BUTT);

            // Search lens and verified check.
            float lensX = cx + base * .205f;
            float lensY = cy + base * .145f;
            paint.setStyle(Paint.Style.FILL);
            paint.setColor(Color.WHITE);
            paint.setShadowLayer(base * .025f, 0f, base * .012f, Color.argb(70, 170, 25, 55));
            canvas.drawCircle(lensX, lensY, base * .145f, paint);
            paint.clearShadowLayer();
            paint.setStyle(Paint.Style.STROKE);
            paint.setStrokeWidth(base * .025f);
            paint.setColor(Color.rgb(240, 70, 95));
            canvas.drawCircle(lensX, lensY, base * .145f, paint);
            paint.setStrokeWidth(base * .040f);
            paint.setStrokeCap(Paint.Cap.ROUND);
            canvas.drawLine(lensX + base * .105f, lensY + base * .105f,
                    lensX + base * .205f, lensY + base * .205f, paint);
            paint.setStrokeWidth(base * .028f);
            path.reset();
            path.moveTo(lensX - base * .065f, lensY);
            path.lineTo(lensX - base * .015f, lensY + base * .050f);
            path.lineTo(lensX + base * .078f, lensY - base * .058f);
            canvas.drawPath(path, paint);
            paint.setStrokeCap(Paint.Cap.BUTT);

            paint.setStyle(Paint.Style.FILL);
            paint.setColor(BOOKING_THEME);
            float orbitRadius = base * .42f;
            float orbitX = cx + (float) Math.cos(radians) * orbitRadius;
            float orbitY = cy + (float) Math.sin(radians) * orbitRadius;
            paint.setShadowLayer(base * .035f, 0f, 0f, Color.argb(120, 225, 42, 83));
            canvas.drawCircle(orbitX, orbitY, base * (.022f + .007f * pulse), paint);
            paint.clearShadowLayer();
            drawDiamond(canvas, w * .20f, h * .31f, base * .025f, Color.rgb(255, 176, 191));
            drawDiamond(canvas, w * .83f, h * .37f, base * .022f, Color.rgb(255, 190, 203));
            drawDiamond(canvas, w * .16f, h * .66f, base * .014f, Color.rgb(255, 211, 220));
            drawDiamond(canvas, w * .84f, h * .69f, base * .014f, Color.rgb(255, 211, 220));
        }

        private void drawLaundryRadar(Canvas canvas, float w, float h) {
            float cx = w * .50f;
            float cy = h * .48f;
            float radius = Math.min(w * .34f, h * .38f);
            double radians = Math.toRadians(radarPhase);
            float pulse = (float) ((Math.sin(radians * 2d) + 1d) * .5d);

            paint.setShader(null);
            paint.setStyle(Paint.Style.FILL);
            paint.setColor(Color.rgb(255, 239, 243));
            paint.setShadowLayer(dp(10), 0f, dp(6), Color.argb(34, 164, 48, 78));
            canvas.drawCircle(cx, cy, radius, paint);
            paint.clearShadowLayer();

            paint.setColor(Color.argb(105, 245, 72, 112));
            RectF radarBounds = new RectF(cx - radius, cy - radius, cx + radius, cy + radius);
            canvas.drawArc(radarBounds, radarPhase - 34f, 42f, true, paint);

            paint.setStyle(Paint.Style.STROKE);
            paint.setStrokeWidth(dp(1));
            for (int ring = 1; ring <= 4; ring++) {
                paint.setColor(ring == 4 ? Color.argb(130, 249, 165, 184) : Color.argb(190, 255, 255, 255));
                canvas.drawCircle(cx, cy, radius * ring / 4f, paint);
            }

            float[][] points = {
                    {-.58f, -.42f}, {.25f, -.55f}, {.62f, -.22f},
                    {-.70f, .34f}, {.20f, .52f}, {.60f, .45f}, {-.12f, .70f}
            };
            paint.setStyle(Paint.Style.FILL);
            for (int index = 0; index < points.length; index++) {
                float dotX = cx + radius * points[index][0];
                float dotY = cy + radius * points[index][1];
                paint.setColor(Color.argb(195, 245, 73, 112));
                paint.setShadowLayer(dp(5), 0f, 0f, Color.argb(120, 240, 65, 104));
                canvas.drawCircle(dotX, dotY, dp(index % 3 == 0 ? 4 : 3), paint);
                paint.clearShadowLayer();
            }

            paint.setColor(Color.WHITE);
            paint.setShadowLayer(dp(7), 0f, dp(3), Color.argb(70, 180, 45, 79));
            canvas.drawCircle(cx, cy, dp(30), paint);
            paint.clearShadowLayer();
            paint.setColor(BOOKING_THEME);
            canvas.drawCircle(cx, cy, dp(23), paint);
            drawLaundryMachineGlyph(canvas, cx, cy, dp(15), Color.WHITE);

            drawLaundryRadarServiceCard(canvas, w * .01f, h * .08f, "CleanWave", "1.2 km");
            drawLaundryRadarServiceCard(canvas, w * .66f, h * .49f, "LaundryPro", "1.5 km");
            drawLaundryRadarServiceCard(canvas, w * .07f, h * .72f, "FreshFold", "0.8 km");

            paint.setStyle(Paint.Style.FILL);
            paint.setColor(BOOKING_THEME);
            float orbitX = cx + (float) Math.cos(radians) * radius * .86f;
            float orbitY = cy + (float) Math.sin(radians) * radius * .86f;
            paint.setShadowLayer(dp(5), 0f, 0f, Color.argb(120, 231, 39, 83));
            canvas.drawCircle(orbitX, orbitY, dp(3) + pulse, paint);
            paint.clearShadowLayer();
        }

        private void drawLaundryRadarServiceCard(Canvas canvas, float left, float top, String name, String distance) {
            float width = dp(112);
            float height = dp(52);
            if (left + width > getWidth() - dp(2)) left = getWidth() - width - dp(2);
            RectF card = new RectF(left, top, left + width, top + height);
            paint.setStyle(Paint.Style.FILL);
            paint.setColor(Color.WHITE);
            paint.setShadowLayer(dp(6), 0f, dp(3), Color.argb(38, 54, 25, 33));
            canvas.drawRoundRect(card, dp(15), dp(15), paint);
            paint.clearShadowLayer();

            float iconCx = left + dp(21);
            float iconCy = top + height / 2f;
            paint.setColor(Color.rgb(255, 240, 244));
            canvas.drawCircle(iconCx, iconCy, dp(13), paint);
            drawLaundryMachineGlyph(canvas, iconCx, iconCy, dp(8), BOOKING_THEME);

            paint.setTypeface(Typeface.create("sans-serif", Typeface.BOLD));
            paint.setTextSize(dp(10));
            paint.setColor(Color.rgb(26, 31, 39));
            canvas.drawText(name, left + dp(40), top + dp(22), paint);
            paint.setTypeface(Typeface.create("sans-serif", Typeface.NORMAL));
            paint.setTextSize(dp(9));
            paint.setColor(Color.rgb(104, 105, 111));
            canvas.drawText(distance, left + dp(40), top + dp(37), paint);
        }

        private void drawLaundryMachineGlyph(Canvas canvas, float cx, float cy, float size, int color) {
            paint.setStyle(Paint.Style.STROKE);
            paint.setStrokeWidth(Math.max(dp(1), size * .12f));
            paint.setStrokeCap(Paint.Cap.ROUND);
            paint.setColor(color);
            RectF body = new RectF(cx - size * .62f, cy - size * .70f, cx + size * .62f, cy + size * .70f);
            canvas.drawRoundRect(body, size * .14f, size * .14f, paint);
            canvas.drawLine(cx - size * .48f, cy - size * .33f, cx + size * .48f, cy - size * .33f, paint);
            canvas.drawCircle(cx, cy + size * .14f, size * .31f, paint);
            paint.setStyle(Paint.Style.FILL);
            canvas.drawCircle(cx + size * .37f, cy - size * .51f, size * .07f, paint);
            paint.setStrokeCap(Paint.Cap.BUTT);
        }

        private void drawCity(Canvas canvas, float w, float h) {
            paint.setStyle(Paint.Style.FILL);
            paint.setColor(Color.rgb(255, 246, 248));
            float ground = h * .88f;
            canvas.drawRect(w * .08f, h * .40f, w * .25f, ground, paint);
            canvas.drawRect(w * .25f, h * .56f, w * .40f, ground, paint);
            canvas.drawRect(w * .61f, h * .49f, w * .78f, ground, paint);
            canvas.drawRect(w * .77f, h * .61f, w * .93f, ground, paint);
            paint.setColor(Color.rgb(255, 230, 235));
            for (int i = 0; i < 3; i++) {
                canvas.drawRoundRect(new RectF(w * (.12f + i * .045f), h * .51f,
                        w * (.14f + i * .045f), h * .58f), 2, 2, paint);
                canvas.drawRoundRect(new RectF(w * (.66f + i * .045f), h * .60f,
                        w * (.68f + i * .045f), h * .67f), 2, 2, paint);
            }
            paint.setColor(Color.rgb(255, 213, 222));
            canvas.drawCircle(w * .28f, ground, h * .13f, paint);
            canvas.drawCircle(w * .72f, ground, h * .13f, paint);
            paint.setStyle(Paint.Style.STROKE);
            paint.setStrokeWidth(Math.max(2f, h * .025f));
            paint.setStrokeCap(Paint.Cap.ROUND);
            canvas.drawLine(w * .22f, h * .70f, w * .22f, ground, paint);
            canvas.drawLine(w * .78f, h * .70f, w * .78f, ground, paint);
            paint.setStrokeCap(Paint.Cap.BUTT);

            paint.setStyle(Paint.Style.FILL);
            paint.setColor(Color.rgb(255, 167, 185));
            path.reset();
            path.moveTo(w * .50f, h * .16f);
            path.cubicTo(w * .38f, h * .16f, w * .34f, h * .38f, w * .50f, h * .79f);
            path.cubicTo(w * .66f, h * .38f, w * .62f, h * .16f, w * .50f, h * .16f);
            path.close();
            canvas.drawPath(path, paint);
            paint.setColor(Color.WHITE);
            canvas.drawCircle(w * .50f, h * .34f, h * .10f, paint);
            paint.setColor(Color.rgb(255, 232, 237));
            canvas.drawOval(new RectF(w * .39f, h * .80f, w * .61f, h * .93f), paint);

            paint.setStyle(Paint.Style.STROKE);
            paint.setStrokeWidth(Math.max(1f, h * .014f));
            paint.setStrokeCap(Paint.Cap.ROUND);
            paint.setColor(Color.rgb(255, 139, 158));
            paint.setPathEffect(new android.graphics.DashPathEffect(new float[]{h * .055f, h * .035f}, 0f));
            path.reset();
            path.moveTo(w * .18f, h * .82f);
            path.cubicTo(w * .30f, h * .64f, w * .36f, h * .91f, w * .46f, h * .82f);
            path.cubicTo(w * .58f, h * .68f, w * .66f, h * .91f, w * .82f, h * .78f);
            canvas.drawPath(path, paint);
            paint.setPathEffect(null);
            paint.setStrokeCap(Paint.Cap.BUTT);
        }

        private void drawPartnerAvatar(Canvas canvas, float w, float h) {
            float s = Math.min(w, h);
            paint.setStyle(Paint.Style.FILL);
            paint.setColor(Color.rgb(255, 239, 242));
            canvas.drawCircle(w / 2f, h / 2f, s * .49f, paint);
            paint.setColor(BOOKING_THEME);
            canvas.drawOval(new RectF(w * .19f, h * .58f, w * .81f, h * 1.03f), paint);
            paint.setColor(Color.rgb(238, 172, 112));
            canvas.drawCircle(w * .50f, h * .40f, s * .18f, paint);
            paint.setColor(Color.rgb(43, 33, 25));
            canvas.drawArc(new RectF(w * .31f, h * .18f, w * .69f, h * .54f), 180, 180, true, paint);
            paint.setColor(LOGIN_ROSE_DARK);
            canvas.drawArc(new RectF(w * .25f, h * .10f, w * .75f, h * .38f), 180, 180, true, paint);
            canvas.drawRect(w * .30f, h * .22f, w * .71f, h * .29f, paint);
            paint.setColor(Color.WHITE);
            canvas.drawCircle(w * .50f, h * .20f, s * .035f, paint);
            paint.setStyle(Paint.Style.STROKE);
            paint.setStrokeWidth(Math.max(2f, s * .025f));
            paint.setStrokeCap(Paint.Cap.ROUND);
            paint.setColor(Color.rgb(70, 45, 30));
            canvas.drawLine(w * .42f, h * .40f, w * .44f, h * .40f, paint);
            canvas.drawLine(w * .56f, h * .40f, w * .58f, h * .40f, paint);
            canvas.drawArc(new RectF(w * .43f, h * .43f, w * .57f, h * .52f), 10, 160, false, paint);
            paint.setColor(Color.WHITE);
            paint.setStrokeWidth(s * .035f);
            canvas.drawLine(w * .71f, h * .69f, w * .71f, h * .88f, paint);
            canvas.drawLine(w * .66f, h * .76f, w * .76f, h * .76f, paint);
            paint.setStrokeCap(Paint.Cap.BUTT);
        }

        private void drawStatusBadgeShell(Canvas canvas, float w, float h, float cx, float cy, float base) {
            double radians = Math.toRadians(radarPhase);
            float pulse = (float) ((Math.sin(radians * 2d) + 1d) * 0.5d);

            paint.setShader(null);
            paint.setStyle(Paint.Style.STROKE);
            paint.setStrokeWidth(Math.max(1f, base * .010f));
            paint.setColor(Color.argb(120 + Math.round(60 * pulse), 255, 164, 181));
            canvas.drawCircle(cx, cy, base * (.47f + .035f * pulse), paint);
            paint.setColor(Color.argb(95 + Math.round(45 * (1f - pulse)), 255, 207, 216));
            canvas.drawCircle(cx, cy, base * (.34f + .025f * (1f - pulse)), paint);

            paint.setStyle(Paint.Style.FILL);
            paint.setShader(new LinearGradient(cx - base * .26f, cy - base * .26f,
                    cx + base * .26f, cy + base * .26f,
                    BOOKING_THEME, LOGIN_ROSE_DARK, Shader.TileMode.CLAMP));
            paint.setShadowLayer(base * .045f, 0f, base * .018f, Color.argb(70, 192, 21, 65));
            canvas.drawCircle(cx, cy, base * .255f, paint);
            paint.clearShadowLayer();
            paint.setShader(null);

            paint.setColor(BOOKING_THEME);
            float orbitRadius = base * .48f;
            float orbitX = cx + (float) Math.cos(radians) * orbitRadius;
            float orbitY = cy + (float) Math.sin(radians) * orbitRadius;
            canvas.drawCircle(orbitX, orbitY, base * (.022f + .006f * pulse), paint);
        }

        private void drawScooterBadge(Canvas canvas, float w, float h) {
            float base = Math.min(w, h);
            float cx = w * .50f;
            float cy = h * .50f;
            drawStatusBadgeShell(canvas, w, h, cx, cy, base);

            paint.setShader(null);
            paint.setStyle(Paint.Style.FILL);
            paint.setColor(Color.WHITE);
            canvas.drawCircle(cx - base * .095f, cy + base * .115f, base * .045f, paint);
            canvas.drawCircle(cx + base * .145f, cy + base * .115f, base * .045f, paint);
            canvas.drawRoundRect(new RectF(cx - base * .17f, cy + base * .005f,
                    cx + base * .18f, cy + base * .095f), base * .04f, base * .04f, paint);
            path.reset();
            path.moveTo(cx + base * .03f, cy + base * .005f);
            path.lineTo(cx + base * .17f, cy - base * .085f);
            path.lineTo(cx + base * .23f, cy - base * .055f);
            path.lineTo(cx + base * .13f, cy + base * .035f);
            path.close();
            canvas.drawPath(path, paint);

            paint.setColor(Color.rgb(249, 185, 117));
            canvas.drawCircle(cx - base * .035f, cy - base * .145f, base * .050f, paint);
            paint.setColor(Color.WHITE);
            canvas.drawRoundRect(new RectF(cx - base * .095f, cy - base * .095f,
                    cx + base * .055f, cy + base * .030f), base * .035f, base * .035f, paint);
            paint.setColor(LOGIN_ROSE_DARK);
            canvas.drawArc(new RectF(cx - base * .095f, cy - base * .205f,
                    cx + base * .060f, cy - base * .105f), 180, 180, true, paint);

            paint.setStyle(Paint.Style.STROKE);
            paint.setColor(Color.WHITE);
            paint.setStrokeWidth(base * .028f);
            paint.setStrokeCap(Paint.Cap.ROUND);
            canvas.drawLine(cx - base * .015f, cy - base * .035f, cx + base * .095f, cy + base * .028f, paint);
            canvas.drawLine(cx - base * .005f, cy + base * .020f, cx - base * .100f, cy + base * .112f, paint);
            paint.setStrokeCap(Paint.Cap.BUTT);
        }

        private void drawToolsBadge(Canvas canvas, float w, float h) {
            float base = Math.min(w, h);
            float cx = w * .50f;
            float cy = h * .50f;
            drawStatusBadgeShell(canvas, w, h, cx, cy, base);

            paint.setShader(null);
            paint.setStyle(Paint.Style.STROKE);
            paint.setStrokeCap(Paint.Cap.ROUND);
            paint.setStrokeJoin(Paint.Join.ROUND);
            paint.setStrokeWidth(base * .052f);
            paint.setColor(Color.WHITE);
            canvas.drawLine(cx - base * .135f, cy + base * .120f, cx + base * .125f, cy - base * .140f, paint);
            canvas.drawLine(cx - base * .125f, cy - base * .135f, cx + base * .140f, cy + base * .130f, paint);

            paint.setStrokeWidth(base * .036f);
            canvas.drawLine(cx + base * .088f, cy - base * .103f, cx + base * .155f, cy - base * .170f, paint);
            canvas.drawLine(cx + base * .113f, cy - base * .078f, cx + base * .180f, cy - base * .145f, paint);

            paint.setStyle(Paint.Style.FILL);
            canvas.drawCircle(cx - base * .145f, cy + base * .145f, base * .045f, paint);
            canvas.drawCircle(cx + base * .145f, cy + base * .145f, base * .045f, paint);
            paint.setStrokeCap(Paint.Cap.BUTT);
        }

        private void drawLineIcon(Canvas canvas, float w, float h, int type) {
            float s = Math.min(w, h);
            float cx = w / 2f;
            float cy = h / 2f;
            int green = tintColor != NO_TINT
                    ? tintColor
                    : (type == BACK ? Color.rgb(8, 16, 34) : (type == BELL ? Color.WHITE : BOOKING_THEME));
            paint.setShader(null);
            paint.setStyle(Paint.Style.STROKE);
            paint.setStrokeWidth(Math.max(2f, s * .085f));
            paint.setStrokeCap(Paint.Cap.ROUND);
            paint.setStrokeJoin(Paint.Join.ROUND);
            paint.setColor(green);
            path.reset();
            if (type == BACK) {
                path.moveTo(w * .62f, h * .18f); path.lineTo(w * .34f, h * .50f); path.lineTo(w * .62f, h * .82f);
                canvas.drawPath(path, paint);
            } else if (type == HEADSET) {
                canvas.drawArc(new RectF(w * .17f, h * .18f, w * .83f, h * .78f), 190, 160, false, paint);
                canvas.drawLine(w * .17f, h * .51f, w * .17f, h * .72f, paint);
                canvas.drawLine(w * .83f, h * .51f, w * .83f, h * .72f, paint);
                canvas.drawLine(w * .83f, h * .72f, w * .69f, h * .82f, paint);
            } else if (type == COPY) {
                canvas.drawRoundRect(new RectF(w * .22f, h * .28f, w * .67f, h * .78f), s * .04f, s * .04f, paint);
                canvas.drawRoundRect(new RectF(w * .36f, h * .15f, w * .81f, h * .65f), s * .04f, s * .04f, paint);
            } else if (type == CALENDAR) {
                canvas.drawRoundRect(new RectF(w * .16f, h * .22f, w * .84f, h * .83f), s * .07f, s * .07f, paint);
                canvas.drawLine(w * .16f, h * .41f, w * .84f, h * .41f, paint);
                canvas.drawLine(w * .34f, h * .13f, w * .34f, h * .30f, paint);
                canvas.drawLine(w * .66f, h * .13f, w * .66f, h * .30f, paint);
                paint.setStyle(Paint.Style.FILL);
                canvas.drawCircle(w * .34f, h * .57f, s * .045f, paint); canvas.drawCircle(w * .55f, h * .57f, s * .045f, paint);
                canvas.drawCircle(w * .34f, h * .72f, s * .045f, paint); canvas.drawCircle(w * .55f, h * .72f, s * .045f, paint);
            } else if (type == LOCATION) {
                path.moveTo(cx, h * .88f);
                path.cubicTo(w * .22f, h * .58f, w * .20f, h * .18f, cx, h * .14f);
                path.cubicTo(w * .80f, h * .18f, w * .78f, h * .58f, cx, h * .88f);
                path.close(); canvas.drawPath(path, paint);
                canvas.drawCircle(cx, h * .41f, s * .10f, paint);
            } else if (type == BELL) {
                path.moveTo(w * .26f, h * .69f); path.quadTo(w * .34f, h * .61f, w * .34f, h * .43f);
                path.quadTo(w * .34f, h * .22f, cx, h * .22f); path.quadTo(w * .66f, h * .22f, w * .66f, h * .43f);
                path.quadTo(w * .66f, h * .61f, w * .74f, h * .69f); canvas.drawPath(path, paint);
                canvas.drawLine(w * .26f, h * .69f, w * .74f, h * .69f, paint);
                canvas.drawArc(new RectF(w * .42f, h * .65f, w * .58f, h * .84f), 0, 180, false, paint);
            } else if (type == SHIELD) {
                path.moveTo(cx, h * .12f); path.lineTo(w * .79f, h * .25f); path.lineTo(w * .74f, h * .61f);
                path.quadTo(w * .69f, h * .78f, cx, h * .90f); path.quadTo(w * .31f, h * .78f, w * .26f, h * .61f);
                path.lineTo(w * .21f, h * .25f); path.close(); canvas.drawPath(path, paint);
                path.reset(); path.moveTo(w * .36f, h * .50f); path.lineTo(w * .47f, h * .62f); path.lineTo(w * .67f, h * .38f); canvas.drawPath(path, paint);
            } else if (type == SERVICE) {
                canvas.drawRoundRect(new RectF(w * .12f, h * .26f, w * .88f, h * .67f), s * .07f, s * .07f, paint);
                canvas.drawLine(w * .18f, h * .73f, w * .82f, h * .73f, paint);
                canvas.drawLine(w * .25f, h * .74f, w * .25f, h * .82f, paint); canvas.drawLine(w * .75f, h * .74f, w * .75f, h * .82f, paint);
                paint.setStyle(Paint.Style.FILL); canvas.drawCircle(w * .75f, h * .45f, s * .035f, paint);
            } else if (type == PHONE) {
                path.moveTo(w * .25f, h * .18f);
                path.cubicTo(w * .19f, h * .22f, w * .18f, h * .35f, w * .23f, h * .47f);
                path.cubicTo(w * .35f, h * .69f, w * .56f, h * .82f, w * .76f, h * .82f);
                path.cubicTo(w * .85f, h * .79f, w * .88f, h * .68f, w * .81f, h * .62f);
                path.lineTo(w * .68f, h * .52f);
                path.cubicTo(w * .63f, h * .49f, w * .56f, h * .55f, w * .52f, h * .58f);
                path.cubicTo(w * .43f, h * .53f, w * .37f, h * .46f, w * .33f, h * .37f);
                path.cubicTo(w * .37f, h * .33f, w * .42f, h * .26f, w * .38f, h * .21f);
                path.close();
                canvas.drawPath(path, paint);
            } else if (type == CHAT) {
                canvas.drawOval(new RectF(w * .13f, h * .17f, w * .87f, h * .72f), paint);
                path.moveTo(w * .30f, h * .68f); path.lineTo(w * .22f, h * .88f); path.lineTo(w * .48f, h * .72f); canvas.drawPath(path, paint);
                paint.setStyle(Paint.Style.FILL);
                canvas.drawCircle(w * .37f, h * .45f, s * .035f, paint);
                canvas.drawCircle(w * .50f, h * .45f, s * .035f, paint);
                canvas.drawCircle(w * .63f, h * .45f, s * .035f, paint);
            } else if (type == CLOCK) {
                canvas.drawCircle(cx, cy, s * .34f, paint);
                canvas.drawLine(cx, cy, cx, h * .28f, paint);
                canvas.drawLine(cx, cy, w * .68f, h * .62f, paint);
            } else if (type == RADAR_SIGNAL) {
                canvas.drawArc(new RectF(w * .10f, h * .10f, w * .90f, h * .90f), 205, 130, false, paint);
                canvas.drawArc(new RectF(w * .24f, h * .24f, w * .76f, h * .76f), 205, 130, false, paint);
                canvas.drawArc(new RectF(w * .38f, h * .38f, w * .62f, h * .62f), 205, 130, false, paint);
                paint.setStyle(Paint.Style.FILL);
                canvas.drawCircle(cx, h * .68f, s * .08f, paint);
            } else if (type == PICKUP_BAG) {
                canvas.drawRoundRect(new RectF(w * .22f, h * .34f, w * .78f, h * .86f), s * .07f, s * .07f, paint);
                canvas.drawArc(new RectF(w * .34f, h * .13f, w * .66f, h * .49f), 180, 180, false, paint);
            } else if (type == HOME) {
                path.moveTo(w * .13f, h * .47f);
                path.lineTo(cx, h * .14f);
                path.lineTo(w * .87f, h * .47f);
                path.moveTo(w * .23f, h * .43f);
                path.lineTo(w * .23f, h * .86f);
                path.lineTo(w * .77f, h * .86f);
                path.lineTo(w * .77f, h * .43f);
                canvas.drawPath(path, paint);
                canvas.drawRect(w * .44f, h * .62f, w * .58f, h * .86f, paint);
            }
            paint.setStrokeCap(Paint.Cap.BUTT);
        }

        private void drawDiamond(Canvas canvas, float cx, float cy, float radius, int color) {
            paint.setStyle(Paint.Style.FILL);
            paint.setColor(color);
            path.reset();
            path.moveTo(cx, cy - radius); path.lineTo(cx + radius, cy); path.lineTo(cx, cy + radius); path.lineTo(cx - radius, cy); path.close();
            canvas.drawPath(path, paint);
        }
    }

    private void renderActiveBookingFlow(String status) {
        renderBookingTrackingScreen(status);
    }

    private void renderLaundryOrderScreen(String rawStatus) {
        String status = normalizeRemoteStatus(rawStatus);
        mainScroll.setFillViewport(true);
        screenContent.setPadding(dp(16), dp(6), dp(16), bookingBottomInsetPx() + dp(18));
        screenContent.setBackground(bookingFindingPageBackground());

        screenContent.addView(premiumLaundryRouteCard(status), margin(-1, -2, 0, 0, 0, 14));
        screenContent.addView(premiumLaundryServiceCard(), margin(-1, -2, 0, 0, 0, 14));
        screenContent.addView(laundryExpectedDeliveryCard(), margin(-1, -2, 0, 0, 0, 14));
        screenContent.addView(premiumLaundryActivityCard(status), margin(-1, -2, 0, 0, 0, 14));
        screenContent.addView(laundrySafeHandsCard(), margin(-1, -2, 0, 0, 0, 8));
    }

    private void renderCleaningOrderScreen(String rawStatus) {
        String status = normalizeRemoteStatus(rawStatus);
        boolean staffAssigned = cleaningStaffAssigned(status);
        mainScroll.setFillViewport(true);
        screenContent.setPadding(dp(16), dp(6), dp(16), bookingBottomInsetPx() + dp(18));
        screenContent.setBackground(bookingFindingPageBackground());
        screenContent.addView(cleaningCompanyTrackingCard(staffAssigned), margin(-1, -2, 0, 0, 0, 14));
        screenContent.addView(cleaningScheduledCard(), margin(-1, -2, 0, 0, 0, 14));
        screenContent.addView(cleaningProgressCard(status, staffAssigned), margin(-1, -2, 0, 0, 0, 14));
        if (staffAssigned) {
            screenContent.addView(cleaningCollectionCard(), margin(-1, -2, 0, 0, 0, 14));
        }
        screenContent.addView(cleaningSafeHandsCard(), margin(-1, -2, 0, 0, 0, 8));
    }

    private boolean cleaningStaffAssigned(String status) {
        return "staff_assigned".equals(status) || "assigned".equals(status) || "on_the_way".equals(status)
                || "arrived".equals(status) || "started".equals(status);
    }

