    private void animateLaundryPaymentPanel(View panel) {
        panel.setAlpha(0f);
        int availableWidth = Math.max(dp(220), getResources().getDisplayMetrics().widthPixels - dp(100));
        panel.measure(View.MeasureSpec.makeMeasureSpec(availableWidth, View.MeasureSpec.EXACTLY),
                View.MeasureSpec.makeMeasureSpec(0, View.MeasureSpec.UNSPECIFIED));
        int targetHeight = panel.getMeasuredHeight();
        ViewGroup.LayoutParams params = panel.getLayoutParams();
        if (params == null) params = new LinearLayout.LayoutParams(-1, 0);
        params.height = 0;
        panel.setLayoutParams(params);
        ViewGroup.LayoutParams finalParams = params;
        ValueAnimator reveal = ValueAnimator.ofInt(0, targetHeight);
        reveal.setDuration(360L);
        reveal.setInterpolator(new AccelerateDecelerateInterpolator());
        reveal.addUpdateListener(animation -> {
            finalParams.height = (int) animation.getAnimatedValue();
            panel.setLayoutParams(finalParams);
            panel.setAlpha(animation.getAnimatedFraction());
        });
        reveal.start();
    }

