    private int laundryStage(String status) {
        if ("completed".equals(status) || "delivered".equals(status) || "amount_pending".equals(status)) return 5;
        if ("started".equals(status) || "out_for_delivery".equals(status) || "ready_for_delivery".equals(status)
                || "in_washing".equals(status) || "washing".equals(status) || "drying".equals(status) || "ironing".equals(status)) return 4;
        if ("arrived".equals(status) || "picked_up".equals(status) || "collected".equals(status)) return 3;
        if ("on_the_way".equals(status)) return 2;
        return 1;
    }

    private String shortLaundryAddress() {
        String address = confirmedAddressLabel();
        if (TextUtils.isEmpty(address)) return "Your service area";
        String[] parts = address.split(",");
        return parts.length > 2 ? parts[parts.length - 3].trim() + ", " + parts[parts.length - 2].trim() : address;
    }

    private String laundryDeliveryLabel() {
        return TextUtils.isEmpty(selectedDate) ? confirmedSlotLabel() : selectedDate + ", Before 8:00 PM";
    }

    private void renderBookingTrackingScreen(String rawStatus) {
        String status = normalizeRemoteStatus(rawStatus);
        boolean partnerAssignedScreen = "accepted".equals(status);
        mainScroll.setFillViewport(true);
        screenContent.setPadding(0, 0, 0, bookingBottomInsetPx() + dp(12));
        screenContent.setBackground(bookingFindingPageBackground());

        LinearLayout hero = vertical();
        hero.setGravity(Gravity.CENTER_HORIZONTAL);
        hero.setPadding(dp(14), dp(4), dp(14), 0);

        String title = trackingHeroTitle(status);
        String subtitle = trackingHeroSubtitle(status);
        View visual;
        if ("accepted".equals(status)) {
            visual = bookingTopSuccessBadge();
        } else if ("on_the_way".equals(status)) {
            visual = bookingTopScooterBadge();
        } else if ("arrived".equals(status)) {
            visual = bookingTopScooterBadge(true);
        } else if ("started".equals(status)) {
            visual = bookingTopToolsBadge();
        } else {
            visual = bookingTopToolsBadge();
        }
        hero.addView(visual, new LinearLayout.LayoutParams(-1, dp(partnerAssignedScreen ? 116 : 100)));
        hero.addView(bookingAssignedHeroHeading(title), margin(-1, -2, 0, 5, 0, 6));
        TextView body = text(subtitle, 14, Color.rgb(48, 52, 62), false);
        body.setGravity(Gravity.CENTER);
        body.setLineSpacing(dp(2), 1f);
        hero.addView(body);
        screenContent.addView(hero, margin(-1, -2, 0, 0, 0, 16));

        screenContent.addView(bookingPartnerAssignedCard(), margin(-1, -2, 18, 0, 18, 14));
        if (canCustomerCancelCurrentBooking()) {
            screenContent.addView(bookingAssignedCancelCard(), margin(-1, -2, 18, 0, 18, 14));
        }
        screenContent.addView(bookingAssignedDetailsCard(), margin(-1, -2, 18, 0, 18, 14));
    }

    private boolean canCustomerCancelCurrentBooking() {
        if (latestBooking == null || isCancellationInFlight(latestBooking.getId())) {
            return false;
        }
        String status = bookingFlowStatus();
        return "pending".equals(status) || "accepted".equals(status);
    }

