    private void showCustomerCancelBookingDialog() {
        if (!canCustomerCancelCurrentBooking()) {
            Toast.makeText(this, "This booking can no longer be cancelled from the app.", Toast.LENGTH_LONG).show();
            return;
        }
        AlertDialog dialog = new AlertDialog.Builder(this).create();
        LinearLayout sheet = vertical();
        sheet.setPadding(dp(20), dp(18), dp(20), dp(18));
        sheet.setBackground(stroke(Color.WHITE, Color.rgb(250, 214, 224), dp(22)));

        sheet.addView(text("Cancel this booking?", 20, BLACK, true));
        TextView body = text("You can cancel before the partner starts travelling. Your booking will remain visible in Booking History under Cancelled.", 12, MUTED, false);
        body.setLineSpacing(dp(2), 1f);
        sheet.addView(body, margin(-1, -2, 0, 6, 0, 16));

        LinearLayout booking = horizontal();
        booking.setGravity(Gravity.CENTER_VERTICAL);
        booking.setPadding(dp(12), dp(10), dp(12), dp(10));
        booking.setBackground(round(Color.rgb(255, 246, 248), dp(14)));
        booking.addView(bookingFindingIconBox(BookingFindingArtworkView.SERVICE, 38), new LinearLayout.LayoutParams(dp(38), dp(38)));
        LinearLayout info = vertical();
        info.setPadding(dp(10), 0, 0, 0);
        info.addView(text(latestBookingService().getName(), 13, BLACK, true));
        info.addView(text("Booking ID: " + bookingDisplayId(), 11, MUTED, false), margin(-1, -2, 0, 2, 0, 0));
        booking.addView(info, new LinearLayout.LayoutParams(0, -2, 1));
        sheet.addView(booking, margin(-1, -2, 0, 0, 0, 16));

        TextView confirm = text("Cancel Booking", 15, Color.WHITE, true);
        confirm.setGravity(Gravity.CENTER);
        confirm.setBackground(bookGlowButtonDrawable());
        confirm.setOnClickListener(view -> {
            confirm.setEnabled(false);
            confirm.setText("Cancelling...");
            cancelCustomerBooking(dialog);
        });
        addPressAnimation(confirm);
        sheet.addView(confirm, new LinearLayout.LayoutParams(-1, dp(50)));

        TextView keep = text("Keep Booking", 14, MUTED, true);
        keep.setGravity(Gravity.CENTER);
        keep.setOnClickListener(view -> dialog.dismiss());
        sheet.addView(keep, margin(-1, 42, 0, 8, 0, 0));

        dialog.setView(sheet);
        dialog.show();
        Window window = dialog.getWindow();
        if (window != null) {
            window.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));
        }
    }

    private void cancelCustomerBooking(AlertDialog dialog) {
        if (latestBooking == null || TextUtils.isEmpty(latestBooking.getId())) {
            return;
        }
        final String bookingCode = latestBooking.getId();
        if (isCancellationInFlight(bookingCode)) {
            return;
        }
        final String previousStatus = bookingStatusFor(latestBooking);
        final long operationVersion = cancellationRegistry.begin(bookingCode, previousStatus);
        if (operationVersion < 0L) return;
        applyBookingStatusById(bookingCode, "cancelling", "USER_CANCEL_OPTIMISTIC", true);
        if (dialog != null && dialog.isShowing()) {
            dialog.dismiss();
        }
        if ("bookings".equals(currentScreen)) {
            showBookingsList();
        }
        final String backendBookingId = backendIdFor(bookingCode);
        bookingLog("API_REQUEST", bookingCode, previousStatus, "cancelling", "USER_CANCEL");
        if (backendClient == null) {
            rollbackCustomerBookingCancellation(bookingCode, operationVersion, "Backend unavailable");
            return;
        }
        backendClient.updateBookingStatus(backendBookingId, "cancelled", 0, new BackendClient.JsonCallback() {
            @Override
            public void onSuccess(JSONObject object) {
                finishCustomerBookingCancellation(bookingCode, operationVersion);
            }

            @Override
            public void onError(String message) {
                rollbackCustomerBookingCancellation(bookingCode, operationVersion, message);
            }
        });
    }

    private void finishCustomerBookingCancellation(String bookingCode, long operationVersion) {
        if (!cancellationRegistry.complete(bookingCode, operationVersion)) return;
        applyBookingStatusById(bookingCode, "cancelled", "API_SUCCESS", true);
        bookingLog("API_SUCCESS", bookingCode, "cancelling", "cancelled", "USER_CANCEL");
        Toast.makeText(this, "Booking cancelled successfully.", Toast.LENGTH_SHORT).show();
        if ("bookings".equals(currentScreen) || bookingCode.equals(currentBookingId())) showBookingsList();
    }

    private void rollbackCustomerBookingCancellation(String bookingCode, long operationVersion, String message) {
        String previous = cancellationRegistry.rollback(bookingCode, operationVersion);
        if (previous == null) return;
        applyBookingStatusById(bookingCode, previous, "API_FAILURE_ROLLBACK", true);
        bookingLog("API_FAILURE", bookingCode, "cancelling", previous, safeUserError(message));
        Toast.makeText(this, "Cancel failed: " + safeUserError(message), Toast.LENGTH_LONG).show();
        if ("bookings".equals(currentScreen) || bookingCode.equals(currentBookingId())) showBookingsList();
    }

