    private String trackingHeroTitle(String status) {
        if ("accepted".equals(status)) return "Partner Assigned!";
        if ("on_the_way".equals(status)) return "Partner On the Way!";
        if ("arrived".equals(status)) return "Partner Arrived!";
        if ("started".equals(status)) return "Work in Progress";
        return "Finding the best expert\nfor you...";
    }

    private String trackingHeroSubtitle(String status) {
        if ("accepted".equals(status)) return "A verified professional has accepted your booking.";
        if ("on_the_way".equals(status)) return "Your partner is on the way to your location.\nWe're almost there!";
        if ("arrived".equals(status)) return "Your partner has arrived at your location.\nGet ready for your service!";
        if ("started".equals(status)) return "Your partner is working on your service.\nSit tight! We'll notify you once it's done.";
        return "Searching nearby verified services";
    }

