    private View paymentRatingCard() {
        LinearLayout card = vertical();
        card.setGravity(Gravity.CENTER_HORIZONTAL);
        card.setPadding(dp(18), dp(18), dp(18), dp(18));
        card.setBackground(stroke(Color.WHITE, Color.rgb(255, 196, 207), dp(18)));
        TextView ratingBadge = text("\u2606", 24, Color.WHITE, true);
        ratingBadge.setGravity(Gravity.CENTER);
        ratingBadge.setBackground(gradient(Color.rgb(255, 111, 134), Color.rgb(236, 45, 83), dp(24)));
        card.addView(ratingBadge, new LinearLayout.LayoutParams(dp(50), dp(50)));
        TextView title = text("Rate your service partner", 18, BLACK, true);
        title.setGravity(Gravity.CENTER);
        card.addView(title, margin(-1, -2, 0, 8, 0, 3));
        TextView subtitle = text("Your feedback helps us improve", 13, MUTED, false);
        subtitle.setGravity(Gravity.CENTER);
        card.addView(subtitle);

        String bookingId = latestBooking == null ? "" : latestBooking.getId();
        if (!bookingId.equals(selectedPartnerRatingBookingId)) {
            selectedPartnerRatingBookingId = bookingId;
            selectedPartnerRating = 0;
        }
        int submittedRating = submittedRatingFor(bookingId);
        if (submittedRating > 0) selectedPartnerRating = submittedRating;
        final TextView[] stars = new TextView[5];
        LinearLayout starRow = horizontal();
        starRow.setGravity(Gravity.CENTER);
        Runnable refresh = () -> {
            for (int i = 0; i < stars.length; i++) {
                if (stars[i] != null) {
                    stars[i].setText(i < selectedPartnerRating ? "\u2605" : "\u2606");
                    stars[i].setTextColor(i < selectedPartnerRating ? Color.rgb(247, 177, 0) : Color.rgb(187, 190, 195));
                }
            }
        };
        for (int i = 0; i < 5; i++) {
            final int value = i + 1;
            TextView star = text("\u2606", 39, Color.rgb(187, 190, 195), true);
            star.setGravity(Gravity.CENTER);
            star.setEnabled(submittedRating == 0);
            star.setOnClickListener(view -> {
                selectedPartnerRating = value;
                refresh.run();
            });
            addPressAnimation(star);
            stars[i] = star;
            starRow.addView(star, new LinearLayout.LayoutParams(dp(52), dp(58)));
        }
        refresh.run();
        card.addView(starRow, margin(-1, -2, 0, 10, 0, 2));

        LinearLayout labels = horizontal();
        labels.addView(text("Poor", 11, MUTED, false), new LinearLayout.LayoutParams(0, -2, 1));
        TextView excellent = text("Excellent", 11, MUTED, false);
        excellent.setGravity(Gravity.RIGHT);
        labels.addView(excellent, new LinearLayout.LayoutParams(0, -2, 1));
        card.addView(labels);

        TextView submit = text(submittedRating > 0 ? "Rating Submitted" : "Submit Rating", 15,
                submittedRating > 0 ? GREEN : BOOKING_THEME, true);
        submit.setGravity(Gravity.CENTER);
        submit.setBackground(stroke(Color.WHITE, submittedRating > 0 ? Color.rgb(169, 225, 193) : Color.rgb(255, 142, 163), dp(14)));
        submit.setEnabled(submittedRating == 0 && !partnerRatingSubmitting);
        submit.setOnClickListener(view -> submitPartnerRating(bookingId, submit));
        addPressAnimation(submit);
        card.addView(submit, margin(-1, 50, 0, 14, 0, 0));
        return card;
    }

    private void submitPartnerRating(String bookingId, TextView submit) {
        if (TextUtils.isEmpty(bookingId) || selectedPartnerRating < 1 || selectedPartnerRating > 5) {
            Toast.makeText(this, "Select a rating before submitting", Toast.LENGTH_SHORT).show();
            return;
        }
        if (partnerRatingSubmitting) return;
        partnerRatingSubmitting = true;
        submit.setEnabled(false);
        submit.setText("Submitting...");
        backendClient.submitReview(bookingId, selectedPartnerRating, "", new BackendClient.JsonCallback() {
            @Override
            public void onSuccess(JSONObject object) {
                partnerRatingSubmitting = false;
                putSecureString(ratingPreferenceKey(bookingId), String.valueOf(selectedPartnerRating));
                JSONObject summary = object.optJSONObject("partnerRating");
                if (summary != null) {
                    assignedPartnerRating = Math.max(0d, summary.optDouble("rating", assignedPartnerRating));
                    assignedPartnerRatingCount = Math.max(0, summary.optInt("ratingCount", assignedPartnerRatingCount));
                    bookingPartnerRatingCache.put(bookingId, assignedPartnerRating);
                    bookingPartnerRatingCountCache.put(bookingId, assignedPartnerRatingCount);
                }
                Toast.makeText(MainActivity.this, "Rating submitted successfully", Toast.LENGTH_SHORT).show();
                showBookingCompletedScreen(bookingId);
            }

            @Override
            public void onError(String message) {
                partnerRatingSubmitting = false;
                submit.setEnabled(true);
                submit.setText("Submit Rating");
                if (message != null && message.contains("409")) {
                    putSecureString(ratingPreferenceKey(bookingId), String.valueOf(selectedPartnerRating));
                    Toast.makeText(MainActivity.this, "This booking is already rated", Toast.LENGTH_SHORT).show();
                    showBookingCompletedScreen(bookingId);
                    return;
                }
                Toast.makeText(MainActivity.this, "Rating could not be submitted. Please try again.", Toast.LENGTH_SHORT).show();
            }
        });
    }

    private String ratingPreferenceKey(String bookingId) {
        return "partner_rating_submitted_" + (bookingId == null ? "" : bookingId.trim());
    }

    private int submittedRatingFor(String bookingId) {
        if (TextUtils.isEmpty(bookingId)) return 0;
        try {
            return Math.max(0, Math.min(5, Integer.parseInt(secureString(ratingPreferenceKey(bookingId), "0"))));
        } catch (Exception ignored) {
            return 0;
        }
    }

