    private void loadCircularPartnerPhoto(ImageView imageView, String url, int sizeDp) {
        if (activityDestroyed || imageView == null || !isSafeRemoteImageUrl(url)) return;
        int pixels = Math.max(dp(sizeDp), dp(40));
        RequestOptions options = new RequestOptions()
                .override(pixels, pixels)
                .circleCrop()
                .format(DecodeFormat.PREFER_RGB_565)
                .diskCacheStrategy(DiskCacheStrategy.AUTOMATIC)
                .dontAnimate();
        Glide.with(imageView).load(url).apply(options).into(imageView);
    }

