    private View bookingFlowProgress(int activeStep) {
        LinearLayout panel = vertical();
        panel.setPadding(dp(8), dp(8), dp(8), dp(8));
        LinearLayout dots = horizontal();
        dots.setGravity(Gravity.CENTER_VERTICAL);
        String[] labels = {"Booking\nConfirmed", "Partner\nAssigned", "On The\nWay", "Arrived", "Working", "Completed"};
        for (int i = 0; i < labels.length; i++) {
            int step = i + 1;
            dots.addView(flowStepDot(step <= activeStep, step == activeStep), new LinearLayout.LayoutParams(dp(24), dp(24)));
            if (i < labels.length - 1) {
                dots.addView(trackStepConnector(step < activeStep), new LinearLayout.LayoutParams(0, dp(2), 1));
            }
        }
        panel.addView(dots);
        LinearLayout textRow = horizontal();
        textRow.setGravity(Gravity.TOP);
        for (int i = 0; i < labels.length; i++) {
            TextView label = text(labels[i], 8, (i + 1) <= activeStep ? GREEN : MUTED, (i + 1) <= activeStep);
            label.setGravity(Gravity.CENTER);
            label.setMaxLines(2);
            label.setIncludeFontPadding(false);
            textRow.addView(label, new LinearLayout.LayoutParams(0, -2, 1));
        }
        panel.addView(textRow, margin(-1, -2, 0, 6, 0, 0));
        return panel;
    }

    private View bookingTrackingProgress(String rawStatus) {
        String status = normalizeRemoteStatus(rawStatus);
        int current = trackingStage(status);
        String[] labels = {
                "Booking\nConfirmed",
                "pending".equals(status) ? "Finding\nService" : "Partner\nAssigned",
                "On the\nWay",
                "Arrived",
                "Working",
                "Completed"
        };
        LinearLayout panel = vertical();
        panel.setPadding(dp(12), dp(13), dp(12), dp(11));
        panel.setBackground(stroke(Color.WHITE, Color.rgb(230, 239, 233), dp(14)));
        panel.setElevation(dp(2));

        LinearLayout dots = horizontal();
        dots.setGravity(Gravity.CENTER_VERTICAL);
        for (int index = 0; index < labels.length; index++) {
            boolean done = index < current || (index == current && !"pending".equals(status));
            boolean active = index == current;
            dots.addView(trackingStepDot(done, active, index == 1 && "pending".equals(status)),
                    new LinearLayout.LayoutParams(dp(22), dp(22)));
            if (index < labels.length - 1) {
                boolean connected = index < current;
                View line = new View(this);
                line.setBackgroundColor(connected ? GREEN : Color.rgb(219, 225, 221));
                dots.addView(line, new LinearLayout.LayoutParams(0, dp(2), 1));
            }
        }
        panel.addView(dots);

        LinearLayout labelRow = horizontal();
        labelRow.setGravity(Gravity.TOP);
        for (int index = 0; index < labels.length; index++) {
            boolean highlighted = index <= current;
            TextView label = text(labels[index], 7, highlighted ? Color.rgb(16, 92, 54) : Color.rgb(126, 130, 127), highlighted);
            label.setGravity(Gravity.CENTER);
            label.setMaxLines(2);
            label.setIncludeFontPadding(false);
            labelRow.addView(label, new LinearLayout.LayoutParams(0, dp(31), 1));
        }
        panel.addView(labelRow, margin(-1, -2, 0, 7, 0, 0));
        return panel;
    }

    private TextView trackingStepDot(boolean done, boolean active, boolean searching) {
        String mark = done ? "\u2713" : (searching ? "\u25CF" : "");
        TextView dot = text(mark, searching ? 9 : 11, done || searching ? Color.WHITE : MUTED, true);
        dot.setGravity(Gravity.CENTER);
        if (done || searching) {
            dot.setBackground(round(GREEN, dp(11)));
        } else {
            dot.setBackground(stroke(Color.rgb(239, 241, 240), Color.rgb(216, 221, 218), dp(11)));
        }
        if (active) {
            startScalePulse(dot, 0.96f, 1.1f, 900);
        }
        return dot;
    }

    private int trackingStage(String status) {
        String value = normalizeRemoteStatus(status);
        if ("completed".equals(value)) return 5;
        if ("amount_pending".equals(value)) return 5;
        if ("started".equals(value)) return 4;
        if ("arrived".equals(value)) return 3;
        if ("on_the_way".equals(value)) return 2;
        return 1;
    }

    private View bookingTrackingNotice(String rawStatus) {
        String status = normalizeRemoteStatus(rawStatus);
        String message;
        if ("accepted".equals(status)) {
            message = "Partner assigned. Expected arrival: " + partnerArrivalDisplay();
        } else if ("on_the_way".equals(status)) {
            message = "Your expert is on the way. Live arrival updates are active.";
        } else if ("arrived".equals(status)) {
            message = "Your expert has arrived at the service address.";
        } else if ("started".equals(status)) {
            message = "Work is in progress. We will notify you when it is completed.";
        } else {
            message = "We'll notify you once a partner is assigned.";
        }
        LinearLayout notice = horizontal();
        notice.setGravity(Gravity.CENTER_VERTICAL);
        notice.setPadding(dp(22), dp(18), dp(22), dp(18));
        notice.setBackground(round(Color.rgb(239, 252, 244), dp(18)));
        notice.setElevation(dp(4));
        TextView bell = text("\u25CE", 24, Color.WHITE, true);
        bell.setGravity(Gravity.CENTER);
        bell.setBackground(successBallDrawable());
        notice.addView(bell, new LinearLayout.LayoutParams(dp(58), dp(58)));
        TextView copy = text("We'll notify you\nonce a partner is assigned.", 18, Color.rgb(4, 73, 35), true);
        copy.setPadding(dp(22), 0, 0, 0);
        copy.setLineSpacing(dp(3), 1f);
        notice.addView(copy, new LinearLayout.LayoutParams(0, -2, 1));
        return notice;
    }

