    private boolean isAmountApprovalPending() {
        return "amount_pending".equals(normalizeRemoteStatus(remoteBookingStatus))
                && remoteFinalAmount > 0
                && "pending".equals(normalizeQuoteStatus(remoteQuoteStatus))
                && !isRemoteQuoteExpired();
    }

    private boolean isRemoteQuoteExpired() {
        return remoteQuoteExpiresAtMillis > 0 && remoteQuoteExpiresAtMillis <= System.currentTimeMillis();
    }

    private String normalizeQuoteStatus(String status) {
        String value = status == null ? "" : status.trim().toLowerCase(Locale.US)
                .replace('-', '_')
                .replace(' ', '_');
        if (value.isEmpty() || "none".equals(value)) {
            return "amount_pending".equals(normalizeRemoteStatus(remoteBookingStatus)) ? "pending" : "none";
        }
        return value;
    }

    private String quoteExpiryLabel() {
        if (remoteQuoteExpiresAtMillis <= 0) {
            return "Valid for 24 hours";
        }
        long remaining = remoteQuoteExpiresAtMillis - System.currentTimeMillis();
        if (remaining <= 0) {
            return "Quote expired";
        }
        long hours = Math.max(1L, (long) Math.ceil(remaining / 3600000.0));
        return "Expires in " + hours + "h";
    }

    private void dismissAmountApprovalPopup() {
        amountApprovalPopupQueued = false;
        if (amountApprovalDialog == null) {
            return;
        }
        AlertDialog dialog = amountApprovalDialog;
        amountApprovalDialog = null;
        if (dialog.isShowing()) {
            dialog.dismiss();
        }
    }

    private void maybeShowAmountApprovalPopup(Booking booking) {
        if (!featureEnabled(FeatureRegistry.PAYMENT)
                || booking == null || amountApprovalPopupQueued || "login".equals(currentScreen) || isPaymentVerificationWaiting() || !isAmountApprovalPending()) {
            return;
        }
        if (amountApprovalDialog != null && amountApprovalDialog.isShowing()) {
            return;
        }
        amountApprovalPopupQueued = true;
        carouselHandler.post(() -> {
            amountApprovalPopupQueued = false;
            if (booking == null || "login".equals(currentScreen) || isPaymentVerificationWaiting() || !isAmountApprovalPending()) {
                return;
            }
            if (amountApprovalDialog != null && amountApprovalDialog.isShowing()) {
                return;
            }
            showAmountApprovalPopup(booking);
        });
    }

