    private void showCounterOfferDialog(Booking booking) {
        AlertDialog dialog = new AlertDialog.Builder(this).create();
        LinearLayout sheet = vertical();
        sheet.setPadding(dp(20), dp(18), dp(20), dp(18));
        sheet.setBackground(bookingOuterDrawable());

        TextView title = text("Send counter offer", 20, BLACK, true);
        title.setGravity(Gravity.CENTER);
        sheet.addView(title);
        TextView subtitle = text("Partner will review your offer and send a fresh quote.", 12, MUTED, false);
        subtitle.setGravity(Gravity.CENTER);
        sheet.addView(subtitle, margin(-1, -2, 0, 4, 0, 16));

        EditText amountInput = new EditText(this);
        amountInput.setHint("Your offer amount");
        amountInput.setInputType(InputType.TYPE_CLASS_NUMBER);
        amountInput.setSingleLine(true);
        amountInput.setTextColor(BLACK);
        amountInput.setHintTextColor(Color.rgb(168, 145, 148));
        amountInput.setBackground(stroke(Color.WHITE, Color.rgb(247, 108, 145), dp(14)));
        amountInput.setPadding(dp(14), 0, dp(14), 0);
        if (remoteFinalAmount > 0) {
            int suggested = Math.max(1, remoteFinalAmount - Math.max(50, remoteFinalAmount / 10));
            amountInput.setText(String.valueOf(suggested));
            amountInput.setSelection(amountInput.getText().length());
        }
        sheet.addView(amountInput, new LinearLayout.LayoutParams(-1, dp(52)));

        EditText messageInput = new EditText(this);
        messageInput.setHint("Optional note");
        messageInput.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);
        messageInput.setSingleLine(true);
        messageInput.setTextColor(BLACK);
        messageInput.setHintTextColor(Color.rgb(168, 145, 148));
        messageInput.setBackground(stroke(Color.WHITE, Color.rgb(238, 213, 211), dp(14)));
        messageInput.setPadding(dp(14), 0, dp(14), 0);
        sheet.addView(messageInput, margin(-1, 52, 0, 10, 0, 16));

        LinearLayout actions = horizontal();
        TextView cancel = text("Cancel", 13, BLACK, true);
        cancel.setGravity(Gravity.CENTER);
        cancel.setBackground(stroke(Color.WHITE, Color.rgb(232, 203, 202), dp(14)));
        cancel.setOnClickListener(view -> dialog.dismiss());
        addPressAnimation(cancel);
        actions.addView(cancel, new LinearLayout.LayoutParams(0, dp(48), 1));

        TextView send = text("Send Offer", 13, Color.WHITE, true);
        send.setGravity(Gravity.CENTER);
        send.setBackground(bookGlowButtonDrawable());
        send.setOnClickListener(view -> {
            String rawAmount = amountInput.getText().toString().trim();
            if (TextUtils.isEmpty(rawAmount)) {
                Toast.makeText(this, "Please enter your offer amount.", Toast.LENGTH_SHORT).show();
                return;
            }
            int amount;
            try {
                amount = Integer.parseInt(rawAmount);
            } catch (Exception ignored) {
                Toast.makeText(this, "Please enter a valid amount.", Toast.LENGTH_SHORT).show();
                return;
            }
            if (amount <= 0) {
                Toast.makeText(this, "Please enter a valid amount.", Toast.LENGTH_SHORT).show();
                return;
            }
            send.setEnabled(false);
            String bookingId = TextUtils.isEmpty(latestBackendBookingId) ? booking.getId() : latestBackendBookingId;
            backendClient.counterOfferQuote(bookingId, amount, messageInput.getText().toString().trim(), new BackendClient.JsonCallback() {
                @Override
                public void onSuccess(JSONObject object) {
                    remoteQuoteStatus = "countered";
                    remoteQuoteCounterAmount = amount;
                    remoteQuoteCounterMessage = messageInput.getText().toString().trim();
                    dismissAmountApprovalPopup();
                    dialog.dismiss();
                    Toast.makeText(MainActivity.this, "Counter offer sent to partner", Toast.LENGTH_SHORT).show();
                    showTrack();
                }

                @Override
                public void onError(String message) {
                    send.setEnabled(true);
                    Toast.makeText(MainActivity.this, "Counter offer failed. Try again.", Toast.LENGTH_SHORT).show();
                }
            });
        });
        addPressAnimation(send);
        LinearLayout.LayoutParams sendParams = new LinearLayout.LayoutParams(0, dp(48), 1);
        sendParams.setMargins(dp(10), 0, 0, 0);
        actions.addView(send, sendParams);
        sheet.addView(actions);

        dialog.setView(sheet);
        dialog.setOnShowListener(d -> {
            if (dialog.getWindow() != null) {
                dialog.getWindow().setBackgroundDrawable(round(Color.TRANSPARENT, dp(24)));
                dialog.getWindow().setDimAmount(0.42f);
                dialog.getWindow().setLayout((int) (getResources().getDisplayMetrics().widthPixels * 0.9f), WindowManager.LayoutParams.WRAP_CONTENT);
            }
        });
        dialog.show();
    }

    private void confirmFinalAmount(Booking booking) {
        if (!requireFeature(FeatureRegistry.PAYMENT, "Payment")) return;
        if (remoteFinalAmount <= 0) {
            Toast.makeText(this, "Final amount missing", Toast.LENGTH_SHORT).show();
            return;
        }
        if (!isAmountApprovalPending()) {
            Toast.makeText(this, isRemoteQuoteExpired() ? "Quote expired. Ask partner for a fresh quote." : "Quote is not ready for approval.", Toast.LENGTH_LONG).show();
            fetchBookingAssignmentStatus();
            return;
        }
        paymentVerificationWaitingBookingId = booking.getId();
        remoteQuoteStatus = "payment_submitted";
        dismissAmountApprovalPopup();
        Toast.makeText(this, "Waiting for partner payment verification", Toast.LENGTH_SHORT).show();
        showBookingConfirmedScreen();
        String bookingId = TextUtils.isEmpty(latestBackendBookingId) ? booking.getId() : latestBackendBookingId;
        backendClient.submitDirectPayment(bookingId, new BackendClient.JsonCallback() {
            @Override
            public void onSuccess(JSONObject object) {
                JSONObject remote = object.optJSONObject("booking");
                if (remote != null) {
                    updateAssignmentFromServer(
                            remote.optString("status", remoteBookingStatus),
                            remote.optString("partnerName", assignedPartnerName),
                            remote.optInt("finalAmount", remoteFinalAmount),
                            remote.optString("quoteStatus", remoteQuoteStatus),
                            jsonLong(remote, "quoteExpiresAtMillis", remoteQuoteExpiresAtMillis),
                            remote.optInt("quoteCounterAmount", remoteQuoteCounterAmount),
                            remote.optString("quoteCounterMessage", remoteQuoteCounterMessage)
                    );
                }
                fetchBookingAssignmentStatus();
            }

            @Override
            public void onError(String message) {
                Toast.makeText(MainActivity.this, "Payment confirmation could not be sent. Please try again.", Toast.LENGTH_LONG).show();
                paymentVerificationWaitingBookingId = "";
                remoteQuoteStatus = "pending";
                showBookingConfirmedScreen();
                fetchBookingAssignmentStatus();
            }
        });
        fetchBookingAssignmentStatus();
    }

