    private String bookingTierLabel(Booking booking) {
        String issue = booking == null ? "" : booking.getCustomerDetails().getIssue();
        String lower = issue.toLowerCase(Locale.US);
        if (lower.startsWith("premium") || lower.startsWith("premier")) {
            return "Premier Service";
        }
        return "Normal Service";
    }

    private String bookingIssueText(Booking booking) {
        if (booking == null) {
            return "Customer requested service inspection";
        }
        String issue = booking.getCustomerDetails().getIssue();
        int split = issue.indexOf(" - ");
        if (split >= 0 && split + 3 < issue.length()) {
            return issue.substring(split + 3);
        }
        return issue;
    }

    private View trackProgressTimeline(Booking booking) {
        String date = trackDateLabel(booking);
        boolean booked = isPartnerAcceptedStatus(remoteBookingStatus) || partnerAssigned;
        int step = booked ? trackStepForStatus(remoteBookingStatus) : 0;
        LinearLayout panel = vertical();
        panel.setPadding(dp(12), dp(8), dp(12), dp(4));

        LinearLayout dots = horizontal();
        dots.setGravity(Gravity.CENTER_VERTICAL);
        dots.addView(trackStepCircle(step == 0 ? "\u25F7" : "\u2713", step >= 1, step == 0), new LinearLayout.LayoutParams(dp(34), dp(34)));
        dots.addView(trackStepConnector(step >= 2), new LinearLayout.LayoutParams(0, dp(2), 1));
        dots.addView(trackStepCircle(step > 2 ? "\u2713" : "2", step >= 2), new LinearLayout.LayoutParams(dp(34), dp(34)));
        dots.addView(trackStepConnector(step >= 3), new LinearLayout.LayoutParams(0, dp(2), 1));
        dots.addView(trackStepCircle(step > 3 ? "\u2713" : "3", step >= 3), new LinearLayout.LayoutParams(dp(34), dp(34)));
        dots.addView(trackStepConnector(step >= 4), new LinearLayout.LayoutParams(0, dp(2), 1));
        dots.addView(trackStepCircle(step >= 4 ? "\u2713" : "4", step >= 4), new LinearLayout.LayoutParams(dp(34), dp(34)));
        panel.addView(dots);

        LinearLayout labels = horizontal();
        labels.setPadding(0, dp(10), 0, 0);
        labels.addView(trackStepLabel(booked ? "Partner Assigned" : "Pending", booked ? date + ", assigned" : "Partner not assigned", step >= 1), new LinearLayout.LayoutParams(0, -2, 1));
        labels.addView(trackStepLabel("On the Way", step >= 2 ? date + ", live" : "Pending", step >= 2), new LinearLayout.LayoutParams(0, -2, 1));
        labels.addView(trackStepLabel("Arrived", step >= 3 ? date + ", arrived" : "Pending", step >= 3), new LinearLayout.LayoutParams(0, -2, 1));
        labels.addView(trackStepLabel("Completed", step >= 4 ? date + ", done" : "Pending", step >= 4), new LinearLayout.LayoutParams(0, -2, 1));
        panel.addView(labels);
        return panel;
    }

