    private int trackStepForStatus(String status) {
        switch (normalizeRemoteStatus(status)) {
            case "on_the_way":
                return 2;
            case "arrived":
            case "started":
            case "amount_pending":
                return 3;
            case "completed":
                return 4;
            case "customer_no_response":
                return 3;
            case "accepted":
                return 1;
            default:
                return 1;
        }
    }

    private String trackDateLabel(Booking booking) {
        if (booking == null || booking.getCustomerDetails() == null) {
            return defaultDateLabel();
        }
        String slot = booking.getCustomerDetails().getSlot();
        int comma = slot.indexOf(",");
        if (comma > 0) {
            return slot.substring(0, comma).trim();
        }
        return slot.isEmpty() ? defaultDateLabel() : slot;
    }

    private TextView trackStepCircle(String value, boolean active) {
        return trackStepCircle(value, active, false);
    }

    private TextView trackStepCircle(String value, boolean active, boolean pendingSpinner) {
        int green = Color.rgb(22, 177, 111);
        int red = Color.rgb(226, 54, 54);
        int textColor = active ? Color.WHITE : (pendingSpinner ? red : MUTED);
        TextView circle = text(value, 13, textColor, true);
        circle.setGravity(Gravity.CENTER);
        if (active) {
            circle.setBackground(round(green, dp(17)));
        } else if (pendingSpinner) {
            circle.setBackground(stroke(Color.WHITE, red, dp(17)));
            startInfiniteRotation(circle, 850);
        } else {
            circle.setBackground(stroke(Color.WHITE, Color.rgb(222, 226, 230), dp(17)));
        }
        return circle;
    }

    private void startInfiniteRotation(View view, long durationMs) {
        ObjectAnimator animator = ObjectAnimator.ofFloat(view, View.ROTATION, 0f, 360f);
        animator.setDuration(durationMs);
        animator.setRepeatCount(ValueAnimator.INFINITE);
        animator.setInterpolator(new LinearInterpolator());
        animator.start();
        view.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener() {
            @Override
            public void onViewAttachedToWindow(View attachedView) {
            }

            @Override
            public void onViewDetachedFromWindow(View detachedView) {
                detachedView.removeOnAttachStateChangeListener(this);
                animator.cancel();
            }
        });
    }

