    private void showBookingHistoryDetails(Booking booking) {
        if (booking == null) return;
        selectedTrackBookingId = booking.getId();
        latestBooking = booking;
        selectedService = primaryService(booking);
        remoteBookingStatus = bookingStatusFor(booking);
        setCurrentScreen("booking_history_details");
        showAppChrome();
        setActiveNav(navBookings);
        resetScreen();
        floatingFooter.setVisibility(View.GONE);
        bottomNav.setVisibility(View.GONE);
        screenContent.setBackgroundColor(Color.rgb(255, 249, 250));

        LinearLayout top = horizontal();
        top.setGravity(Gravity.CENTER_VERTICAL);
        top.setPadding(dp(18), dp(14), dp(18), dp(12));
        TextView back = text("‹", 30, BLACK, false);
        back.setGravity(Gravity.CENTER);
        back.setBackground(stroke(Color.WHITE, Color.rgb(245, 225, 230), dp(16)));
        back.setOnClickListener(view -> showBookingsList());
        addPressAnimation(back);
        top.addView(back, new LinearLayout.LayoutParams(dp(46), dp(46)));
        TextView heading = text("Booking Details", 19, BLACK, true);
        heading.setGravity(Gravity.CENTER);
        top.addView(heading, new LinearLayout.LayoutParams(0, dp(46), 1));
        TextView secure = text("◇  Secure", 10, BOOKING_THEME, true);
        secure.setGravity(Gravity.CENTER);
        secure.setBackground(stroke(Color.WHITE, Color.rgb(245, 225, 230), dp(14)));
        top.addView(secure, new LinearLayout.LayoutParams(dp(80), dp(40)));
        screenContent.addView(top);

        LinearLayout card = vertical();
        card.setPadding(dp(18), dp(18), dp(18), dp(18));
        card.setBackground(stroke(Color.WHITE, Color.rgb(244, 226, 231), dp(18)));
        card.setElevation(dp(3));
        LinearLayout identity = horizontal();
        identity.setGravity(Gravity.CENTER_VERTICAL);
        identity.addView(serviceLogoView(selectedService, 64, true), new LinearLayout.LayoutParams(dp(64), dp(64)));
        LinearLayout copy = vertical();
        copy.setPadding(dp(14), 0, 0, 0);
        copy.addView(text(selectedService.getName(), 18, BLACK, true));
        copy.addView(text("Booking ID: " + booking.getId(), 11, MUTED, false));
        identity.addView(copy, new LinearLayout.LayoutParams(0, -2, 1));
        String statusValue = bookingStatusFor(booking);
        TextView status = text(readableHistoryDetailStatus(statusValue), 11, historyDetailStatusColor(statusValue), true);
        status.setGravity(Gravity.CENTER);
        status.setBackground(round(historyDetailStatusSoftColor(statusValue), dp(15)));
        identity.addView(status, new LinearLayout.LayoutParams(dp(94), dp(32)));
        card.addView(identity);
        card.addView(insetDivider(0), margin(-1, 1, 0, 16, 0, 14));
        card.addView(historyDetailRow(BookingFindingArtworkView.CALENDAR, "Date & Time", booking.getCustomerDetails().getSlot()));
        card.addView(insetDivider(48));
        card.addView(historyDetailRow(BookingFindingArtworkView.LOCATION, "Service Address", booking.getCustomerDetails().getAddress()));
        card.addView(insetDivider(48));
        String canonicalPrimary = authenticatedPrimaryPhone();
        String contactValue = "Primary  " + (isValidCustomerMobile(canonicalPrimary)
                ? formatIndianPhone(canonicalPrimary) : "Not added yet");
        if (isValidCustomerMobile(booking.getCustomerDetails().getAlternatePhone())) {
            contactValue += "\nAlternate  " + formatIndianPhone(booking.getCustomerDetails().getAlternatePhone());
        }
        card.addView(historyDetailRow(BookingFindingArtworkView.PHONE, "Contact Numbers", contactValue));
        card.addView(insetDivider(48));
        card.addView(historyDetailRow(BookingFindingArtworkView.SERVICE, "Service Details", booking.getCustomerDetails().getIssue()));
        if (booking.getTotal() > 0 || (booking.getId().equals(remoteFinalAmountBookingId) && remoteFinalAmount > 0)) {
            card.addView(insetDivider(48));
            int amount = booking.getId().equals(remoteFinalAmountBookingId) && remoteFinalAmount > 0 ? remoteFinalAmount : booking.getTotal();
            card.addView(historyDetailRow(BookingFindingArtworkView.COPY, "Amount", "₹" + amount));
        }
        screenContent.addView(card, margin(-1, -2, 18, 4, 18, 14));

        if (!isBookingClosed(booking)) {
            TextView track = text("Track Booking  →", 15, Color.WHITE, true);
            track.setGravity(Gravity.CENTER);
            track.setBackground(bookGlowButtonDrawable());
            track.setOnClickListener(view -> showTrackBooking(booking));
            addPressAnimation(track);
            screenContent.addView(track, margin(-1, 54, 18, 0, 18, 12));
        }
        screenContent.addView(bookingHelpActions(booking), margin(-1, -2, 18, 0, 18, 14));
        TextView bookAgain = text("▣  Book Again", 15, Color.WHITE, true);
        bookAgain.setGravity(Gravity.CENTER);
        bookAgain.setBackground(bookGlowButtonDrawable());
        bookAgain.setOnClickListener(view -> showBooking(primaryService(booking)));
        addPressAnimation(bookAgain);
        screenContent.addView(bookAgain, margin(-1, 56, 18, 0, 18, 24));
    }

