    private void showExistingBookingContactEditor(Booking booking) {
        if (booking == null || backendClient == null) return;
        AlertDialog dialog = new AlertDialog.Builder(this).create();
        LinearLayout sheet = vertical();
        sheet.setPadding(dp(20), dp(18), dp(20), dp(16));
        sheet.setBackground(bookingOuterDrawable());
        sheet.addView(text("Edit contact numbers", 19, BLACK, true));
        sheet.addView(text("Changes are saved to this booking immediately.", 12, MUTED, false), margin(-1, -2, 0, 4, 0, 14));
        EditText primary = bookingAddressField("Primary mobile number");
        primary.setInputType(InputType.TYPE_CLASS_PHONE);
        primary.setText(booking.getCustomerDetails().getPhone());
        sheet.addView(addressFieldBlock("Primary number *", primary));
        EditText alternate = bookingAddressField("Alternate mobile number (optional)");
        alternate.setInputType(InputType.TYPE_CLASS_PHONE);
        alternate.setText(booking.getCustomerDetails().getAlternatePhone());
        sheet.addView(addressFieldBlock("Alternate number", alternate));
        TextView save = text("Save Contact Numbers", 14, Color.WHITE, true);
        save.setGravity(Gravity.CENTER);
        save.setBackground(bookGlowButtonDrawable());
        save.setOnClickListener(view -> {
            String primaryPhone = normalizeCustomerPhoneInput(primary.getText().toString());
            String alternatePhone = normalizeCustomerPhoneInput(alternate.getText().toString());
            if (!isValidCustomerMobile(primaryPhone)) {
                Toast.makeText(this, "Enter a valid primary number", Toast.LENGTH_SHORT).show();
                return;
            }
            if (!TextUtils.isEmpty(alternatePhone) && !isValidCustomerMobile(alternatePhone)) {
                Toast.makeText(this, "Enter a valid alternate number", Toast.LENGTH_SHORT).show();
                return;
            }
            if (primaryPhone.equals(alternatePhone)) {
                Toast.makeText(this, "Primary and alternate numbers must be different", Toast.LENGTH_SHORT).show();
                return;
            }
            if (!isNetworkOnline()) {
                Toast.makeText(this, "Connection Lost. Contact update was not confirmed.", Toast.LENGTH_LONG).show();
                return;
            }
            save.setEnabled(false);
            save.setText("Saving...");
            backendClient.updateBookingContacts(booking.getId(), primaryPhone, alternatePhone, new BackendClient.JsonCallback() {
                @Override public void onSuccess(JSONObject object) {
                    dialog.dismiss();
                    putSecureString(KEY_CUSTOMER_PHONE, primaryPhone);
                    applyConfirmedBookingMutation(object, booking);
                    Toast.makeText(MainActivity.this, "Contact numbers updated", Toast.LENGTH_SHORT).show();
                }
                @Override public void onError(String message) {
                    save.setEnabled(true);
                    save.setText("Save Contact Numbers");
                    Toast.makeText(MainActivity.this, NetworkError.body(NetworkError.safe(message)), Toast.LENGTH_LONG).show();
                }
            });
        });
        sheet.addView(save, margin(-1, 50, 0, 4, 0, 0));
        dialog.setView(sheet);
        dialog.show();
    }

    private void showExistingBookingAddressEditor(Booking booking) {
        if (booking == null || backendClient == null) return;
        AlertDialog dialog = new AlertDialog.Builder(this).create();
        LinearLayout sheet = vertical();
        sheet.setPadding(dp(20), dp(18), dp(20), dp(16));
        sheet.setBackground(bookingOuterDrawable());
        sheet.addView(text("Edit Service Address", 19, BLACK, true));
        sheet.addView(text("The confirmed address is sent to your partner and admin immediately.", 12, MUTED, false), margin(-1, -2, 0, 4, 0, 14));
        EditText address = new EditText(this);
        address.setText(booking.getCustomerDetails().getAddress());
        address.setHint("Complete service address");
        address.setTextSize(13);
        address.setMinLines(3);
        address.setGravity(Gravity.TOP);
        address.setPadding(dp(14), dp(10), dp(14), dp(10));
        address.setBackground(stroke(Color.WHITE, Color.rgb(232, 203, 202), dp(12)));
        sheet.addView(address, margin(-1, 92, 0, 0, 0, 14));
        TextView save = text("Confirm Updated Location", 14, Color.WHITE, true);
        save.setGravity(Gravity.CENTER);
        save.setBackground(bookGlowButtonDrawable());
        save.setOnClickListener(view -> {
            String updatedAddress = address.getText().toString().trim();
            if (updatedAddress.length() < 10) {
                Toast.makeText(this, "Enter the complete service address", Toast.LENGTH_SHORT).show();
                return;
            }
            if (!isNetworkOnline()) {
                Toast.makeText(this, "Connection Lost. Your location update couldn't be confirmed. Please check your internet connection and try again.", Toast.LENGTH_LONG).show();
                return;
            }
            save.setEnabled(false);
            save.setText("Confirming location...");
            resolveAddressCoordinates(updatedAddress, booking, (lat, lng) -> {
                JSONObject payload = new JSONObject();
                try {
                    payload.put("address", updatedAddress);
                    payload.put("city", "Guwahati");
                    payload.put("lat", lat);
                    payload.put("lng", lng);
                    payload.put("expectedVersion", bookingLocationVersionCache.containsKey(booking.getId()) ? bookingLocationVersionCache.get(booking.getId()) : 1);
                } catch (Exception ignored) {
                }
                backendClient.updateBookingLocation(booking.getId(), payload, new BackendClient.JsonCallback() {
                    @Override public void onSuccess(JSONObject object) {
                        dialog.dismiss();
                        applyConfirmedBookingMutation(object, booking);
                        Toast.makeText(MainActivity.this, "Service location updated", Toast.LENGTH_SHORT).show();
                    }
                    @Override public void onError(String message) {
                        save.setEnabled(true);
                        save.setText("Confirm Updated Location");
                        Toast.makeText(MainActivity.this, "Location update wasn't confirmed. " + NetworkError.body(NetworkError.safe(message)), Toast.LENGTH_LONG).show();
                        backendClient.getBooking(booking.getId(), new BackendClient.JsonCallback() {
                            @Override public void onSuccess(JSONObject object) { applyConfirmedBookingMutation(object, booking); }
                            @Override public void onError(String ignored) { }
                        });
                    }
                });
            });
        });
        sheet.addView(save, margin(-1, 50, 0, 4, 0, 0));
        dialog.setView(sheet);
        dialog.show();
    }

    private interface BookingCoordinatesCallback { void onReady(double lat, double lng); }

    private void resolveAddressCoordinates(String address, Booking booking, BookingCoordinatesCallback callback) {
        double fallbackLat = bookingLatitudeCache.containsKey(booking.getId()) ? bookingLatitudeCache.get(booking.getId()) : serviceLat;
        double fallbackLng = bookingLongitudeCache.containsKey(booking.getId()) ? bookingLongitudeCache.get(booking.getId()) : serviceLng;
        executeGeocoderTask(() -> {
            double lat = fallbackLat;
            double lng = fallbackLng;
            try {
                List<Address> matches = new Geocoder(MainActivity.this, Locale.getDefault()).getFromLocationName(address, 1);
                if (matches != null && !matches.isEmpty()) {
                    lat = matches.get(0).getLatitude();
                    lng = matches.get(0).getLongitude();
                }
            } catch (Exception ignored) {
            }
            double confirmedLat = lat;
            double confirmedLng = lng;
            runOnUiThread(() -> {
                if (activityDestroyed || isFinishing() || isDestroyed()) return;
                callback.onReady(confirmedLat, confirmedLng);
            });
        });
    }

    private void applyConfirmedBookingMutation(JSONObject response, Booking fallback) {
        JSONObject remote = response == null ? null : response.optJSONObject("booking");
        if (remote == null) remote = response;
        if (remote == null) return;
        try {
            Booking updated = Booking.fromBackendJson(remote);
            bookingStore.save(updated);
            replaceStableBookingHistory(mergeBookingHistory(Collections.singletonList(updated), stableBookingHistory));
            rememberRemoteBookingMetadata(updated, remote);
            latestBooking = updated;
            if (fallback != null && fallback.getId().equals(selectedTrackBookingId)) selectedTrackBookingId = updated.getId();
            if ("booking_history_details".equals(currentScreen)) showBookingHistoryDetails(updated);
        } catch (Exception ignored) {
        }
    }

    private String readableHistoryDetailStatus(String status) {
        String value = normalizeRemoteStatus(status);
        if ("completed".equals(value)) return "Completed";
        if ("cancelled".equals(value) || "rejected".equals(value)) return "Cancelled";
        return readableBookingStatus(value);
    }

    private int historyDetailStatusColor(String status) {
        String value = normalizeRemoteStatus(status);
        if ("completed".equals(value)) return GREEN;
        if ("cancelled".equals(value) || "rejected".equals(value)) return Color.rgb(218, 59, 76);
        return BOOKING_THEME;
    }

    private int historyDetailStatusSoftColor(String status) {
        String value = normalizeRemoteStatus(status);
        if ("completed".equals(value)) return Color.rgb(226, 249, 238);
        if ("cancelled".equals(value) || "rejected".equals(value)) return Color.rgb(255, 235, 238);
        return BOOKING_THEME_SOFT;
    }

    private void showTrackBooking(Booking booking) {
        if (booking == null) {
            showTrack();
            return;
        }
        boolean alreadySelected = latestBooking != null
                && booking.getId().equals(latestBooking.getId())
                && !TextUtils.isEmpty(latestBackendBookingId);
        selectedTrackBookingId = booking.getId();
        latestBooking = booking;
        // Persist the exact card/popup booking before rendering. This guarantees
        // that a live booking opened from history or Home cannot be replaced by
        // another record (or sent back to the booking list) during a refresh.
        if (bookingStore != null) {
            bookingStore.save(booking);
        }
        if (!bookingStatusCache.containsKey(booking.getId())) {
            bookingStatusCache.put(booking.getId(), normalizeRemoteStatus(booking.getStatus()));
        }
        if (!alreadySelected) {
            // The backend accepts the public booking code too. Keeping it tied to the
            // selected card prevents an old booking's Mongo id from opening the wrong flow.
            latestBackendBookingId = booking.getId();
            saveLatestBackendBookingId();
        }
        selectedService = primaryService(booking);
        remoteBookingStatus = bookingStatusFor(booking);
        partnerAssigned = isPartnerAcceptedStatus(remoteBookingStatus);
        awaitingPartnerAssignment = !partnerAssigned && !isClosedBookingStatus(remoteBookingStatus);
        assignedPartnerName = bookingPartnerNameCache.containsKey(booking.getId())
                ? bookingPartnerNameCache.get(booking.getId())
                : "ApnaServo Partner";
        assignedPartnerPhotoUrl = bookingPartnerPhotoCache.containsKey(booking.getId())
                ? bookingPartnerPhotoCache.get(booking.getId())
                : "";
        assignedPartnerRating = bookingPartnerRatingCache.containsKey(booking.getId())
                ? bookingPartnerRatingCache.get(booking.getId())
                : 0d;
        assignedPartnerRatingCount = bookingPartnerRatingCountCache.containsKey(booking.getId())
                ? bookingPartnerRatingCountCache.get(booking.getId())
                : 0;
        showTrack();
        if (!isBookingClosed(booking)) {
            fetchCachedBookingFromBackend(booking.getId());
        }
    }

    private String readableBookingStatus(String status) {
        String value = normalizeRemoteStatus(status);
        if ("accepted".equals(value)) return "Accepted";
        if ("on_the_way".equals(value)) return "On the way";
        if ("arrived".equals(value)) return "Arrived";
        if ("started".equals(value)) return "In service";
        if ("amount_pending".equals(value)) return "Payment due";
        return "Booked";
    }

    private Booking selectedBookingFrom(List<Booking> bookings) {
        if (bookings == null || bookings.isEmpty()) {
            selectedTrackBookingId = "";
            return null;
        }
        String wanted = !TextUtils.isEmpty(selectedTrackBookingId)
                ? selectedTrackBookingId
                : latestBooking == null ? "" : latestBooking.getId();
        if (!TextUtils.isEmpty(wanted)) {
            for (Booking booking : bookings) {
                if (wanted.equals(booking.getId())) {
                    selectedTrackBookingId = booking.getId();
                    return booking;
                }
            }
        }
        selectedTrackBookingId = bookings.get(0).getId();
        return bookings.get(0);
    }

    private boolean isBookingAssigned(Booking booking) {
        if (booking != null && latestBooking != null && booking.getId().equals(latestBooking.getId())) {
            return isPartnerAcceptedStatus(remoteBookingStatus) || partnerAssigned;
        }
        return isPartnerAcceptedStatus(bookingStatusFor(booking));
    }

    private Service primaryService(Booking booking) {
        if (booking == null || booking.getItems().isEmpty()) {
            return selectedService == null ? serviceById("ac") : selectedService;
        }
        return serviceById(booking.getItems().get(0).getService().getId());
    }

