    private void refreshBookingStepper(boolean confirmPage) {
        if (bookingStepperContainer == null) {
            return;
        }
        bookingStepperContainer.removeAllViews();
        boolean addressDone = confirmPage || isBookingAddressReady();
        boolean confirmDone = confirmPage;

        LinearLayout dots = horizontal();
        dots.setGravity(Gravity.CENTER);
        dots.addView(bookingStepCircle("1", true), new LinearLayout.LayoutParams(dp(36), dp(36)));
        dots.addView(bookingStepLine(addressDone), new LinearLayout.LayoutParams(0, dp(2), 1));
        dots.addView(bookingStepCircle("2", addressDone), new LinearLayout.LayoutParams(dp(36), dp(36)));
        dots.addView(bookingStepLine(confirmDone), new LinearLayout.LayoutParams(0, dp(2), 1));
        dots.addView(bookingStepCircle("3", confirmDone), new LinearLayout.LayoutParams(dp(36), dp(36)));
        bookingStepperContainer.addView(dots);

        LinearLayout labels = horizontal();
        labels.addView(bookingStepLabel("Service", true), new LinearLayout.LayoutParams(0, -2, 1));
        labels.addView(bookingStepLabel("Address", addressDone), new LinearLayout.LayoutParams(0, -2, 1));
        labels.addView(bookingStepLabel("Confirm", confirmDone), new LinearLayout.LayoutParams(0, -2, 1));
        bookingStepperContainer.addView(labels, margin(-1, -2, 0, 6, 0, 0));
    }

