    private boolean isBookingAddressReady() {
        return TextUtils.isEmpty(bookingAddressError());
    }

    private String bookingAddressError() {
        if (TextUtils.isEmpty(bookingAddressMode)) {
            return "Select current location or manual address";
        }
        if ("manual_freeform".equals(bookingAddressMode)) {
            return fieldValue(addressInput).length() >= 10 ? "" : "Enter the complete service address";
        }
        if (TextUtils.isEmpty(fieldValue(houseFlatInput))) {
            return "Enter house or flat number";
        }
        if ("current".equals(bookingAddressMode)) {
            if (!hasServiceLocation || addressInput == null) {
                return "Wait for current location detection";
            }
            String detected = fieldValue(addressInput);
            if (TextUtils.isEmpty(detected) || detected.toLowerCase(Locale.US).startsWith("detecting")) {
                return "Wait for current location detection";
            }
            return "";
        }
        if (TextUtils.isEmpty(fieldValue(addressInput))) {
            return "Enter street, locality and area";
        }
        if (TextUtils.isEmpty(fieldValue(cityInput))) {
            return "Enter city";
        }
        if (TextUtils.isEmpty(fieldValue(stateInput))) {
            return "Enter state";
        }
        if (!fieldValue(pinCodeInput).matches("\\d{6}")) {
            return "Enter a valid 6-digit PIN code";
        }
        return "";
    }

