    private FrameLayout laundryItemCard(String item) {
        FrameLayout card = new FrameLayout(this);
        card.setPadding(dp(8), dp(9), dp(8), dp(7));
        LinearLayout content = vertical();
        content.setGravity(Gravity.CENTER_HORIZONTAL);
        FrameLayout artwork = new FrameLayout(this);
        artwork.setBackground(round(Color.rgb(255, 242, 246), dp(26)));
        View image = laundryItemVisual(item, 46);
        artwork.addView(image, new FrameLayout.LayoutParams(dp(46), dp(46), Gravity.CENTER));
        content.addView(artwork, new LinearLayout.LayoutParams(dp(56), dp(56)));
        TextView label = text(laundryItemDisplayName(item), 10, BLACK, true);
        label.setGravity(Gravity.CENTER);
        label.setMaxLines(2);
        label.setEllipsize(TextUtils.TruncateAt.END);
        label.setIncludeFontPadding(false);
        content.addView(label, margin(-1, 30, 0, 7, 0, 0));
        card.addView(content, new FrameLayout.LayoutParams(-1, -1));
        TextView check = text("✓", 9, Color.WHITE, true);
        check.setGravity(Gravity.CENTER);
        check.setBackground(round(BOOKING_THEME, dp(11)));
        check.setVisibility(View.GONE);
        FrameLayout.LayoutParams checkParams = new FrameLayout.LayoutParams(dp(20), dp(20), Gravity.RIGHT | Gravity.TOP);
        checkParams.setMargins(0, dp(2), dp(2), 0);
        card.addView(check, checkParams);
        card.setTag(check);
        card.setContentDescription("Laundry item: " + item);
        card.setOnClickListener(view -> updateLaundryItemQuantity(item, selectedLaundryItems.containsKey(item) ? -1 : 1));
        addPressAnimation(card);
        laundryItemCards.put(item, card);
        styleLaundryItemCard(card, false);
        return card;
    }

    private View laundryItemVisual(String item, int size) {
        // Keep the selector visually consistent and lightweight. The previous photorealistic
        // generated PNGs varied in style and used considerably more memory on low-end devices.
        return new LaundryBookingIconView(laundryItemIconType(item));
    }

    private String laundryItemDisplayName(String item) {
        if ("Lowers / Track Pants".equals(item)) return "Track Pants";
        if ("Suit / Kurta".equals(item)) return "Suit / Kurta";
        return item;
    }

    private String laundryItemImageName(String item) {
        if ("T-Shirts".equals(item)) return "laundry_item_tshirt";
        if ("Shirts".equals(item)) return "laundry_item_shirt";
        if ("Lowers / Track Pants".equals(item)) return "laundry_item_trackpants";
        if ("Jeans".equals(item)) return "laundry_item_jeans";
        if ("Bed Sheet".equals(item)) return "laundry_item_bedsheet";
        if ("Blanket".equals(item)) return "laundry_item_blanket";
        if ("Pillow Cover".equals(item)) return "laundry_item_pillow_cover";
        if ("Curtain".equals(item)) return "laundry_item_curtain";
        if ("Towel".equals(item)) return "laundry_item_towel";
        if ("Saree".equals(item)) return "laundry_item_saree";
        if ("Suit / Kurta".equals(item)) return "laundry_item_kurta";
        if ("Jacket".equals(item)) return "laundry_item_jacket";
        if ("Shoes".equals(item)) return "laundry_item_shoes";
        return "";
    }

    private String laundryItemIconType(String item) {
        if ("Lowers / Track Pants".equals(item) || "Jeans".equals(item)) return "pants";
        if ("Bed Sheet".equals(item) || "Blanket".equals(item) || "Pillow Cover".equals(item)) return "bedding";
        if ("Curtain".equals(item)) return "curtain";
        if ("Towel".equals(item)) return "folded";
        if ("Saree".equals(item) || "Suit / Kurta".equals(item)) return "dress";
        if ("Jacket".equals(item)) return "jacket";
        if ("Shoes".equals(item)) return "shoes";
        if ("Others".equals(item)) return "more";
        return "shirt";
    }

    private void updateLaundryItemQuantity(String item, int delta) {
        int next = Math.max(0, (selectedLaundryItems.containsKey(item) ? selectedLaundryItems.get(item) : 0) + delta);
        if (next == 0) selectedLaundryItems.remove(item); else selectedLaundryItems.put(item, next);
        refreshLaundryItemSelection();
    }

    private void refreshLaundryItemSelection() {
        for (Map.Entry<String, FrameLayout> entry : laundryItemCards.entrySet()) {
            styleLaundryItemCard(entry.getValue(), selectedLaundryItems.containsKey(entry.getKey()));
        }
        if (laundrySelectedItemsContainer == null || laundrySelectedItemsBadge == null) return;
        int quantity = 0;
        for (Integer value : selectedLaundryItems.values()) quantity += value == null ? 0 : value;
        laundrySelectedItemsBadge.setText(selectedLaundryItems.isEmpty() ? "0 selected" : quantity + " item" + (quantity == 1 ? "" : "s"));
        laundrySelectedItemsContainer.removeAllViews();
        if (selectedLaundryItems.isEmpty()) {
            TextView empty = text("No items selected yet. Choose from the options above.", 10, MUTED, false);
            empty.setPadding(dp(3), dp(6), dp(3), dp(6));
            laundrySelectedItemsContainer.addView(empty);
            return;
        }
        for (Map.Entry<String, Integer> entry : selectedLaundryItems.entrySet()) {
            laundrySelectedItemsContainer.addView(laundrySelectedItemRow(entry.getKey(), entry.getValue()), margin(-1, 38, 0, 4, 0, 0));
        }
    }

    private View laundrySelectedItemRow(String item, int quantity) {
        LinearLayout row = horizontal();
        row.setGravity(Gravity.CENTER_VERTICAL);
        row.setPadding(dp(2), 0, dp(2), 0);
        row.addView(laundryItemVisual(item, 28), new LinearLayout.LayoutParams(dp(32), dp(32)));
        TextView name = text(item, 10, BLACK, true);
        name.setSingleLine(true);
        name.setEllipsize(TextUtils.TruncateAt.END);
        row.addView(name, margin(0, -2, 7, 0, 0, 0, 1));
        TextView minus = laundryQuantityButton("−");
        minus.setOnClickListener(view -> updateLaundryItemQuantity(item, -1));
        row.addView(minus, new LinearLayout.LayoutParams(dp(25), dp(25)));
        TextView count = text(String.valueOf(quantity), 11, BLACK, true);
        count.setGravity(Gravity.CENTER);
        row.addView(count, new LinearLayout.LayoutParams(dp(24), dp(25)));
        TextView plus = laundryQuantityButton("+");
        plus.setOnClickListener(view -> updateLaundryItemQuantity(item, 1));
        row.addView(plus, new LinearLayout.LayoutParams(dp(25), dp(25)));
        TextView remove = text("×", 17, BOOKING_THEME, true);
        remove.setGravity(Gravity.CENTER);
        remove.setOnClickListener(view -> { selectedLaundryItems.remove(item); refreshLaundryItemSelection(); });
        row.addView(remove, margin(27, 27, 4, 0, 0, 0));
        return row;
    }

    private TextView laundryQuantityButton(String value) {
        TextView button = text(value, 14, BOOKING_THEME, true);
        button.setGravity(Gravity.CENTER);
        button.setBackground(round(Color.rgb(255, 237, 243), dp(13)));
        addPressAnimation(button);
        return button;
    }

    private void styleLaundryItemCard(FrameLayout card, boolean selected) {
        card.setBackground(stroke(selected ? Color.rgb(255, 246, 249) : Color.WHITE,
                selected ? BOOKING_THEME : Color.rgb(239, 230, 232), dp(9)));
        card.setElevation(selected ? dp(3) : dp(1));
        Object tag = card.getTag();
        if (tag instanceof TextView) ((TextView) tag).setVisibility(selected ? View.VISIBLE : View.GONE);
    }

    private String laundryItemsSummary() {
        List<String> summary = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : selectedLaundryItems.entrySet()) {
            int count = entry.getValue() == null ? 0 : entry.getValue();
            if (count > 0) summary.add(entry.getKey() + " x" + count);
        }
        return TextUtils.join(", ", summary);
    }

    private void addCleaningBookingOptions() {
        LinearLayout section = vertical();
        section.setPadding(0, dp(12), 0, dp(10));
        section.addView(text("Select Cleaning Type", 15, BLACK, true));
        section.addView(text("Choose the type of cleaning service you need", 11, MUTED, false), margin(-1, -2, 0, 3, 0, 12));

        String[][] types = {
                {"Home Cleaning", "General cleaning\nof your home"},
                {"Deep Cleaning", "Thorough & deep\ncleaning"},
                {"Bathroom Cleaning", "Bathroom & toilet\ncleaning"},
                {"Room Cleaning", "Bedroom & room\ncleaning"}
        };
        int[] artwork = {
                R.drawable.cleaning_type_home_art,
                R.drawable.cleaning_type_deep_art,
                R.drawable.cleaning_type_bathroom_art,
                R.drawable.cleaning_type_room_art
        };
        LinearLayout row = horizontal();
        List<LinearLayout> cards = new ArrayList<>();
        for (int index = 0; index < types.length; index++) {
            String[] type = types[index];
            LinearLayout card = cleaningTypeCard(type[0], type[1], artwork[index]);
            cards.add(card);
            card.setOnClickListener(view -> {
                selectedCleaningType = type[0];
                for (LinearLayout candidate : cards) {
                    styleCleaningTypeCard(candidate, selectedCleaningType.equals(candidate.getTag()));
                }
            });
            addPressAnimation(card);
            row.addView(card, margin(0, 126, 4, 0, 4, 0, 1));
        }
        section.addView(row);
        if (bookingForm != null) {
            bookingForm.addView(section);
            bookingForm.addView(insetDivider(0));
        }
    }

