    private final class ApplianceBookingArtView extends View {
        private final String type;
        private final Paint artPaint = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final Paint fillPaint = new Paint(Paint.ANTI_ALIAS_FLAG);

        ApplianceBookingArtView(String type) {
            super(MainActivity.this);
            this.type = type;
            artPaint.setStyle(Paint.Style.STROKE);
            artPaint.setStrokeWidth(dp(2));
            artPaint.setStrokeJoin(Paint.Join.ROUND);
            artPaint.setColor(Color.rgb(68, 76, 82));
            fillPaint.setColor(Color.rgb(231, 236, 237));
        }

        @Override protected void onDraw(Canvas canvas) {
            super.onDraw(canvas);
            float w = getWidth(), h = getHeight();
            if ("fridge".equals(type)) {
                RectF fridge = new RectF(w * .29f, h * .12f, w * .70f, h * .88f);
                canvas.drawRoundRect(fridge, dp(5), dp(5), fillPaint);
                canvas.drawRoundRect(fridge, dp(5), dp(5), artPaint);
                canvas.drawLine(w * .29f, h * .47f, w * .70f, h * .47f, artPaint);
                canvas.drawLine(w * .62f, h * .22f, w * .62f, h * .38f, artPaint);
                canvas.drawLine(w * .62f, h * .57f, w * .62f, h * .78f, artPaint);
                canvas.drawLine(w * .35f, h * .90f, w * .35f, h * .84f, artPaint);
                canvas.drawLine(w * .65f, h * .90f, w * .65f, h * .84f, artPaint);
                return;
            }
            RectF machine = new RectF(w * .15f, h * .15f, w * .85f, h * .86f);
            canvas.drawRoundRect(machine, dp(7), dp(7), fillPaint);
            canvas.drawRoundRect(machine, dp(7), dp(7), artPaint);
            canvas.drawLine(w * .15f, h * .34f, w * .85f, h * .34f, artPaint);
            fillPaint.setColor(Color.rgb(255, 255, 255));
            canvas.drawCircle(w * .50f, h * .62f, w * .20f, fillPaint);
            canvas.drawCircle(w * .50f, h * .62f, w * .20f, artPaint);
            fillPaint.setColor(Color.rgb(196, 210, 214));
            canvas.drawCircle(w * .50f, h * .62f, w * .13f, fillPaint);
            canvas.drawCircle(w * .50f, h * .62f, w * .13f, artPaint);
            canvas.drawCircle(w * .28f, h * .25f, dp(3), artPaint);
            canvas.drawCircle(w * .39f, h * .25f, dp(3), artPaint);
            fillPaint.setColor(Color.rgb(231, 236, 237));
        }
    }

