    private final class LaundryBookingIconView extends View {
        private final String type;
        private final Paint iconPaint = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final Path iconPath = new Path();

        LaundryBookingIconView(String type) {
            super(MainActivity.this);
            this.type = type == null ? "shirt" : type;
            iconPaint.setColor(BOOKING_THEME);
            iconPaint.setStyle(Paint.Style.STROKE);
            iconPaint.setStrokeWidth(dp(2));
            iconPaint.setStrokeCap(Paint.Cap.ROUND);
            iconPaint.setStrokeJoin(Paint.Join.ROUND);
        }

        @Override protected void onDraw(Canvas canvas) {
            super.onDraw(canvas);
            float w = getWidth(), h = getHeight(), cx = w / 2f;
            if ("iron".equals(type)) { drawIron(canvas, w, h, false); return; }
            if ("wash_iron".equals(type)) { drawShirt(canvas, w * .56f, h, 0); drawIron(canvas, w, h, true); return; }
            if ("dry_clean".equals(type)) { drawJacket(canvas, w, h); return; }
            if ("wash_fold".equals(type)) { drawShirt(canvas, w, h, 0); canvas.drawLine(cx - w*.22f,h*.78f,cx+w*.22f,h*.78f,iconPaint); return; }
            if ("pants".equals(type)) { drawPants(canvas,w,h); return; }
            if ("folded".equals(type)) { drawFolded(canvas,w,h); return; }
            if ("bedding".equals(type)) { drawBedding(canvas,w,h); return; }
            if ("curtain".equals(type)) { drawCurtain(canvas, w, h); return; }
            if ("dress".equals(type)) { drawDress(canvas,w,h); return; }
            if ("jacket".equals(type)) { drawJacket(canvas,w,h); return; }
            if ("shoes".equals(type)) { drawShoes(canvas,w,h); return; }
            if ("more".equals(type)) { drawMore(canvas,w,h); return; }
            drawShirt(canvas,w,h,0);
        }

        private void drawShirt(Canvas c,float w,float h,float offsetX) {
            float l=offsetX+w*.17f,r=offsetX+w*.83f,t=h*.17f,b=h*.84f;
            iconPath.reset();
            iconPath.moveTo(l+w*.18f,t); iconPath.lineTo(l,t+h*.18f); iconPath.lineTo(l+w*.12f,t+h*.34f);
            iconPath.lineTo(l+w*.24f,t+h*.26f); iconPath.lineTo(l+w*.25f,b); iconPath.lineTo(r-w*.25f,b);
            iconPath.lineTo(r-w*.24f,t+h*.26f); iconPath.lineTo(r-w*.12f,t+h*.34f); iconPath.lineTo(r,t+h*.18f);
            iconPath.lineTo(r-w*.18f,t); iconPath.quadTo(offsetX+w*.5f,t+h*.22f,l+w*.18f,t); c.drawPath(iconPath,iconPaint);
        }
        private void drawJacket(Canvas c,float w,float h){
            drawShirt(c,w,h,0); c.drawLine(w*.5f,h*.3f,w*.5f,h*.83f,iconPaint);
            c.drawLine(w*.37f,h*.2f,w*.5f,h*.38f,iconPaint); c.drawLine(w*.63f,h*.2f,w*.5f,h*.38f,iconPaint);
        }
        private void drawIron(Canvas c,float w,float h,boolean small){
            float s=small?.58f:1f, left=small?w*.43f:w*.1f, top=small?h*.43f:h*.18f;
            RectF base=new RectF(left,top+h*.32f*s,left+w*.72f*s,top+h*.57f*s); c.drawRoundRect(base,dp(3),dp(3),iconPaint);
            iconPath.reset(); iconPath.moveTo(left+w*.13f*s,top+h*.32f*s); iconPath.quadTo(left+w*.28f*s,top,left+w*.58f*s,top+h*.12f*s); iconPath.lineTo(left+w*.68f*s,top+h*.32f*s); c.drawPath(iconPath,iconPaint);
            c.drawLine(left+w*.18f*s,top+h*.68f*s,left+w*.7f*s,top+h*.68f*s,iconPaint);
        }
        private void drawPants(Canvas c,float w,float h){
            iconPath.reset(); iconPath.moveTo(w*.27f,h*.14f); iconPath.lineTo(w*.73f,h*.14f); iconPath.lineTo(w*.68f,h*.84f); iconPath.lineTo(w*.51f,h*.84f); iconPath.lineTo(w*.5f,h*.42f); iconPath.lineTo(w*.42f,h*.84f); iconPath.lineTo(w*.24f,h*.84f); iconPath.close(); c.drawPath(iconPath,iconPaint);
        }
        private void drawFolded(Canvas c,float w,float h){
            c.drawRoundRect(new RectF(w*.18f,h*.25f,w*.82f,h*.75f),dp(3),dp(3),iconPaint); c.drawLine(w*.5f,h*.25f,w*.5f,h*.75f,iconPaint); c.drawLine(w*.18f,h*.5f,w*.82f,h*.5f,iconPaint);
        }
        private void drawBedding(Canvas c,float w,float h){
            c.drawRoundRect(new RectF(w*.13f,h*.27f,w*.87f,h*.74f),dp(4),dp(4),iconPaint); c.drawRoundRect(new RectF(w*.22f,h*.36f,w*.5f,h*.55f),dp(3),dp(3),iconPaint); c.drawLine(w*.13f,h*.65f,w*.87f,h*.65f,iconPaint);
        }
        private void drawCurtain(Canvas c,float w,float h){
            c.drawLine(w*.14f,h*.18f,w*.86f,h*.18f,iconPaint);
            for(int i=0;i<4;i++){
                float x=w*(.22f+i*.18f);
                c.drawLine(x,h*.18f,x,h*.72f,iconPaint);
                c.drawArc(new RectF(x-w*.09f,h*.48f,x+w*.09f,h*.82f),180,180,false,iconPaint);
            }
        }
        private void drawDress(Canvas c,float w,float h){
            iconPath.reset(); iconPath.moveTo(w*.42f,h*.15f); iconPath.lineTo(w*.58f,h*.15f); iconPath.lineTo(w*.63f,h*.38f); iconPath.lineTo(w*.82f,h*.83f); iconPath.lineTo(w*.18f,h*.83f); iconPath.lineTo(w*.37f,h*.38f); iconPath.close(); c.drawPath(iconPath,iconPaint); c.drawLine(w*.37f,h*.38f,w*.63f,h*.38f,iconPaint);
        }
        private void drawShoes(Canvas c,float w,float h){
            iconPath.reset();
            iconPath.moveTo(w*.16f,h*.57f); iconPath.lineTo(w*.38f,h*.57f); iconPath.quadTo(w*.48f,h*.72f,w*.71f,h*.69f);
            iconPath.quadTo(w*.84f,h*.69f,w*.84f,h*.81f); iconPath.lineTo(w*.84f,h*.86f); iconPath.lineTo(w*.16f,h*.86f); iconPath.close();
            c.drawPath(iconPath,iconPaint); c.drawLine(w*.23f,h*.68f,w*.43f,h*.68f,iconPaint);
            c.drawLine(w*.18f,h*.86f,w*.84f,h*.86f,iconPaint);
        }
        private void drawMore(Canvas c,float w,float h){
            iconPaint.setStyle(Paint.Style.FILL); c.drawCircle(w*.28f,h*.5f,dp(2),iconPaint); c.drawCircle(w*.5f,h*.5f,dp(2),iconPaint); c.drawCircle(w*.72f,h*.5f,dp(2),iconPaint); iconPaint.setStyle(Paint.Style.STROKE);
        }
    }

    private void addBookingVisitTypePanel() {
        LinearLayout card = bookingPanel(16);
        card.addView(bookingSectionHeader("\u2726", "Choose Visit Type", "Pick Normal or Premier expert support."));

        LinearLayout row = horizontal();
        FrameLayout normal = bookingVisitOption("Normal Visit", "Standard visit", "\u25A3", false);
        FrameLayout premium = bookingVisitOption("Premier Visit", "Priority expert", "\u272A", true);
        normal.setOnClickListener(view -> {
            selectedServiceTier = "Normal";
            styleBookingVisitOption(normal, false);
            styleBookingVisitOption(premium, true);
            updateVisitTypeChip();
        });
        premium.setOnClickListener(view -> {
            selectedServiceTier = "Premier";
            styleBookingVisitOption(normal, false);
            styleBookingVisitOption(premium, true);
            updateVisitTypeChip();
        });
        row.addView(normal, margin(0, 86, 0, 14, 5, 0, 1));
        row.addView(premium, margin(0, 86, 5, 14, 0, 0, 1));
        card.addView(row);
        animateIn(card, 90);
        screenContent.addView(card, margin(-1, -2, 16, 0, 16, 14));
    }

    private FrameLayout bookingVisitOption(String title, String subtitle, String icon, boolean premium) {
        FrameLayout frame = new FrameLayout(this);
        frame.setClipChildren(true);
        frame.setClipToPadding(true);

        LinearLayout content = vertical();
        content.setGravity(Gravity.CENTER);
        content.setPadding(dp(8), dp(8), dp(8), dp(8));
        TextView mark = text(icon, 22, premium ? PREMIER : ORANGE, true);
        mark.setGravity(Gravity.CENTER);
        mark.setBackground(round(premium ? PREMIER_SOFT : ORANGE_SOFT, dp(18)));
        content.addView(mark, new LinearLayout.LayoutParams(dp(38), dp(38)));
        TextView name = text(title, 13, BLACK, true);
        name.setGravity(Gravity.CENTER);
        content.addView(name, margin(-1, -2, 0, 6, 0, 0));
        TextView sub = text(subtitle, 11, MUTED, false);
        sub.setGravity(Gravity.CENTER);
        content.addView(sub);
        frame.addView(content, new FrameLayout.LayoutParams(-1, -1));

        TextView radio = text("", 18, ORANGE, true);
        radio.setGravity(Gravity.CENTER);
        FrameLayout.LayoutParams radioParams = new FrameLayout.LayoutParams(dp(28), dp(28), Gravity.LEFT | Gravity.TOP);
        radioParams.setMargins(dp(8), dp(8), 0, 0);
        frame.addView(radio, radioParams);
        frame.setTag(radio);
        addShineOverlay(frame, 0.42f);
        addPressAnimation(frame);
        styleBookingVisitOption(frame, premium);
        return frame;
    }

    private void styleBookingVisitOption(FrameLayout frame, boolean premium) {
        boolean selected = premium ? isPremierVisitSelected() : "Normal".equals(selectedServiceTier);
        int accent = premium ? PREMIER : ORANGE;
        int soft = premium ? PREMIER_SOFT : ORANGE_SOFT;
        frame.setBackground(serviceTierSurfaceDrawable(selected, accent, soft));
        frame.setElevation(selected ? dp(9) : dp(3));
        frame.setScaleX(selected ? 1.02f : 1f);
        frame.setScaleY(selected ? 1.03f : 1f);
        Object tag = frame.getTag();
        if (tag instanceof TextView) {
            TextView radio = (TextView) tag;
            radio.setText(selected ? "\u25C9" : "\u25CB");
            radio.setTextColor(selected ? accent : Color.rgb(165, 165, 165));
        }
    }

    private boolean isPremierVisitSelected() {
        return "Premier".equals(selectedServiceTier) || "Premium".equals(selectedServiceTier);
    }

    private String visitTypeLabel() {
        return isPremierVisitSelected() ? "Premier Visit" : "Normal Visit";
    }

    private void updateVisitTypeChip() {
        if (selectedTierChip != null) {
            selectedTierChip.setText(visitTypeLabel());
            selectedTierChip.setTextColor(isPremierVisitSelected() ? PREMIER : ORANGE);
            selectedTierChip.setBackground(round(isPremierVisitSelected() ? PREMIER_SOFT : ORANGE_SOFT, dp(12)));
            selectedTierChip.animate().cancel();
            selectedTierChip.setScaleX(0.96f);
            selectedTierChip.setScaleY(0.96f);
            selectedTierChip.animate().scaleX(1f).scaleY(1f).setDuration(160).start();
        }
    }

