    private TextView bookingDateChip(Calendar day) {
        String label = dateChipLabel(day);
        TextView chip = text(label, 13, BLACK, true);
        chip.setGravity(Gravity.CENTER);
        chip.setLineSpacing(dp(2), 1f);
        chip.setPadding(0, dp(6), 0, dp(6));
        addPressAnimation(chip);
        return chip;
    }

    private String dateChipLabel(Calendar day) {
        return new java.text.SimpleDateFormat("EEE", Locale.US).format(day.getTime())
                + "\n" + day.get(Calendar.DAY_OF_MONTH)
                + "\n" + monthName(day.get(Calendar.MONTH));
    }

    private void styleDateChip(TextView chip, boolean selected) {
        chip.setTextColor(selected ? Color.WHITE : BLACK);
        chip.setTypeface(Typeface.DEFAULT, selected ? Typeface.BOLD : Typeface.NORMAL);
        chip.setBackground(selected ? bookGlowButtonDrawable() : stroke(Color.WHITE, Color.rgb(238, 225, 221), dp(10)));
        chip.setElevation(selected ? dp(7) : dp(2));
    }

    private String dateLabel(Calendar day) {
        return String.format(Locale.US, "%02d %s %d",
                day.get(Calendar.DAY_OF_MONTH),
                monthName(day.get(Calendar.MONTH)),
                day.get(Calendar.YEAR));
    }

