    private void addTimeSlotRows(LinearLayout parent) {
        String[] slots = {
                "09:00 AM - 11:00 AM",
                "10:00 AM - 12:00 PM",
                "12:00 PM - 02:00 PM",
                "02:00 PM - 04:00 PM",
                "04:00 PM - 06:00 PM",
                "06:00 PM - 08:00 PM"
        };
        List<TextView> slotViews = new ArrayList<>();
        for (int rowIndex = 0; rowIndex < 3; rowIndex++) {
            LinearLayout row = horizontal();
            for (int col = 0; col < 2; col++) {
                int index = rowIndex * 2 + col;
                TextView slot = bookingTimeSlot(slots[index]);
                final TextView selectedSlot = slot;
                slot.setOnClickListener(view -> {
                    selectedTime = selectedSlot.getText().toString();
                    for (TextView item : slotViews) {
                        styleTimeSlot(item, item == selectedSlot);
                    }
                    refreshBookingStepper(false);
                });
                slotViews.add(slot);
                row.addView(slot, margin(0, 42, 4, 0, 4, 8, 1));
            }
            parent.addView(row);
        }
        for (TextView slot : slotViews) {
            styleTimeSlot(slot, slot.getText().toString().equals(selectedTime));
        }
    }

    private TextView bookingTimeSlot(String slot) {
        TextView view = text(slot, 10, BLACK, false);
        view.setGravity(Gravity.CENTER);
        view.setSingleLine(true);
        view.setIncludeFontPadding(false);
        view.setPadding(dp(4), 0, dp(4), 0);
        addPressAnimation(view);
        return view;
    }

    private void styleTimeSlot(TextView view, boolean selected) {
        view.setTextColor(selected ? Color.WHITE : BLACK);
        view.setTypeface(Typeface.DEFAULT, selected ? Typeface.BOLD : Typeface.NORMAL);
        view.setBackground(selected ? bookGlowButtonDrawable() : stroke(Color.WHITE, Color.rgb(238, 225, 221), dp(10)));
        view.setElevation(selected ? dp(7) : dp(2));
    }

    private void addBookingAddressPanel(Service service) {
        LinearLayout card = vertical();
        card.setPadding(0, dp(8), 0, dp(8));
        card.addView(bookingSectionHeader(
                R.drawable.booking_icon_service_address,
                "Service Address",
                "laundry".equals(service.getId())
                        ? "Add the exact address so our partner can reach you easily"
                        : "Add the exact entrance and property details for your expert."
        ));

        TextView currentRadio = text("\u25CB", 22, MUTED, true);
        TextView manualRadio = text("\u25CB", 22, MUTED, true);
        LinearLayout currentRow = bookingAddressOption(
                currentRadio,
                R.drawable.booking_icon_current_location,
                "Use my current location",
                "laundry".equals(service.getId()) ? "Detect location automatically" : "Use your location, then add house or flat details",
                true
        );
        LinearLayout manualRow = bookingAddressOption(
                manualRadio,
                R.drawable.booking_icon_manual_address,
                "Enter address manually",
                "laundry".equals(service.getId()) ? "Fill in the address details" : "Provide complete property and locality details",
                false
        );

        addressInput = bookingAddressField("Detected service address");
        addressInput.setSingleLine(false);
        addressInput.setMinLines(2);
        addressInput.setMaxLines(3);
        addressInput.setGravity(Gravity.TOP);
        houseFlatInput = bookingAddressField("e.g. House 12 or Flat 3B");
        buildingInput = bookingAddressField("Apartment, society or building name");
        floorInput = bookingAddressField("e.g. 2nd floor");
        roomInput = bookingAddressField("e.g. Room 204");
        landmarkInput = bookingAddressField("Nearby landmark (optional)");
        cityInput = bookingAddressField("City");
        stateInput = bookingAddressField("State");
        stateInput.setText("Assam");
        pinCodeInput = bookingAddressField("6-digit PIN code");
        pinCodeInput.setInputType(InputType.TYPE_CLASS_NUMBER);
        pinCodeInput.setFilters(new InputFilter[]{new InputFilter.LengthFilter(6)});

        addressDetailsContainer = vertical();
        addressDetailsContainer.setPadding(dp(12), dp(12), dp(12), dp(12));
        addressDetailsContainer.setBackground(stroke(Color.rgb(255, 252, 252), Color.rgb(241, 221, 222), dp(15)));

        boolean laundryAddress = "laundry".equals(service.getId());
        addressLineLabel = text(laundryAddress ? "Detected location" : "Detected service address", 12, BLACK, true);
        addressDetailsContainer.addView(addressLineLabel);
        if (laundryAddress) {
            LinearLayout detectedRow = horizontal();
            detectedRow.setGravity(Gravity.CENTER_VERTICAL);
            detectedRow.setBackground(stroke(Color.rgb(255, 247, 249), Color.rgb(255, 235, 241), dp(12)));
            detectedRow.setPadding(dp(6), dp(5), dp(6), dp(5));
            addressInput.setBackgroundColor(Color.TRANSPARENT);
            detectedRow.addView(addressInput, new LinearLayout.LayoutParams(0, dp(66), 1));
            TextView change = text("✎  Change", 11, BOOKING_THEME, true);
            change.setGravity(Gravity.CENTER);
            change.setBackground(stroke(Color.WHITE, Color.rgb(248, 211, 222), dp(10)));
            change.setOnClickListener(view -> manualRow.performClick());
            detectedRow.addView(change, new LinearLayout.LayoutParams(dp(82), dp(42)));
            addressDetailsContainer.addView(detectedRow, margin(-1, -2, 0, 5, 0, 10));
        } else {
            addressDetailsContainer.addView(addressInput, margin(-1, 66, 0, 5, 0, 10));
        }
        addressDetailsContainer.addView(addressFieldBlock("House / Flat number *", houseFlatInput));

        manualAddressExtraContainer = vertical();
        manualAddressExtraContainer.addView(addressFieldBlock("Apartment / Building", buildingInput));
        manualAddressExtraContainer.addView(addressFieldPair(
                "Floor", floorInput,
                "Room number", roomInput
        ));
        manualAddressExtraContainer.addView(addressFieldBlock("Landmark", landmarkInput));
        manualAddressExtraContainer.addView(addressFieldPair(
                "City *", cityInput,
                "State *", stateInput
        ));
        manualAddressExtraContainer.addView(addressFieldBlock("PIN code *", pinCodeInput));
        manualAddressExtraContainer.setVisibility(View.GONE);
        addressDetailsContainer.addView(manualAddressExtraContainer);

        TextView addressHint = text(
                "House/flat number is required even when your location is detected.",
                11,
                MUTED,
                false
        );
        addressHint.setLineSpacing(dp(2), 1f);
        addressDetailsContainer.addView(addressHint, margin(-1, -2, 0, 4, 0, 0));

        currentRow.setOnClickListener(view -> {
            styleAddressOption(currentRow, currentRadio, true);
            styleAddressOption(manualRow, manualRadio, false);
            bookingAddressMode = "current";
            addressDetailsContainer.setVisibility(View.VISIBLE);
            manualAddressExtraContainer.setVisibility(View.GONE);
            setAddressInputMode(false);
            hasServiceLocation = false;
            addressInput.setText("Detecting your current service location...");
            requestCurrentLocation();
        });
        manualRow.setOnClickListener(view -> {
            styleAddressOption(currentRow, currentRadio, false);
            styleAddressOption(manualRow, manualRadio, true);
            boolean switchedFromCurrent = "current".equals(bookingAddressMode);
            bookingAddressMode = "manual";
            hasServiceLocation = false;
            addressDetailsContainer.setVisibility(View.VISIBLE);
            manualAddressExtraContainer.setVisibility(View.VISIBLE);
            setAddressInputMode(true);
            if (switchedFromCurrent || addressInput.getText().toString().trim().toLowerCase(Locale.US).startsWith("detecting")) {
                addressInput.setText("");
            }
            addressInput.requestFocus();
            setLocationStatus("Enter the complete property and locality details.", ORANGE);
        });

        addPressAnimation(currentRow);
        addPressAnimation(manualRow);
        if ("laundry".equals(service.getId())) {
            LinearLayout addressChoices = horizontal();
            addressChoices.addView(currentRow, margin(0, 64, 0, 0, 5, 0, 1));
            addressChoices.addView(manualRow, margin(0, 64, 5, 0, 0, 0, 1));
            card.addView(addressChoices, margin(-1, -2, 0, 16, 0, 10));
        } else {
            card.addView(currentRow, margin(-1, 64, 0, 16, 0, 0));
            card.addView(manualRow, margin(-1, 64, 0, 0, 0, 10));
        }
        card.addView(addressDetailsContainer, margin(-1, -2, 0, 0, 0, 12));
        bookingContactContainer = bookingContactSection();
        card.addView(bookingContactContainer, margin(-1, -2, 0, 0, 0, 12));
        card.addView(bookingSafetyNotice());

        styleAddressOption(currentRow, currentRadio, true);
        bookingAddressMode = "current";
        addressDetailsContainer.setVisibility(View.VISIBLE);
        setAddressInputMode(false);
        addressInput.setText("Detecting your current service location...");
        currentRow.postDelayed(() -> {
            requestCurrentLocation();
        }, 250);

        animateIn(card, 150);
        if (bookingForm != null) {
            bookingForm.addView(card, margin(-1, -2, 0, 8, 0, 8));
        } else {
            screenContent.addView(card, margin(-1, -2, 16, 0, 16, 12));
        }
    }

