    private void setAddressInputMode(boolean manual) {
        if (addressLineLabel != null) {
            boolean laundry = selectedService != null && "laundry".equals(selectedService.getId());
            addressLineLabel.setText(manual ? "Street / locality / area *" : (laundry ? "Detected location" : "Detected service address"));
        }
        if (addressInput == null) {
            return;
        }
        addressInput.setHint(manual ? "Street, locality and area" : "Detected service address");
        addressInput.setFocusable(manual);
        addressInput.setFocusableInTouchMode(manual);
        addressInput.setCursorVisible(manual);
        addressInput.setLongClickable(manual);
        addressInput.setTextColor(manual ? BLACK : Color.rgb(78, 86, 98));
        addressInput.setBackground(stroke(
                manual ? Color.WHITE : Color.rgb(247, 250, 247),
                manual ? Color.rgb(231, 211, 212) : Color.rgb(190, 225, 199),
                dp(11)
        ));
    }

