    private void updateServiceMiniMap(String message, boolean exact) {
        if (serviceMiniMap != null) {
            serviceMiniMap.setVisibility(View.VISIBLE);
        }
        if (serviceMiniMapLabel != null) {
            serviceMiniMapLabel.setText(message);
            serviceMiniMapLabel.setTextColor(exact ? GREEN : MUTED);
        }
        if (serviceMiniMapPin != null) {
            serviceMiniMapPin.setBackground(round(exact ? GREEN : Color.rgb(220, 16, 42), dp(18)));
            serviceMiniMapPin.animate().cancel();
            serviceMiniMapPin.setScaleX(0.86f);
            serviceMiniMapPin.setScaleY(0.86f);
            serviceMiniMapPin.animate().scaleX(1f).scaleY(1f).setDuration(180).start();
        }
    }

