    private void addBookingContinueButton(Service service) {
        View button = glassContinueButton("Continue", view -> {
            if (!isBookingAddressReady()) {
                Toast.makeText(this, bookingAddressError(), Toast.LENGTH_SHORT).show();
                return;
            }
            if (!isValidCustomerMobile(bookingPrimaryPhone)) {
                Toast.makeText(this, "Add a valid primary contact number", Toast.LENGTH_SHORT).show();
                showBookingPhoneEditor(true);
                return;
            }
            showBookingConfirm(service);
        });
        if (bookingForm != null) {
            bookingForm.addView(button, margin(-1, 58, 0, 8, 0, 0));
        } else {
            screenContent.addView(button, margin(-1, 58, 16, 0, 16, 28));
        }
    }

    private void showBookingConfirm(Service service) {
        setCurrentScreen("confirm");
        showAppChrome();
        floatingFooter.setVisibility(View.GONE);
        bottomNav.setVisibility(View.GONE);
        setActiveNav(null);
        resetScreen();
        addBookingTopBar();
        addBookingStepperConfirm();

        LinearLayout summary = bookingPanel(18);
        summary.addView(bookingSectionHeader("\u2713", "Confirm Service", "Review your booking before final confirm."));
        summary.addView(confirmRow("Service", service.getName(), service), margin(-1, 64, 0, 18, 0, 8));
        summary.addView(confirmEditableRow("Address", bookingAddressPreview(), R.drawable.booking_icon_service_address, "Change", view -> showAddressEditDialog(service)), margin(-1, -2, 0, 0, 0, 0));
        summary.addView(confirmEditableRow("Contact", formatIndianPhone(bookingPrimaryPhone) + (isValidCustomerMobile(bookingAlternatePhone) ? "\nAlternate: " + formatIndianPhone(bookingAlternatePhone) : ""), "☎", "Edit", view -> showBookingPhoneEditor(true)), margin(-1, -2, 0, 8, 0, 0));
        animateIn(summary, 80);
        screenContent.addView(summary, margin(-1, -2, 16, 8, 16, 14));

        LinearLayout note = bookingPanel(14);
        note.addView(text("No upfront payment", 16, BLACK, true));
        note.addView(text("Final quote and payment happen after expert inspection.", 12, MUTED, false), margin(-1, -2, 0, 4, 0, 0));
        screenContent.addView(note, margin(-1, -2, 16, 0, 16, 14));

        View button = glassContinueButton("Confirm Booking   \u2192", view -> confirmBooking(service));
        screenContent.addView(button, margin(-1, 58, 16, 2, 16, 28));
    }

