    private void showDateTimeEditDialog(Service service) {
        AlertDialog dialog = new AlertDialog.Builder(this).create();
        LinearLayout sheet = vertical();
        sheet.setPadding(dp(18), dp(18), dp(18), dp(16));
        sheet.setBackground(bookingOuterDrawable());
        sheet.addView(text("Edit Date & Time", 20, BLACK, true));
        sheet.addView(text("Choose the most convenient slot.", 12, MUTED, false), margin(-1, -2, 0, 4, 0, 14));

        List<TextView> dateViews = new ArrayList<>();
        LinearLayout dateRow = horizontal();
        Calendar start = Calendar.getInstance();
        start.add(Calendar.DAY_OF_MONTH, 1);
        for (int index = 0; index < 4; index++) {
            Calendar day = (Calendar) start.clone();
            day.add(Calendar.DAY_OF_MONTH, index);
            TextView chip = bookingDateChip(day);
            chip.setTag(dateLabel(day));
            final TextView selectedChip = chip;
            chip.setOnClickListener(view -> {
                selectedDate = String.valueOf(selectedChip.getTag());
                for (TextView item : dateViews) {
                    styleDateChip(item, item == selectedChip);
                }
                refreshBookingStepper(false);
            });
            dateViews.add(chip);
            dateRow.addView(chip, margin(0, 88, 3, 0, 3, 0, 1));
        }
        for (TextView item : dateViews) {
            styleDateChip(item, selectedDate.equals(String.valueOf(item.getTag())));
        }
        sheet.addView(dateRow, margin(-1, -2, 0, 0, 0, 14));

        String[] slots = {"09:00 AM - 11:00 AM", "10:00 AM - 12:00 PM", "12:00 PM - 02:00 PM", "02:00 PM - 04:00 PM"};
        List<TextView> timeViews = new ArrayList<>();
        for (int rowIndex = 0; rowIndex < 2; rowIndex++) {
            LinearLayout row = horizontal();
            for (int col = 0; col < 2; col++) {
                TextView slot = bookingTimeSlot(slots[rowIndex * 2 + col]);
                final TextView selectedSlot = slot;
                slot.setOnClickListener(view -> {
                    selectedTime = selectedSlot.getText().toString();
                    for (TextView item : timeViews) {
                        styleTimeSlot(item, item == selectedSlot);
                    }
                    refreshBookingStepper(false);
                });
                timeViews.add(slot);
                row.addView(slot, margin(0, 42, 4, 0, 4, 8, 1));
            }
            sheet.addView(row);
        }
        for (TextView item : timeViews) {
            styleTimeSlot(item, selectedTime.equals(item.getText().toString()));
        }

        TextView save = orangeButton("Save Slot");
        save.setOnClickListener(view -> {
            dialog.dismiss();
            showBookingConfirm(service);
        });
        sheet.addView(save, margin(-1, 52, 0, 8, 0, 0));
        dialog.setView(sheet);
        dialog.show();
    }

    private void showAddressEditDialog(Service service) {
        AlertDialog dialog = new AlertDialog.Builder(this).create();
        LinearLayout sheet = vertical();
        sheet.setPadding(dp(18), dp(18), dp(18), dp(16));
        sheet.setBackground(bookingOuterDrawable());
        sheet.addView(text("Edit Service Address", 20, BLACK, true));
        sheet.addView(text("Update exact location, house number or landmark.", 12, MUTED, false), margin(-1, -2, 0, 4, 0, 14));

        EditText edit = new EditText(this);
        edit.setText(bookingAddressPreview().startsWith("Location will") ? "" : bookingAddressPreview());
        edit.setHint("Flat/house, street, landmark, city");
        edit.setTextSize(14);
        edit.setMinLines(3);
        edit.setGravity(Gravity.TOP);
        edit.setPadding(dp(14), dp(10), dp(14), dp(10));
        edit.setBackground(stroke(Color.WHITE, Color.rgb(232, 203, 202), dp(14)));
        sheet.addView(edit, margin(-1, 96, 0, 0, 0, 14));

        TextView save = orangeButton("Save Address");
        save.setOnClickListener(view -> {
            String updatedAddress = edit.getText().toString().trim();
            if (updatedAddress.length() < 10) {
                Toast.makeText(this, "Enter the complete service address", Toast.LENGTH_SHORT).show();
                return;
            }
            if (addressInput == null) {
                addressInput = new EditText(this);
            }
            bookingAddressMode = "manual_freeform";
            hasServiceLocation = false;
            addressInput.setText(updatedAddress);
            dialog.dismiss();
            showBookingConfirm(service);
        });
        sheet.addView(save, margin(-1, 52, 0, 0, 0, 0));
        dialog.setView(sheet);
        dialog.show();
    }

    private String bookingAddressPreview() {
        if (!isBookingAddressReady()) {
            return "Location will be confirmed by customer";
        }
        if ("manual_freeform".equals(bookingAddressMode)) {
            return fieldValue(addressInput);
        }

        List<String> parts = new ArrayList<>();
        addAddressPart(parts, fieldValue(houseFlatInput));
        addAddressPart(parts, fieldValue(buildingInput));
        addAddressPart(parts, prefixedAddressPart("Floor ", fieldValue(floorInput)));
        addAddressPart(parts, prefixedAddressPart("Room ", fieldValue(roomInput)));
        addAddressPart(parts, fieldValue(addressInput));
        addAddressPart(parts, prefixedAddressPart("Near ", fieldValue(landmarkInput)));
        if ("manual".equals(bookingAddressMode)) {
            addAddressPart(parts, fieldValue(cityInput));
            addAddressPart(parts, fieldValue(stateInput));
            addAddressPart(parts, fieldValue(pinCodeInput));
        }
        return TextUtils.join(", ", parts);
    }

    private String fieldValue(EditText field) {
        return field == null ? "" : field.getText().toString().trim();
    }

    private String prefixedAddressPart(String prefix, String value) {
        return TextUtils.isEmpty(value) ? "" : prefix + value;
    }

    private void addAddressPart(List<String> parts, String value) {
        if (!TextUtils.isEmpty(value) && !parts.contains(value)) {
            parts.add(value);
        }
    }

