    private View bookingIconBadge(int iconRes, int sizeDp, float imageScale) {
        FrameLayout badge = new FrameLayout(this);
        badge.setClipChildren(true);
        badge.setClipToPadding(true);
        badge.setBackground(stroke(Color.WHITE, Color.rgb(244, 224, 226), dp(11)));

        ImageView image = new ImageView(this);
        Bitmap compactBitmap = compactIconBitmap(iconRes);
        if (compactBitmap != null) {
            image.setImageBitmap(compactBitmap);
        } else {
            image.setImageResource(iconRes);
        }
        image.setScaleType(ImageView.ScaleType.FIT_CENTER);
        image.setScaleX(imageScale);
        image.setScaleY(imageScale);
        image.setPadding(dp(2), dp(2), dp(2), dp(2));
        badge.addView(image, new FrameLayout.LayoutParams(-1, -1, Gravity.CENTER));
        return badge;
    }

    private Bitmap compactIconBitmap(int resId) {
        Bitmap cached = compactIconCache.get(resId);
        if (cached != null && !cached.isRecycled()) {
            return cached;
        }
        BitmapFactory.Options bounds = new BitmapFactory.Options();
        bounds.inJustDecodeBounds = true;
        BitmapFactory.decodeResource(getResources(), resId, bounds);
        if (bounds.outWidth <= 0 || bounds.outHeight <= 0) {
            return null;
        }
        int sample = 1;
        int targetPixels = isLowRamDevice() ? 128 : 256;
        while (bounds.outWidth / (sample * 2) >= targetPixels
                && bounds.outHeight / (sample * 2) >= targetPixels) {
            sample *= 2;
        }
        BitmapFactory.Options options = new BitmapFactory.Options();
        options.inSampleSize = sample;
        options.inPreferredConfig = Bitmap.Config.ARGB_8888;
        Bitmap bitmap = BitmapFactory.decodeResource(getResources(), resId, options);
        if (bitmap != null) {
            compactIconCache.put(resId, bitmap);
        }
        return bitmap;
    }

