    private LinearLayout serviceTierOption(String title, String subtitle, String icon, boolean selected) {
        LinearLayout option = vertical();
        option.setGravity(Gravity.CENTER);
        option.setPadding(dp(10), dp(10), dp(10), dp(10));

        LinearLayout top = horizontal();
        top.setGravity(Gravity.CENTER_VERTICAL);
        TextView radio = text("", 22, ORANGE, true);
        radio.setGravity(Gravity.CENTER);
        top.addView(radio, new LinearLayout.LayoutParams(dp(28), dp(32)));

        TextView iconView = text(icon, 22, ORANGE, true);
        iconView.setGravity(Gravity.CENTER);
        top.addView(iconView, margin(48, 48, 0, 0, 0, 0));
        option.addView(top, margin(-1, -2, 0, 0, 0, 8));

        LinearLayout copy = vertical();
        copy.setGravity(Gravity.CENTER);
        TextView titleView = text(title, 15, BLACK, true);
        titleView.setGravity(Gravity.CENTER);
        copy.addView(titleView, new LinearLayout.LayoutParams(-1, -2));
        TextView subtitleView = text(subtitle, 12, MUTED, false);
        subtitleView.setGravity(Gravity.CENTER);
        copy.addView(subtitleView, margin(-1, -2, 0, 3, 0, 0));
        option.addView(copy, new LinearLayout.LayoutParams(-1, -2));

        if ("Normal".equals(title)) {
            normalTierRadio = radio;
            normalTierIcon = iconView;
            normalTierCard = option;
        } else {
            premierTierRadio = radio;
            premierTierIcon = iconView;
            premierTierCard = option;
        }
        styleServiceTierOption(option, radio, iconView, selected);
        addPressAnimation(option);
        return option;
    }

    private void refreshServiceTierCards() {
        styleServiceTierOption(normalTierCard, normalTierRadio, normalTierIcon, "Normal".equals(selectedServiceTier));
        styleServiceTierOption(premierTierCard, premierTierRadio, premierTierIcon, isPremierVisitSelected());
    }

    private void styleServiceTierOption(LinearLayout option, TextView radio, TextView icon, boolean selected) {
        if (option == null || radio == null || icon == null) {
            return;
        }
        boolean premier = option == premierTierCard || icon == premierTierIcon;
        int accent = premier ? PREMIER : ORANGE;
        int soft = premier ? PREMIER_SOFT : ORANGE_SOFT;
        option.setBackground(serviceTierSurfaceDrawable(selected, accent, soft));
        option.setElevation(selected ? dp(10) : dp(4));
        option.setTranslationZ(selected ? dp(5) : dp(1));
        option.setScaleX(selected ? 1.02f : 1f);
        option.setScaleY(selected ? 1.03f : 1f);
        radio.setText(selected ? "\u25C9" : "\u25CB");
        radio.setTextColor(selected ? accent : Color.rgb(175, 175, 175));
        icon.setTextColor(premier ? PREMIER : (selected ? ORANGE : Color.rgb(105, 105, 105)));
        icon.setBackground(round(selected || premier ? soft : Color.rgb(244, 244, 244), dp(28)));
    }

