    private void showDatePicker() {
        Calendar calendar = bookingCalendarNow();
        DatePickerDialog dialog = new DatePickerDialog(this, (view, year, month, dayOfMonth) -> {
            Calendar chosen = bookingCalendarNow();
            chosen.set(year, month, dayOfMonth);
            selectedDate = String.format(Locale.US, "%02d %s %d", dayOfMonth, monthName(month), year);
            clearSelectedTimeIfUnavailable(chosen);
            if (dateValueView != null) {
                if ("date_selector".equals(dateValueView.getTag())) {
                    dateValueView.setText(selectedDate);
                } else {
                    dateValueView.setText(dateChipLabel(chosen));
                    dateValueView.setTag(selectedDate);
                }
            }
            refreshBookingStepper(false);
        }, calendar.get(Calendar.YEAR), calendar.get(Calendar.MONTH), calendar.get(Calendar.DAY_OF_MONTH));
        dialog.getDatePicker().setMinDate(System.currentTimeMillis() - 1000);
        dialog.show();
    }

    private void showTimeSlotPicker() {
        ensureBookingDateSelectedForTimePicker();
        Calendar bookingDate = selectedBookingDateCalendar();
        String[] slots = {
                "08:00 AM - 10:00 AM",
                "10:00 AM - 12:00 PM",
                "12:00 PM - 02:00 PM",
                "02:00 PM - 04:00 PM",
                "04:00 PM - 06:00 PM",
                "06:00 PM - 08:00 PM"
        };
        AlertDialog dialog = new AlertDialog.Builder(this).create();
        LinearLayout sheet = vertical();
        sheet.setPadding(dp(18), dp(10), dp(18), dp(18));
        sheet.setBackground(timeSlotSheetDrawable());

        View handle = new View(this);
        handle.setBackground(round(Color.rgb(198, 198, 198), dp(2)));
        LinearLayout.LayoutParams handleParams = new LinearLayout.LayoutParams(dp(62), dp(4));
        handleParams.gravity = Gravity.CENTER_HORIZONTAL;
        handleParams.setMargins(0, 0, 0, dp(16));
        sheet.addView(handle, handleParams);

        LinearLayout heading = horizontal();
        heading.setGravity(Gravity.CENTER_VERTICAL);
        heading.addView(text("Select Time Slot", 24, BLACK, true), new LinearLayout.LayoutParams(0, -2, 1));
        TextView close = text("\u00D7", 24, BLACK, true);
        close.setGravity(Gravity.CENTER);
        close.setBackground(round(Color.rgb(242, 242, 242), dp(20)));
        close.setOnClickListener(view -> dialog.dismiss());
        addPressAnimation(close);
        heading.addView(close, new LinearLayout.LayoutParams(dp(42), dp(42)));
        sheet.addView(heading);

        LinearLayout dateRow = horizontal();
        dateRow.setGravity(Gravity.CENTER_VERTICAL);
        dateRow.setPadding(0, dp(18), 0, dp(18));
        TextView calendarIcon = text("\u25A6", 22, Color.rgb(210, 16, 42), true);
        calendarIcon.setGravity(Gravity.CENTER);
        calendarIcon.setBackground(round(Color.rgb(255, 235, 239), dp(12)));
        dateRow.addView(calendarIcon, new LinearLayout.LayoutParams(dp(54), dp(54)));
        TextView dateText = text(fullDateLabel(bookingDate), 18, BLACK, false);
        dateText.setPadding(dp(18), 0, 0, 0);
        dateRow.addView(dateText, new LinearLayout.LayoutParams(0, -2, 1));
        TextView change = text("\u25A6  Change Date", 13, Color.rgb(210, 16, 42), true);
        change.setGravity(Gravity.CENTER);
        change.setBackground(stroke(Color.WHITE, Color.rgb(244, 190, 198), dp(10)));
        change.setOnClickListener(view -> {
            dialog.dismiss();
            showDatePicker();
        });
        addPressAnimation(change);
        dateRow.addView(change, new LinearLayout.LayoutParams(dp(142), dp(48)));
        sheet.addView(dateRow);
        sheet.addView(insetDivider(0));

        List<LinearLayout> rowViews = new ArrayList<>();
        List<TextView> radioViews = new ArrayList<>();
        List<TextView> badgeViews = new ArrayList<>();
        List<Boolean> enabledStates = new ArrayList<>();
        List<String> statusLabels = new ArrayList<>();
        int recommendedIndex = recommendedSlotIndex(bookingDate, slots);
        final int[] selectedIndex = {-1};
        for (int index = 0; index < slots.length; index++) {
            String slot = slots[index];
            boolean available = isSlotAvailableForDate(bookingDate, slot);
            String status = timeSlotStatusLabel(bookingDate, slot, index == recommendedIndex, available);
            boolean initiallySelected = slot.equals(selectedTime) && available;
            if (initiallySelected) {
                selectedIndex[0] = index;
            }

            LinearLayout row = horizontal();
            row.setGravity(Gravity.CENTER_VERTICAL);
            row.setPadding(dp(14), 0, dp(14), 0);
            TextView radio = text(initiallySelected ? "\u25C9" : "\u25CB", 25, initiallySelected ? Color.rgb(210, 16, 42) : Color.rgb(185, 185, 185), true);
            radio.setGravity(Gravity.CENTER);
            row.addView(radio, new LinearLayout.LayoutParams(dp(42), -1));
            TextView slotText = text(slot.replace(" - ", " \u2013 "), 18, available ? BLACK : Color.rgb(160, 160, 160), false);
            slotText.setPadding(dp(16), 0, 0, 0);
            row.addView(slotText, new LinearLayout.LayoutParams(0, -2, 1));
            TextView badge = text(status, 13, GREEN, false);
            badge.setGravity(Gravity.CENTER);
            badge.setPadding(dp(11), 0, dp(11), 0);
            row.addView(badge, new LinearLayout.LayoutParams(-2, dp(32)));

            rowViews.add(row);
            radioViews.add(radio);
            badgeViews.add(badge);
            enabledStates.add(available);
            statusLabels.add(status);
            final int rowIndex = index;
            if (available) {
                row.setOnClickListener(view -> {
                    selectedIndex[0] = rowIndex;
                    for (int item = 0; item < rowViews.size(); item++) {
                        styleTimeSlotSheetRow(rowViews.get(item), radioViews.get(item), badgeViews.get(item), item == selectedIndex[0], enabledStates.get(item), statusLabels.get(item));
                    }
                });
                addPressAnimation(row);
            }
            styleTimeSlotSheetRow(row, radio, badge, initiallySelected, available, status);
            sheet.addView(row, margin(-1, 62, 0, index == 0 ? 14 : 0, 0, 10));
        }

        TextView confirm = commercialPrimaryButton("Confirm Time Slot", view -> {
            if (selectedIndex[0] < 0) {
                Toast.makeText(this, "Please select an available time slot", Toast.LENGTH_SHORT).show();
                return;
            }
            selectedTime = slots[selectedIndex[0]];
            if (timeValueView != null) {
                timeValueView.setText(selectedTime);
            }
            refreshBookingStepper(false);
            dialog.dismiss();
        });
        sheet.addView(confirm, margin(-1, 58, 0, 12, 0, 12));
        TextView note = text("\u25C7  We value your time. Our team will be on time.", 14, MUTED, false);
        note.setGravity(Gravity.CENTER);
        sheet.addView(note);

        dialog.setView(sheet);
        dialog.setOnShowListener(d -> {
            if (dialog.getWindow() != null) {
                dialog.getWindow().setBackgroundDrawable(round(Color.TRANSPARENT, dp(24)));
                dialog.getWindow().setDimAmount(0.42f);
                dialog.getWindow().setGravity(Gravity.BOTTOM);
                dialog.getWindow().setLayout(WindowManager.LayoutParams.MATCH_PARENT, WindowManager.LayoutParams.WRAP_CONTENT);
            }
        });
        dialog.show();
    }

    private void ensureBookingDateSelectedForTimePicker() {
        if (!TextUtils.isEmpty(selectedDate)) {
            return;
        }
        Calendar today = bookingCalendarNow();
        selectedDate = dateLabel(today);
        if (dateValueView != null) {
            dateValueView.setText(selectedDate);
            if ("date_selector".equals(dateValueView.getTag())) {
                dateValueView.setTag("date_selector");
            } else {
                dateValueView.setTag(selectedDate);
            }
        }
    }

    private Calendar selectedBookingDateCalendar() {
        Calendar fallback = bookingCalendarNow();
        if (TextUtils.isEmpty(selectedDate)) {
            return fallback;
        }
        try {
            java.text.SimpleDateFormat format = new java.text.SimpleDateFormat("dd MMM yyyy", Locale.US);
            format.setTimeZone(bookingTimeZone());
            Calendar parsed = bookingCalendarNow();
            parsed.setTime(format.parse(selectedDate));
            return parsed;
        } catch (Exception ignored) {
            return fallback;
        }
    }

    private String fullDateLabel(Calendar calendar) {
        java.text.SimpleDateFormat format = new java.text.SimpleDateFormat("EEEE, dd MMMM yyyy", Locale.US);
        format.setTimeZone(bookingTimeZone());
        return format.format(calendar.getTime());
    }

    private java.util.TimeZone bookingTimeZone() {
        return java.util.TimeZone.getTimeZone("Asia/Kolkata");
    }

    private Calendar bookingCalendarNow() {
        return Calendar.getInstance(bookingTimeZone());
    }

    private void clearSelectedTimeIfUnavailable(Calendar date) {
        if (TextUtils.isEmpty(selectedTime) || isSlotAvailableForDate(date, selectedTime)) {
            return;
        }
        selectedTime = "";
        if (timeValueView != null) {
            timeValueView.setText("Choose time");
        }
    }

    private int recommendedSlotIndex(Calendar date, String[] slots) {
        for (int index = 0; index < slots.length; index++) {
            if (isSlotAvailableForDate(date, slots[index]) && !"Limited".equals(timeSlotStatusLabel(date, slots[index], false, true))) {
                return index;
            }
        }
        for (int index = 0; index < slots.length; index++) {
            if (isSlotAvailableForDate(date, slots[index])) {
                return index;
            }
        }
        return -1;
    }

    private boolean isSlotAvailableForDate(Calendar date, String slot) {
        if (isDateBeforeToday(date)) {
            return false;
        }
        if (!isSameDay(date, bookingCalendarNow())) {
            return true;
        }
        int[] bounds = slotBoundsMinutes(slot);
        int now = currentMinutesOfDay();
        return bounds[1] > now;
    }

    private String timeSlotStatusLabel(Calendar date, String slot, boolean recommended, boolean available) {
        if (!available) {
            return "Unavailable";
        }
        if (isSameDay(date, bookingCalendarNow())) {
            int[] bounds = slotBoundsMinutes(slot);
            int now = currentMinutesOfDay();
            if (bounds[0] <= now && now < bounds[1]) {
                return "Limited";
            }
        }
        return recommended ? "\u2605  Recommended" : "Available";
    }

    private int[] slotBoundsMinutes(String slot) {
        try {
            String[] parts = slot.split(" - ");
            return new int[]{parseTimeMinutes(parts[0].trim()), parseTimeMinutes(parts[1].trim())};
        } catch (Exception ignored) {
            return new int[]{0, 0};
        }
    }

    private int parseTimeMinutes(String value) throws Exception {
        java.text.SimpleDateFormat format = new java.text.SimpleDateFormat("hh:mm a", Locale.US);
        format.setTimeZone(bookingTimeZone());
        Calendar calendar = bookingCalendarNow();
        calendar.setTime(format.parse(value));
        return calendar.get(Calendar.HOUR_OF_DAY) * 60 + calendar.get(Calendar.MINUTE);
    }

    private int currentMinutesOfDay() {
        Calendar now = bookingCalendarNow();
        return now.get(Calendar.HOUR_OF_DAY) * 60 + now.get(Calendar.MINUTE);
    }

    private boolean isSameDay(Calendar first, Calendar second) {
        return first.get(Calendar.YEAR) == second.get(Calendar.YEAR)
                && first.get(Calendar.DAY_OF_YEAR) == second.get(Calendar.DAY_OF_YEAR);
    }

    private boolean isDateBeforeToday(Calendar date) {
        Calendar today = bookingCalendarNow();
        Calendar selected = (Calendar) date.clone();
        selected.set(Calendar.HOUR_OF_DAY, 0);
        selected.set(Calendar.MINUTE, 0);
        selected.set(Calendar.SECOND, 0);
        selected.set(Calendar.MILLISECOND, 0);
        today.set(Calendar.HOUR_OF_DAY, 0);
        today.set(Calendar.MINUTE, 0);
        today.set(Calendar.SECOND, 0);
        today.set(Calendar.MILLISECOND, 0);
        return selected.before(today);
    }

    private void styleTimeSlotSheetRow(LinearLayout row, TextView radio, TextView badge, boolean selected, boolean enabled, String status) {
        int border = selected ? Color.rgb(244, 190, 198) : Color.rgb(225, 225, 225);
        int fill = selected ? Color.rgb(255, 241, 243) : Color.WHITE;
        if (!enabled) {
            fill = Color.rgb(248, 248, 248);
            border = Color.rgb(226, 226, 226);
        }
        row.setEnabled(enabled);
        row.setAlpha(enabled ? 1f : 0.58f);
        row.setBackground(stroke(fill, border, dp(11)));
        row.setElevation(selected ? dp(3) : 0);
        radio.setText(selected ? "\u25C9" : "\u25CB");
        radio.setTextColor(selected ? Color.rgb(210, 16, 42) : Color.rgb(185, 185, 185));

        if (status.contains("Recommended")) {
            badge.setText(status);
            badge.setTextColor(Color.rgb(210, 16, 42));
            badge.setBackground(round(Color.rgb(255, 226, 230), dp(9)));
        } else if ("Limited".equals(status)) {
            badge.setText(status);
            badge.setTextColor(Color.rgb(241, 112, 24));
            badge.setBackground(round(Color.rgb(255, 239, 226), dp(9)));
        } else if ("Unavailable".equals(status)) {
            badge.setText(status);
            badge.setTextColor(Color.rgb(130, 130, 130));
            badge.setBackground(round(Color.rgb(238, 238, 238), dp(9)));
        } else {
            badge.setText(status);
            badge.setTextColor(Color.rgb(21, 135, 69));
            badge.setBackground(round(Color.rgb(231, 248, 237), dp(9)));
        }
    }

    private GradientDrawable timeSlotSheetDrawable() {
        GradientDrawable drawable = new GradientDrawable();
        drawable.setColor(Color.WHITE);
        float radius = dp(24);
        drawable.setCornerRadii(new float[]{radius, radius, radius, radius, 0, 0, 0, 0});
        return drawable;
    }

    private String defaultDateLabel() {
        Calendar calendar = Calendar.getInstance();
        calendar.add(Calendar.DAY_OF_MONTH, 1);
        return String.format(Locale.US, "%02d %s %d",
                calendar.get(Calendar.DAY_OF_MONTH),
                monthName(calendar.get(Calendar.MONTH)),
                calendar.get(Calendar.YEAR));
    }

    private String monthName(int month) {
        String[] months = {"Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"};
        return months[Math.max(0, Math.min(month, months.length - 1))];
    }

    private String problemHint(Service service) {
        if ("ac".equals(service.getId())) {
            return "Example: AC cooling kam hai, water leak ho raha hai...";
        }
        if ("electrician".equals(service.getId())) {
            return "Example: switch spark kar raha hai, fan slow chal raha hai...";
        }
        if ("plumbing".equals(service.getId())) {
            return "Example: bathroom tap leak, sink block, flush issue...";
        }
        return "Example: describe the problem, room or location, and urgency...";
    }

