    private void showEditProfileDialog() {
        AlertDialog dialog = new AlertDialog.Builder(this).create();

        LinearLayout sheet = vertical();
        sheet.setPadding(dp(20), dp(20), dp(20), dp(18));
        sheet.setBackground(bookingOuterDrawable());

        LinearLayout header = horizontal();
        header.setGravity(Gravity.CENTER_VERTICAL);
        LinearLayout copy = vertical();
        copy.addView(text("Edit Profile", 20, BLACK, true));
        copy.addView(text("Update your name and mobile number.", 12, MUTED, false), margin(-1, -2, 0, 4, 0, 0));
        header.addView(copy, new LinearLayout.LayoutParams(0, -2, 1));
        TextView close = text("\u00D7", 24, Color.rgb(150, 150, 150), true);
        close.setGravity(Gravity.CENTER);
        close.setOnClickListener(view -> dialog.dismiss());
        addPressAnimation(close);
        header.addView(close, new LinearLayout.LayoutParams(dp(38), dp(38)));
        sheet.addView(header);

        EditText nameInput = new EditText(this);
        nameInput.setText(customerName());
        nameInput.setSingleLine(true);
        nameInput.setTextSize(14);
        nameInput.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_PERSON_NAME);
        nameInput.setHint("Full name");
        nameInput.setPadding(dp(14), 0, dp(14), 0);
        nameInput.setBackground(stroke(Color.WHITE, Color.rgb(232, 203, 202), dp(12)));
        sheet.addView(nameInput, margin(-1, 48, 0, 18, 0, 10));

        EditText phoneInput = new EditText(this);
        String phone = customerPhone();
        phoneInput.setText("Not shared".equals(phone) ? "" : phone);
        phoneInput.setSingleLine(true);
        phoneInput.setTextSize(14);
        phoneInput.setInputType(InputType.TYPE_CLASS_PHONE);
        phoneInput.setFilters(new InputFilter[]{new InputFilter.LengthFilter(16)});
        phoneInput.setHint("Mobile number");
        phoneInput.setPadding(dp(14), 0, dp(14), 0);
        phoneInput.setBackground(stroke(Color.WHITE, Color.rgb(232, 203, 202), dp(12)));
        sheet.addView(phoneInput, margin(-1, 48, 0, 0, 0, 16));

        TextView save = text("Save Changes", 14, Color.WHITE, true);
        save.setGravity(Gravity.CENTER);
        save.setBackground(bookGlowButtonDrawable());
        save.setOnClickListener(view -> {
            String name = nameInput.getText().toString().trim();
            String rawPhone = phoneInput.getText().toString().trim();
            String cleanPhone = normalizeCustomerPhoneInput(rawPhone);
            if (TextUtils.isEmpty(name)) {
                Toast.makeText(this, "Name required", Toast.LENGTH_SHORT).show();
                return;
            }
            if (!isValidCustomerMobile(cleanPhone)) {
                Toast.makeText(this, "Please enter a valid 10-digit mobile number.", Toast.LENGTH_SHORT).show();
                return;
            }
            putSecureString(KEY_CUSTOMER_NAME, name);
            putSecureString(KEY_CUSTOMER_PHONE, cleanPhone);
            if (backendClient != null) {
                backendClient.connectFcmTokenToProfile(name, TextUtils.isEmpty(cleanPhone) ? "" : cleanPhone, customerEmail(), "", serviceLat, serviceLng);
            }
            Toast.makeText(this, "Profile updated", Toast.LENGTH_SHORT).show();
            dialog.dismiss();
            showProfile();
        });
        addPressAnimation(save);
        sheet.addView(save, new LinearLayout.LayoutParams(-1, dp(48)));

        dialog.setView(sheet);
        dialog.setOnShowListener(d -> {
            if (dialog.getWindow() != null) {
                dialog.getWindow().setBackgroundDrawable(round(Color.TRANSPARENT, dp(22)));
            }
        });
        dialog.show();
    }

