    private View referenceTinyLock() {
        return new View(this) {
            final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);
            @Override protected void onDraw(Canvas canvas) {
                float w=getWidth(), h=getHeight();
                paint.setColor(MUTED); paint.setStyle(Paint.Style.STROKE);
                paint.setStrokeWidth(Math.max(1.2f,w*.10f)); paint.setStrokeCap(Paint.Cap.ROUND);
                canvas.drawRoundRect(w*.22f,h*.43f,w*.78f,h*.88f,w*.08f,w*.08f,paint);
                canvas.drawArc(w*.32f,h*.12f,w*.68f,h*.58f,180,-180,false,paint);
            }
        };
    }

