    private View referenceLineIcon(String kind) {
        return new View(this) {
            final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);
            final Path path = new Path();
            @Override protected void onDraw(Canvas canvas) {
                super.onDraw(canvas);
                float w = getWidth(), h = getHeight(), cx = w / 2f, cy = h / 2f;
                paint.setStyle(Paint.Style.FILL);
                paint.setColor(Color.rgb(255, 242, 245));
                canvas.drawRoundRect(2, 2, w - 2, h - 2, w * .28f, w * .28f, paint);
                paint.setStyle(Paint.Style.STROKE);
                paint.setStrokeWidth(Math.max(2f, w * .035f));
                paint.setStrokeCap(Paint.Cap.ROUND);
                paint.setStrokeJoin(Paint.Join.ROUND);
                paint.setColor(Color.rgb(156, 37, 59));
                float l=w*.24f, r=w*.76f, t=h*.24f, b=h*.76f;
                if ("book".equals(kind)) {
                    canvas.drawRect(l, t, cx-.03f*w, b, paint); canvas.drawRect(cx+.03f*w, t, r, b, paint);
                    canvas.drawLine(cx, t+.05f*h, cx, b, paint); canvas.drawLine(l+.06f*w,t+.12f*h,cx-.08f*w,t+.12f*h,paint);
                } else if ("rocket".equals(kind)) {
                    path.reset(); path.moveTo(cx,t); path.quadTo(r,t+.08f*h,r-.05f*w,cy); path.lineTo(cx,cy+.12f*h); path.lineTo(l+.05f*w,cy); path.quadTo(l,t+.08f*h,cx,t); canvas.drawPath(path,paint);
                    canvas.drawCircle(cx,cy-.1f*h,.055f*w,paint); canvas.drawLine(cx,cy+.13f*h,cx-.12f*w,b,paint); canvas.drawLine(cx,cy+.13f*h,cx+.12f*w,b,paint);
                } else if ("lock".equals(kind)) {
                    path.reset(); path.moveTo(cx,t); path.lineTo(r-.04f*w,t+.1f*h); path.lineTo(r-.06f*w,cy+.15f*h); path.quadTo(cx,b,cx, b); path.quadTo(l+.06f*w,cy+.15f*h,l+.04f*w,t+.1f*h); path.close(); canvas.drawPath(path,paint);
                    canvas.drawRect(cx-.09f*w,cy-.03f*h,cx+.09f*w,cy+.15f*h,paint); canvas.drawArc(cx-.07f*w,cy-.12f*h,cx+.07f*w,cy+.04f*h,180,180,false,paint);
                } else if ("external".equals(kind)) {
                    canvas.drawRoundRect(l,cy-.08f*h,r-.12f*w,b,.05f*w,.05f*w,paint); canvas.drawLine(cx,cy,r,t,paint); canvas.drawLine(r,t,r,cy-.13f*h,paint); canvas.drawLine(r,t,cx+.13f*w,t,paint);
                } else if ("refund".equals(kind)) {
                    canvas.drawArc(l,t,r,b,-60,285,false,paint); canvas.drawLine(l+.02f*w,cy-.18f*h,l,cy,paint); canvas.drawLine(l,cy,l+.16f*w,cy-.02f*h,paint);
                    paint.setStyle(Paint.Style.FILL); paint.setTextSize(w*.34f); paint.setTextAlign(Paint.Align.CENTER); canvas.drawText("₹",cx,cy+.12f*h,paint);
                } else if ("support".equals(kind)) {
                    canvas.drawArc(l,t,r,cy+.13f*h,190,160,false,paint); canvas.drawLine(l,cy,l,cy+.17f*h,paint); canvas.drawLine(r,cy,r,cy+.17f*h,paint); canvas.drawCircle(l,cy+.12f*h,.045f*w,paint); canvas.drawCircle(r,cy+.12f*h,.045f*w,paint); canvas.drawLine(r,cy+.17f*h,cx+.1f*w,b,paint);
                } else if ("trash".equals(kind)) {
                    canvas.drawRoundRect(l+.08f*w,t+.13f*h,r-.08f*w,b,.04f*w,.04f*w,paint); canvas.drawLine(l,t+.1f*h,r,t+.1f*h,paint); canvas.drawLine(cx-.09f*w,t,cx+.09f*w,t,paint); canvas.drawLine(cx-.08f*w,cy-.02f*h,cx-.08f*w,b-.08f*h,paint); canvas.drawLine(cx+.08f*w,cy-.02f*h,cx+.08f*w,b-.08f*h,paint);
                } else if ("home".equals(kind)) {
                    path.reset(); path.moveTo(l,cy); path.lineTo(cx,t); path.lineTo(r,cy); path.moveTo(l+.08f*w,cy-.03f*h); path.lineTo(l+.08f*w,b); path.lineTo(r-.08f*w,b); path.lineTo(r-.08f*w,cy-.03f*h); canvas.drawPath(path,paint); canvas.drawRect(cx-.07f*w,cy+.09f*h,cx+.07f*w,b,paint);
                } else if ("work".equals(kind)) {
                    canvas.drawRect(l+.05f*w,t,r-.05f*w,b,paint); canvas.drawLine(l,t+.22f*h,r,t+.22f*h,paint); for(int i=0;i<3;i++){ canvas.drawCircle(cx-.13f*w+i*.13f*w,cy,.018f*w,paint); canvas.drawCircle(cx-.13f*w+i*.13f*w,cy+.14f*h,.018f*w,paint); }
                } else {
                    path.reset(); path.moveTo(cx,t); path.lineTo(r-.04f*w,t+.1f*h); path.lineTo(r-.06f*w,cy+.15f*h); path.quadTo(cx,b,cx,b); path.quadTo(l+.06f*w,cy+.15f*h,l+.04f*w,t+.1f*h); path.close(); canvas.drawPath(path,paint); canvas.drawLine(cx-.1f*w,cy,cx-.02f*w,cy+.08f*h,paint); canvas.drawLine(cx-.02f*w,cy+.08f*h,cx+.14f*w,cy-.1f*h,paint);
                }
                paint.setStyle(Paint.Style.STROKE);
                paint.setStrokeWidth(Math.max(1.4f, w * .025f));
                float star = w * .035f;
                canvas.drawLine(w*.18f-star, h*.18f, w*.18f+star, h*.18f, paint);
                canvas.drawLine(w*.18f, h*.18f-star, w*.18f, h*.18f+star, paint);
                canvas.drawLine(w*.79f-star, h*.20f, w*.79f+star, h*.20f, paint);
                canvas.drawLine(w*.79f, h*.20f-star, w*.79f, h*.20f+star, paint);
            }
        };
    }

    private View referenceNavigationIcon(boolean close) {
        return new View(this) {
            final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);
            @Override protected void onDraw(Canvas canvas) {
                super.onDraw(canvas);
                float w = getWidth(), h = getHeight();
                paint.setStyle(Paint.Style.FILL);
                paint.setColor(close ? Color.rgb(255, 239, 242) : Color.WHITE);
                canvas.drawRoundRect(1, 1, w - 1, h - 1, w * .27f, w * .27f, paint);
                if (!close) {
                    paint.setStyle(Paint.Style.STROKE);
                    paint.setStrokeWidth(Math.max(dp(1), w * .025f));
                    paint.setColor(Color.rgb(244, 224, 228));
                    canvas.drawRoundRect(1, 1, w - 1, h - 1, w * .27f, w * .27f, paint);
                }
                paint.setColor(Color.rgb(151, 28, 50));
                paint.setStrokeWidth(Math.max(dp(2), w * .055f));
                paint.setStrokeCap(Paint.Cap.ROUND);
                paint.setStrokeJoin(Paint.Join.ROUND);
                paint.setStyle(Paint.Style.STROKE);
                if (close) {
                    canvas.drawLine(w*.37f, h*.37f, w*.63f, h*.63f, paint);
                    canvas.drawLine(w*.63f, h*.37f, w*.37f, h*.63f, paint);
                } else {
                    Path arrow = new Path();
                    arrow.moveTo(w*.58f, h*.30f);
                    arrow.lineTo(w*.38f, h*.50f);
                    arrow.lineTo(w*.58f, h*.70f);
                    canvas.drawPath(arrow, paint);
                }
            }
        };
    }

    private View referenceRowActionIcon(boolean external) {
        return new View(this) {
            final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);
            @Override protected void onDraw(Canvas canvas) {
                super.onDraw(canvas);
                float w=getWidth(), h=getHeight();
                paint.setColor(Color.rgb(181, 70, 89));
                paint.setStyle(Paint.Style.STROKE);
                paint.setStrokeWidth(Math.max(dp(1), w*.065f));
                paint.setStrokeCap(Paint.Cap.ROUND);
                paint.setStrokeJoin(Paint.Join.ROUND);
                Path path = new Path();
                if (external) {
                    canvas.drawRoundRect(w*.19f,h*.36f,w*.70f,h*.82f,w*.05f,w*.05f,paint);
                    path.moveTo(w*.48f,h*.50f); path.lineTo(w*.82f,h*.18f);
                    path.moveTo(w*.58f,h*.18f); path.lineTo(w*.82f,h*.18f); path.lineTo(w*.82f,h*.42f);
                } else {
                    path.moveTo(w*.38f,h*.28f); path.lineTo(w*.62f,h*.50f); path.lineTo(w*.38f,h*.72f);
                }
                canvas.drawPath(path,paint);
            }
        };
    }

    private View referenceAddressSelection(boolean selected) {
        return new View(this) {
            final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);
            @Override protected void onDraw(Canvas canvas) {
                super.onDraw(canvas);
                float w=getWidth(), h=getHeight(), cx=w/2f, cy=h/2f, radius=w*.31f;
                paint.setStyle(Paint.Style.STROKE);
                paint.setStrokeWidth(Math.max(dp(1), w*.045f));
                paint.setColor(Color.rgb(190, 50, 78));
                canvas.drawCircle(cx,cy,radius,paint);
                if (selected) {
                    paint.setStyle(Paint.Style.FILL);
                    paint.setColor(Color.rgb(205, 70, 96));
                    canvas.drawCircle(cx,cy,radius*.72f,paint);
                    paint.setStyle(Paint.Style.STROKE);
                    paint.setStrokeWidth(Math.max(dp(2),w*.055f));
                    paint.setStrokeCap(Paint.Cap.ROUND);
                    paint.setColor(Color.WHITE);
                    Path check=new Path(); check.moveTo(cx-radius*.34f,cy); check.lineTo(cx-radius*.06f,cy+radius*.27f); check.lineTo(cx+radius*.40f,cy-radius*.28f); canvas.drawPath(check,paint);
                }
                paint.setColor(Color.rgb(151, 28, 50));
                paint.setStrokeWidth(Math.max(1.2f,w*.025f));
                float s=w*.035f;
                canvas.drawLine(w*.18f-s,h*.22f,w*.18f+s,h*.22f,paint); canvas.drawLine(w*.18f,h*.22f-s,w*.18f,h*.22f+s,paint);
                canvas.drawLine(w*.82f-s,h*.18f,w*.82f+s,h*.18f,paint); canvas.drawLine(w*.82f,h*.18f-s,w*.82f,h*.18f+s,paint);
            }
        };
    }

    private View customerLegalActionRow(String icon, String title, String body, int accent, int bg, View.OnClickListener listener) {
        LinearLayout row = horizontal();
        row.setGravity(Gravity.CENTER_VERTICAL);
        row.setPadding(0, dp(12), 0, dp(12));
        row.setOnClickListener(listener);
        addPressAnimation(row);

        TextView mark = text(icon, 16, accent, true);
        mark.setGravity(Gravity.CENTER);
        mark.setBackground(round(bg, dp(16)));
        row.addView(mark, new LinearLayout.LayoutParams(dp(34), dp(34)));

        LinearLayout copy = vertical();
        copy.setPadding(dp(12), 0, 0, 0);
        copy.addView(text(title, 15, BLACK, true));
        TextView bodyView = text(body, 12, MUTED, false);
        bodyView.setMaxLines(2);
        copy.addView(bodyView, margin(-1, -2, 0, 0, 0, 0));
        row.addView(copy, new LinearLayout.LayoutParams(0, -2, 1));
        row.addView(text("\u203A", 21, MUTED, true));
        return row;
    }

    private void openLegalWebPage(String url) {
        try {
            Intent intent = new Intent(Intent.ACTION_VIEW, Uri.parse(url));
            intent.addCategory(Intent.CATEGORY_BROWSABLE);
            startActivity(intent);
        } catch (Exception error) {
            Toast.makeText(this, "Could not open the page. Please try again.", Toast.LENGTH_LONG).show();
        }
    }

    private View customerLegalAccordionCard(String icon, String title, String subtitle, int accent, int bg, String bodyText, boolean expandedByDefault) {
        LinearLayout card = vertical();
        card.setPadding(dp(14), dp(13), dp(14), dp(13));
        card.setBackground(stroke(Color.WHITE, Color.rgb(235, 225, 225), dp(18)));
        card.setElevation(dp(2));

        LinearLayout header = horizontal();
        header.setGravity(Gravity.CENTER_VERTICAL);

        TextView mark = text(icon, 14, accent, true);
        mark.setGravity(Gravity.CENTER);
        mark.setBackground(round(bg, dp(16)));
        header.addView(mark, new LinearLayout.LayoutParams(dp(34), dp(34)));

        LinearLayout copy = vertical();
        copy.setPadding(dp(12), 0, dp(10), 0);
        copy.addView(text(title, 15, BLACK, true));
        TextView sub = text(subtitle, 11, MUTED, false);
        sub.setMaxLines(2);
        sub.setEllipsize(TextUtils.TruncateAt.END);
        copy.addView(sub, margin(-1, -2, 0, 1, 0, 0));
        header.addView(copy, new LinearLayout.LayoutParams(0, -2, 1));

        TextView arrow = text(expandedByDefault ? "\u2303" : "\u2304", 18, accent, true);
        arrow.setGravity(Gravity.CENTER);
        header.addView(arrow, new LinearLayout.LayoutParams(dp(28), dp(34)));
        card.addView(header);

        TextView body = text(bodyText, 12, Color.rgb(64, 66, 70), false);
        body.setLineSpacing(dp(3), 1.04f);
        body.setVisibility(expandedByDefault ? View.VISIBLE : View.GONE);
        card.addView(body, margin(-1, -2, 0, 12, 0, 0));

        View.OnClickListener toggle = view -> {
            boolean expanded = body.getVisibility() == View.VISIBLE;
            body.setVisibility(expanded ? View.GONE : View.VISIBLE);
            arrow.setText(expanded ? "\u2304" : "\u2303");
        };
        header.setOnClickListener(toggle);
        card.setOnClickListener(toggle);
        addPressAnimation(card);
        return card;
    }

