    private List<String> savedServiceAddresses() {
        List<String> result = new ArrayList<>();
        String currentPhone = normalizeCustomerPhoneInput(secureString(KEY_CUSTOMER_PHONE, ""));
        String ownerPhone = normalizeCustomerPhoneInput(secureString(KEY_SAVED_ADDRESS_OWNER_PHONE, ""));
        if (!isValidCustomerMobile(currentPhone) || !currentPhone.equals(ownerPhone)) return result;
        try {
            JSONArray array = new JSONArray(secureString(KEY_SAVED_ADDRESSES, "[]"));
            for (int i = 0; i < array.length(); i++) {
                String value = array.optString(i, "").trim();
                if (!TextUtils.isEmpty(value) && !result.contains(value)) result.add(value);
            }
        } catch (Exception ignored) {
        }
        return result;
    }

    private void rememberSavedServiceAddress(String address) {
        String cleanAddress = address == null ? "" : address.trim();
        String phone = normalizeCustomerPhoneInput(secureString(KEY_CUSTOMER_PHONE, ""));
        if (cleanAddress.length() < 8 || !isValidCustomerMobile(phone)) return;
        List<String> addresses = savedServiceAddresses();
        if (!addresses.contains(cleanAddress)) addresses.add(cleanAddress);
        JSONArray array = new JSONArray();
        for (String item : addresses) array.put(item);
        putSecureString(KEY_SAVED_ADDRESSES, array.toString());
        putSecureString(KEY_SAVED_ADDRESS_OWNER_PHONE, phone);
        if (TextUtils.isEmpty(secureString(KEY_DEFAULT_SAVED_ADDRESS, ""))) {
            putSecureString(KEY_DEFAULT_SAVED_ADDRESS, cleanAddress);
        }
    }

    private void showBookingChat(Booking booking) {
        if (!requireFeature(FeatureRegistry.BOOKING_CHAT, "Booking chat")) return;
        if (booking == null) {
            Toast.makeText(this, "Booking not found", Toast.LENGTH_SHORT).show();
            showTrack();
            return;
        }
        if (!isPartnerAcceptedStatus(remoteBookingStatus) && !partnerAssigned) {
            Toast.makeText(this, "Chat will be available after a partner is assigned.", Toast.LENGTH_SHORT).show();
            return;
        }
        latestBooking = booking;
        activeBookingChatId = backendChatBookingId(booking);
        boolean laundryBooking = "laundry".equals(latestBookingService().getId());
        activeBookingChatPeer = TextUtils.isEmpty(assignedPartnerName)
                ? (laundryBooking ? "Laundry Service" : "Service Professional")
                : assignedPartnerName;
        setCurrentScreen("booking_chat");
        showAppChrome();
        setActiveNav(navBookings);
        resetScreen();
        floatingFooter.setVisibility(View.GONE);
        supportMessages = null;
        supportInput = null;
        supportFeedbackView = null;
        supportTypingView = null;
        supportStatusViews.clear();
        bookingChatRendered.clear();

        addBookingChatTopBar(laundryBooking ? "Laundry Service Chat" : "Service Chat");
        screenContent.addView(userBookingChatPeerCard(booking), margin(-1, -2, 18, 0, 18, 18));

        supportMessages = vertical();
        supportMessages.addView(supportDatePill(), margin(-1, -2, 0, 0, 0, 14));
        supportMessages.addView(userBookingChatEmptyState(), margin(-1, -2, 0, 18, 0, 18));
        screenContent.addView(supportMessages, margin(-1, -2, 18, 6, 18, 14));

        loadBookingChatMessages(activeBookingChatId);
        scheduleBookingChatPolling();

        if (supportInputDock != null) {
            supportInputDock.removeAllViews();
            supportInputDock.addView(bookingChatInputBar(), new LinearLayout.LayoutParams(-1, dp(58)));
            supportInputDock.setVisibility(View.VISIBLE);
        } else {
            screenContent.addView(bookingChatInputBar(), margin(-1, 62, 16, 0, 16, 96));
        }
        if (backendClient != null) {
            backendClient.markBookingChatSeen(activeBookingChatId);
        }
        mainScroll.post(() -> mainScroll.smoothScrollTo(0, screenContent.getBottom()));
    }

