    private void removeUserBookingChatEmptyState() {
        if (supportMessages == null) {
            return;
        }
        for (int index = supportMessages.getChildCount() - 1; index >= 0; index--) {
            View child = supportMessages.getChildAt(index);
            if ("booking_chat_empty_state".equals(child.getTag())) {
                supportMessages.removeViewAt(index);
            }
        }
    }

    private void scheduleBookingChatPolling() {
        if (bookingChatPollRunnable != null) {
            carouselHandler.removeCallbacks(bookingChatPollRunnable);
        }
        bookingChatPollRunnable = new Runnable() {
            @Override
            public void run() {
                if (!"booking_chat".equals(currentScreen) || TextUtils.isEmpty(activeBookingChatId) || backendClient == null) {
                    return;
                }
                backendClient.fetchBookingChatMessages(activeBookingChatId, new BackendClient.JsonCallback() {
                    @Override
                    public void onSuccess(JSONObject object) {
                        JSONArray messages = object.optJSONArray("messages");
                        if (messages != null && "booking_chat".equals(currentScreen)) {
                            for (int index = 0; index < messages.length(); index++) {
                                addBookingChatMessage(messages.optJSONObject(index), true);
                            }
                            backendClient.markBookingChatSeen(activeBookingChatId);
                        }
                    }

                    @Override
                    public void onError(String message) {
                    }
                });
                carouselHandler.postDelayed(this, 3000L);
            }
        };
        carouselHandler.postDelayed(bookingChatPollRunnable, 3000L);
    }

    private String backendChatBookingId(Booking booking) {
        if (booking == null) {
            return "";
        }
        if (latestBooking != null
                && booking.getId().equals(latestBooking.getId())
                && !TextUtils.isEmpty(latestBackendBookingId)) {
            return latestBackendBookingId;
        }
        return booking.getId();
    }

