    private void loadSupportLiveAppStatus() {
        if (backendClient == null) return;
        backendClient.fetchBookingLaunchStatus(new BackendClient.JsonCallback() {
            @Override public void onSuccess(JSONObject object) {
                supportBookingOpen = object.optBoolean("bookingOpen", false);
                supportLaunchDateLabel = object.optString("launchDateLabel", "").trim();
                supportLaunchStatusKnown = true;
            }
            @Override public void onError(String ignored) {
                supportLaunchStatusKnown = false;
            }
        });
    }

