    private void sendSupportMessage(String preset) {
        String message = preset == null && supportInput != null ? supportInput.getText().toString().trim() : preset;
        if (message == null || message.trim().isEmpty()) {
            Toast.makeText(this, "Please type your issue", Toast.LENGTH_SHORT).show();
            return;
        }
        if (supportInput != null) {
            supportInput.setText("");
        }
        int replyId = ++supportReplySequence;
        String ticketId = activeSupportTicketId;
        boolean actualComplaint = supportAwaitingComplaintDetails || shouldCreateSupportTicket(message);
        if (TextUtils.isEmpty(ticketId) && actualComplaint) {
            ticketId = complaintTicketId();
            activeSupportTicketId = ticketId;
        }
        final String activeTicketId = ticketId;
        String messageId = supportMessageId("CUSMSG");
        if (actualComplaint && TextUtils.isEmpty(activeSupportComplaintMessageId)) {
            activeSupportComplaintMessageId = messageId;
            supportAwaitingComplaintDetails = false;
            if (supportInput != null) supportInput.setHint("Type your issue or message...");
        }
        addSupportMessage(message, true, messageId, isNetworkOnline() ? "Sending" : "Queued");
        showSupportTypingIndicator();
        dispatchCustomerSupportMessage(supportTypeForMessage(message), message, activeTicketId, messageId, "", false);
        carouselHandler.postDelayed(() -> {
            if (replyId != supportReplySequence || !"support".equals(currentScreen)) {
                return;
            }
            hideSupportTypingIndicator();
            String reply = generateSupportReply(message, activeTicketId);
            addSupportMessage(reply, false);
            updateSupportMessageStatus(messageId, "Seen");
            if (shouldShowSupportBookingCard(message)) {
                addSupportBookingUpdateCard();
            }
            if (shouldShowSupportFeedback(message)) {
                showSupportFeedbackPopup();
            }
        }, supportReplyDelayMs(message));
    }

    private int supportReplyDelayMs(String message) {
        int length = message == null ? 0 : message.length();
        return Math.min(1800, 850 + (length * 16));
    }

    private void showSupportTypingIndicator() {
        if (supportMessages == null) {
            return;
        }
        hideSupportTypingIndicator();
        removeSupportFeedbackPopup();
        LinearLayout row = horizontal();
        row.setGravity(Gravity.LEFT | Gravity.TOP);
        row.addView(supportBotIcon(), new LinearLayout.LayoutParams(dp(30), dp(30)));

        LinearLayout bubble = horizontal();
        bubble.setGravity(Gravity.CENTER);
        bubble.setPadding(dp(12), dp(10), dp(12), dp(10));
        bubble.setBackground(stroke(Color.WHITE, Color.rgb(235, 226, 226), dp(16)));
        for (int index = 0; index < 3; index++) {
            TextView dot = text("\u25CF", 14, Color.rgb(247, 110, 130), true);
            dot.setGravity(Gravity.CENTER);
            bubble.addView(dot, margin(14, 18, index == 0 ? 0 : 3, 0, 0, 0));
            startTypingDotAnimation(dot, index * 120L);
        }
        row.addView(bubble, margin(76, -2, 8, 0, 0, 0));
        supportTypingView = row;
        supportMessages.addView(row, margin(-1, -2, 0, 0, 0, 12));
        mainScroll.post(() -> mainScroll.smoothScrollTo(0, screenContent.getBottom()));
    }

    private void startTypingDotAnimation(View dot, long delayMs) {
        ObjectAnimator bounce = ObjectAnimator.ofFloat(dot, View.TRANSLATION_Y, 0f, -dp(6), 0f);
        bounce.setDuration(620);
        bounce.setStartDelay(delayMs);
        bounce.setRepeatCount(ValueAnimator.INFINITE);
        bounce.setRepeatMode(ValueAnimator.RESTART);
        bounce.setInterpolator(new AccelerateDecelerateInterpolator());
        bounce.start();
    }

    private void hideSupportTypingIndicator() {
        if (supportMessages != null && supportTypingView != null) {
            supportMessages.removeView(supportTypingView);
        }
        supportTypingView = null;
    }

    private void addSupportMessage(String message, boolean fromUser) {
        addSupportMessage(message, fromUser, "", "");
    }

    private void addSupportMessage(String message, boolean fromUser, String messageId, String status) {
        if (supportMessages == null) {
            return;
        }
        removeSupportFeedbackPopup();
        LinearLayout row = horizontal();
        row.setGravity(fromUser ? Gravity.RIGHT : Gravity.LEFT | Gravity.TOP);
        if (!fromUser) {
            row.addView(supportBotIcon(), new LinearLayout.LayoutParams(dp(30), dp(30)));
        }
        LinearLayout stack = vertical();
        TextView bubble = text(message, 14, BLACK, false);
        bubble.setPadding(dp(13), dp(11), dp(13), dp(11));
        bubble.setMaxLines(10);
        bubble.setBackground(fromUser
                ? round(Color.rgb(255, 240, 245), dp(16))
                : stroke(Color.WHITE, Color.rgb(235, 226, 226), dp(16)));
        stack.addView(bubble, new LinearLayout.LayoutParams(dp(fromUser ? 252 : 266), -2));
        TextView time = text(supportTimeLabel(), 10, Color.rgb(145, 135, 135), false);
        time.setGravity(fromUser ? Gravity.RIGHT : Gravity.LEFT);
        if (fromUser && !TextUtils.isEmpty(status)) {
            time.setText(supportStatusText(status));
        }
        if (fromUser && !TextUtils.isEmpty(messageId)) {
            supportStatusViews.put(messageId, time);
            time.setOnClickListener(view -> retryQueuedCustomerSupportMessage(messageId));
        }
        stack.addView(time, margin(-1, -2, 0, 2, 0, 0));
        row.addView(stack);
        supportMessages.addView(row, margin(-1, -2, 0, 0, 0, 12));
        mainScroll.post(() -> mainScroll.smoothScrollTo(0, screenContent.getBottom()));
    }

    private View supportBotIcon() {
        TextView icon = text("\uD83E\uDD16", 15, Color.WHITE, true);
        icon.setGravity(Gravity.CENTER);
        icon.setIncludeFontPadding(false);
        icon.setBackground(round(GREEN, dp(15)));
        icon.setElevation(dp(2));
        return icon;
    }

    private String supportTimeLabel() {
        Calendar calendar = Calendar.getInstance();
        int hour = calendar.get(Calendar.HOUR);
        if (hour == 0) {
            hour = 12;
        }
        return String.format(Locale.US, "%d:%02d %s",
                hour,
                calendar.get(Calendar.MINUTE),
                calendar.get(Calendar.AM_PM) == Calendar.AM ? "AM" : "PM");
    }

    private String supportStatusText(String status) {
        return supportTimeLabel() + "  •  " + status;
    }

    private void updateSupportMessageStatus(String messageId, String status) {
        if (TextUtils.isEmpty(messageId)) {
            return;
        }
        TextView view = supportStatusViews.get(messageId);
        if (view != null) {
            view.setText(supportStatusText(status));
            int color = "Seen".equalsIgnoreCase(status) || "Delivered".equalsIgnoreCase(status) || "Sent".equalsIgnoreCase(status)
                    ? GREEN
                    : ("Queued".equalsIgnoreCase(status) ? ORANGE : Color.rgb(215, 51, 70));
            view.setTextColor(color);
        }
        persistCustomerSupportDeliveryStatus(messageId, status);
    }

    private void persistCustomerSupportDeliveryStatus(String messageId, String status) {
        if (TextUtils.isEmpty(messageId)
                || status == null
                || !(containsAny(status.toLowerCase(Locale.US), "sent", "delivered", "seen"))
                || firestore == null) {
            return;
        }
        Map<String, Object> update = new HashMap<>();
        update.put("deliveryStatus", status.toLowerCase(Locale.US));
        update.put("deliveryStatusAtMillis", System.currentTimeMillis());
        if (realtimeDatabase != null) {
            realtimeDatabase.getReference("customer_support_messages").child(messageId).updateChildren(new HashMap<>(update));
        }
        firestore.collection("customer_support_messages")
                .document(messageId)
                .set(update, SetOptions.merge())
                .addOnFailureListener(error -> {});
    }

    private String supportMessageId(String prefix) {
        return prefix + System.currentTimeMillis() + String.valueOf(Math.abs((int) (Math.random() * 9000)) + 1000);
    }

    private void startCustomerSupportPhotoCapture() {
        if (!"support".equals(currentScreen)) {
            showSupportChat();
            return;
        }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M
                && checkSelfPermission(Manifest.permission.CAMERA) != PackageManager.PERMISSION_GRANTED) {
            requestPermissions(new String[]{Manifest.permission.CAMERA}, SUPPORT_CAMERA_PERMISSION_REQUEST);
            return;
        }
        launchSupportCamera();
    }

    private void launchSupportCamera() {
        try {
            Intent intent = new Intent(MediaStore.ACTION_IMAGE_CAPTURE);
            startActivityForResult(intent, SUPPORT_CAMERA_REQUEST);
        } catch (Exception error) {
            Toast.makeText(this, "Unable to open the camera.", Toast.LENGTH_SHORT).show();
        }
    }

    private void handleSupportCameraResult(Intent data) {
        if (data == null || data.getExtras() == null) {
            Toast.makeText(this, "Photo capture failed", Toast.LENGTH_SHORT).show();
            return;
        }
        Object bitmap = data.getExtras().get("data");
        if (!(bitmap instanceof Bitmap)) {
            Toast.makeText(this, "Photo capture failed", Toast.LENGTH_SHORT).show();
            return;
        }
        File file = saveSupportBitmap((Bitmap) bitmap);
        if (file == null) {
            updateSupportMessageStatus("", "Failed - tap retry");
            Toast.makeText(this, "Unable to save the photo.", Toast.LENGTH_SHORT).show();
            return;
        }
        String messageId = supportMessageId("CUSPHOTO");
        String message = "Photo attachment";
        if (TextUtils.isEmpty(activeSupportTicketId)) {
            activeSupportTicketId = complaintTicketId();
        }
        addSupportMessage(message, true, messageId, isNetworkOnline() ? "Uploading" : "Queued");
        dispatchCustomerSupportMessage("attachment", message, activeSupportTicketId, messageId, file.getAbsolutePath(), false);
    }

    private File saveSupportBitmap(Bitmap bitmap) {
        try {
            File dir = new File(getFilesDir(), "support_uploads");
            if (!dir.exists() && !dir.mkdirs()) {
                return null;
            }
            File file = new File(dir, "customer_support_" + System.currentTimeMillis() + ".jpg");
            FileOutputStream output = new FileOutputStream(file);
            bitmap.compress(Bitmap.CompressFormat.JPEG, 72, output);
            output.flush();
            output.close();
            return file;
        } catch (Exception ignored) {
            return null;
        }
    }

    private void dispatchCustomerSupportMessage(String type, String message, String ticketId, String messageId, String attachmentPath, boolean fromQueue) {
        if (TextUtils.isEmpty(messageId)) {
            messageId = supportMessageId("CUSMSG");
        }
        if (!isNetworkOnline()) {
            queueCustomerSupportMessage(type, message, ticketId, messageId, attachmentPath);
            updateSupportMessageStatus(messageId, "Queued");
            return;
        }
        String finalMessageId = messageId;
        ensureFirebaseReady(() -> writeCustomerSupportMessage(type, message, ticketId, finalMessageId, attachmentPath));
    }

    private void writeCustomerSupportMessage(String type, String message, String ticketId, String messageId, String attachmentPath) {
        if (!TextUtils.isEmpty(attachmentPath)) {
            uploadCustomerSupportAttachment(messageId, attachmentPath, url ->
                    writeCustomerSupportMessageDocument(type, message, ticketId, messageId, url, true, attachmentPath)
            );
            return;
        }
        writeCustomerSupportMessageDocument(type, message, ticketId, messageId, "", false, "");
    }

    private void uploadCustomerSupportAttachment(String messageId, String attachmentPath, SupportUploadCallback callback) {
        File file = new File(attachmentPath);
        if (!file.exists()) {
            updateSupportMessageStatus(messageId, "Failed - tap retry");
            return;
        }
        if (file.length() > SUPPORT_UPLOAD_MAX_BYTES) {
            updateSupportMessageStatus(messageId, "Failed - retake photo");
            Toast.makeText(this, "Photo too large. Please retake a clear photo.", Toast.LENGTH_SHORT).show();
            return;
        }
        if (firebaseStorage == null) {
            firebaseStorage = FirebaseStorage.getInstance();
        }
        updateSupportMessageStatus(messageId, "Uploading");
        StorageReference ref = firebaseStorage.getReference().child("support_uploads/customer/" + supportOwnerUid() + "/" + messageId + ".jpg");
        StorageMetadata metadata = new StorageMetadata.Builder().setContentType("image/jpeg").build();
        ref.putFile(Uri.fromFile(file), metadata)
                .addOnSuccessListener(snapshot -> ref.getDownloadUrl()
                        .addOnSuccessListener(uri -> callback.onUploaded(uri.toString()))
                        .addOnFailureListener(error -> {
                            queueCustomerSupportMessage("attachment", "Photo attachment", "", messageId, attachmentPath);
                            updateSupportMessageStatus(messageId, "Failed - tap retry");
                        }))
                .addOnFailureListener(error -> {
                    queueCustomerSupportMessage("attachment", "Photo attachment", "", messageId, attachmentPath);
                    updateSupportMessageStatus(messageId, "Failed - tap retry");
                });
    }

    private void deleteQuietly(File file) {
        try {
            if (file != null && file.exists()) {
                file.delete();
            }
        } catch (Exception ignored) {
        }
    }

    private void writeCustomerSupportMessageDocument(String type, String message, String ticketId, String messageId, String attachmentUrl, boolean hasAttachment, String attachmentPath) {
        Map<String, Object> payload = new HashMap<>();
        payload.put("clientMessageId", messageId);
        payload.put("ticketId", ticketId == null ? "" : ticketId);
        payload.put("type", TextUtils.isEmpty(type) ? "chat" : type);
        payload.put("message", message);
        payload.put("senderRole", "customer");
        payload.put("ownerUid", supportOwnerUid());
        payload.put("customerName", customerName());
        payload.put("customerPhone", customerPhone());
        payload.put("bookingId", latestBooking == null ? "" : latestBooking.getId());
        payload.put("deliveryStatus", "sent");
        payload.put("createdAtMillis", System.currentTimeMillis());
        payload.put("sentAtMillis", System.currentTimeMillis());
        payload.put("hasAttachment", hasAttachment);
        payload.put("attachmentUrl", attachmentUrl == null ? "" : attachmentUrl);
        monitorCustomerSupportFraud(message, messageId);

        if (realtimeDatabase != null) {
            realtimeDatabase.getReference("customer_support_messages").child(messageId).updateChildren(new HashMap<>(payload));
        }
        Map<String, Object> firestorePayload = new HashMap<>(payload);
        firestorePayload.put("createdAt", FieldValue.serverTimestamp());
        firestore.collection("customer_support_messages")
                .document(messageId)
                .set(firestorePayload, SetOptions.merge())
                .addOnSuccessListener(ref -> {
                    removeQueuedCustomerSupportMessage(messageId);
                    updateSupportMessageStatus(messageId, "Sent");
                    carouselHandler.postDelayed(() -> updateSupportMessageStatus(messageId, "Delivered"), 500);
                    if (!TextUtils.isEmpty(ticketId) && messageId.equals(activeSupportComplaintMessageId)) {
                        writeCustomerSupportTicket(type, message, ticketId, messageId, attachmentUrl);
                    }
                    if (hasAttachment) {
                        deleteQuietly(new File(attachmentPath));
                    }
                })
                .addOnFailureListener(error -> {
                    queueCustomerSupportMessage(type, message, ticketId, messageId, hasAttachment ? attachmentPath : "");
                    updateSupportMessageStatus(messageId, "Failed - tap retry");
                });
    }

    private void monitorCustomerSupportFraud(String message, String messageId) {
        if (backendClient == null || TextUtils.isEmpty(message)) {
            return;
        }
        String bookingId = !TextUtils.isEmpty(latestBackendBookingId)
                ? latestBackendBookingId
                : (latestBooking == null ? "" : latestBooking.getId());
        if (!TextUtils.isEmpty(bookingId)) {
            backendClient.monitorBookingChat(bookingId, message, messageId);
        }
    }

    private void writeCustomerSupportTicket(String type, String message, String ticketId, String messageId, String attachmentUrl) {
        Map<String, Object> request = new HashMap<>();
        request.put("ticketId", ticketId);
        request.put("type", type);
        request.put("message", message);
        request.put("lastMessageId", messageId);
        request.put("customerName", customerName());
        request.put("ownerUid", supportOwnerUid());
        request.put("customerPhone", customerPhone());
        request.put("bookingId", latestBooking == null ? "" : latestBooking.getId());
        request.put("status", "open");
        request.put("deliveryStatus", "sent");
        request.put("attachmentUrl", attachmentUrl == null ? "" : attachmentUrl);
        request.put("createdAtMillis", System.currentTimeMillis());
        if (realtimeDatabase != null) {
            realtimeDatabase.getReference("customer_support_requests").child(ticketId).updateChildren(request);
        }
        Map<String, Object> firestoreRequest = new HashMap<>(request);
        firestoreRequest.put("createdAt", FieldValue.serverTimestamp());
        firestore.collection("customer_support_requests")
                .document(ticketId)
                .set(firestoreRequest, SetOptions.merge())
                .addOnFailureListener(error -> {});
        if (backendClient != null) {
            backendClient.syncSupportTicket(
                    ticketId,
                    messageId,
                    "user",
                    customerName(),
                    message,
                    type,
                    !TextUtils.isEmpty(latestBackendBookingId)
                            ? latestBackendBookingId
                            : (latestBooking == null ? "" : latestBooking.getId()),
                    attachmentUrl,
                    new BackendClient.JsonCallback() {
                        @Override public void onSuccess(JSONObject object) {
                            String serverTicketId = object.optString("publicId", object.optString("ticketId", ""));
                            if (!TextUtils.isEmpty(serverTicketId)) activeSupportTicketId = serverTicketId;
                        }
                        @Override public void onError(String ignored) { }
                    }
            );
        }
    }

    private void queueCustomerSupportMessage(String type, String message, String ticketId, String messageId, String attachmentPath) {
        try {
            JSONArray queue = pendingCustomerSupportQueue();
            JSONArray updated = new JSONArray();
            boolean replaced = false;
            for (int index = 0; index < queue.length(); index++) {
                JSONObject item = queue.optJSONObject(index);
                if (item == null) {
                    continue;
                }
                if (messageId.equals(item.optString("id"))) {
                    updated.put(customerSupportQueueItem(type, message, ticketId, messageId, attachmentPath, item.optInt("attempts", 0) + 1));
                    replaced = true;
                } else {
                    updated.put(item);
                }
            }
            if (!replaced) {
                updated.put(customerSupportQueueItem(type, message, ticketId, messageId, attachmentPath, 0));
            }
            putSecureString(KEY_PENDING_SUPPORT_QUEUE, updated.toString());
        } catch (Exception ignored) {
        }
    }

    private JSONObject customerSupportQueueItem(String type, String message, String ticketId, String messageId, String attachmentPath, int attempts) {
        JSONObject item = new JSONObject();
        try {
            item.put("id", messageId);
            item.put("type", TextUtils.isEmpty(type) ? "chat" : type);
            item.put("message", message == null ? "" : message);
            item.put("ticketId", ticketId == null ? "" : ticketId);
            item.put("attachmentPath", attachmentPath == null ? "" : attachmentPath);
            item.put("attempts", attempts);
            item.put("createdAtMillis", System.currentTimeMillis());
        } catch (Exception ignored) {
        }
        return item;
    }

    private String supportOwnerUid() {
        return firebaseAuth != null && firebaseAuth.getCurrentUser() != null
                ? firebaseAuth.getCurrentUser().getUid()
                : "";
    }

    private JSONArray pendingCustomerSupportQueue() {
        try {
            return new JSONArray(secureString(KEY_PENDING_SUPPORT_QUEUE, "[]"));
        } catch (Exception ignored) {
            removeSecureString(KEY_PENDING_SUPPORT_QUEUE);
            return new JSONArray();
        }
    }

    private void removeQueuedCustomerSupportMessage(String messageId) {
        try {
            JSONArray queue = pendingCustomerSupportQueue();
            JSONArray updated = new JSONArray();
            for (int index = 0; index < queue.length(); index++) {
                JSONObject item = queue.optJSONObject(index);
                if (item != null && !messageId.equals(item.optString("id"))) {
                    updated.put(item);
                }
            }
            putSecureString(KEY_PENDING_SUPPORT_QUEUE, updated.toString());
        } catch (Exception ignored) {
        }
    }

    private void retryQueuedCustomerSupportMessage(String messageId) {
        JSONArray queue = pendingCustomerSupportQueue();
        for (int index = 0; index < queue.length(); index++) {
            JSONObject item = queue.optJSONObject(index);
            if (item != null && messageId.equals(item.optString("id"))) {
                updateSupportMessageStatus(messageId, isNetworkOnline() ? "Retrying" : "Queued");
                dispatchCustomerSupportMessage(
                        item.optString("type", "chat"),
                        item.optString("message", ""),
                        item.optString("ticketId", ""),
                        messageId,
                        item.optString("attachmentPath", ""),
                        true
                );
                return;
            }
        }
    }

    private void flushQueuedCustomerSupportMessages() {
        if (supportQueueSyncing || !isNetworkOnline()) {
            return;
        }
        JSONArray queue = pendingCustomerSupportQueue();
        if (queue.length() == 0) {
            return;
        }
        supportQueueSyncing = true;
        for (int index = 0; index < queue.length(); index++) {
            JSONObject item = queue.optJSONObject(index);
            if (item == null) {
                continue;
            }
            String id = item.optString("id");
            updateSupportMessageStatus(id, "Retrying");
            dispatchCustomerSupportMessage(
                    item.optString("type", "chat"),
                    item.optString("message", ""),
                    item.optString("ticketId", ""),
                    id,
                    item.optString("attachmentPath", ""),
                    true
            );
        }
        carouselHandler.postDelayed(() -> supportQueueSyncing = false, 2200L);
    }

    private interface SupportUploadCallback {
        void onUploaded(String url);
    }

    private boolean shouldShowSupportBookingCard(String message) {
        if (latestBooking == null || message == null) {
            return false;
        }
        String lower = message.toLowerCase(Locale.US);
        return lower.contains("booking") || lower.contains("status") || lower.contains("track");
    }

    private boolean shouldShowSupportFeedback(String message) {
        if (message == null) {
            return false;
        }
        String lower = message.toLowerCase(Locale.US);
        return lower.contains("thanks")
                || lower.contains("thank you")
                || lower.contains("done")
                || lower.contains("resolved")
                || lower.contains("close")
                || lower.contains("bye")
                || lower.contains("ok")
                || lower.contains("thik")
                || lower.contains("ho gaya");
    }

