    private void removeTransientBookingScreensFromHistory() {
        for (int i = screenHistory.size() - 1; i >= 0; i--) {
            String screen = screenHistory.get(i);
            if ("booking".equals(screen)
                    || "confirm".equals(screen)
                    || "booking_submitting".equals(screen)) {
                screenHistory.remove(i);
            }
        }
    }

