    private int heroFeatureIconColor(String icon, String title) {
        String key = (icon + " " + title).toLowerCase(Locale.US);
        if (key.contains("\u2713") || key.contains("verified")) {
            return GREEN;
        }
        if (key.contains("\u2605") || key.contains("\u2606") || key.contains("satisfaction")) {
            return Color.rgb(235, 168, 34);
        }
        if (key.contains("\u20B9") || key.contains("pricing")) {
            return Color.rgb(21, 142, 122);
        }
        if (key.contains("\u23F1") || key.contains("time")) {
            return Color.rgb(42, 124, 230);
        }
        return ORANGE;
    }

