    private int compactBannerTitleSize(Service service) {
        String value = bannerTitle(service);
        if (value.length() >= 10) {
            return 24;
        }
        if (value.length() >= 8) {
            return 26;
        }
        return 28;
    }

    private void startHeroBackgroundCarousel(FrameLayout banner, TextView kicker, TextView title, TextView line, TextView cta, ImageView background, TextView dots) {
        stopBannerCarousel();
        List<Service> slides = carouselServices();
        bannerIndex = 0;
        applyHeroBackgroundSlide(slides, kicker, title, line, cta, background, dots, false);
        carouselRunnable = new Runnable() {
            @Override
            public void run() {
                bannerIndex = (bannerIndex + 1) % slides.size();
                applyHeroBackgroundSlide(slides, kicker, title, line, cta, background, dots, true);
                carouselHandler.postDelayed(this, 2800);
            }
        };
        attachHeroSwipe(banner, slides, kicker, title, line, cta, background, dots, carouselRunnable);
        carouselHandler.postDelayed(carouselRunnable, 2600);
    }

    private void attachHeroSwipe(FrameLayout banner, List<Service> slides, TextView kicker, TextView title, TextView line, TextView cta, ImageView background, TextView dots, Runnable autoRunnable) {
        final float[] startX = new float[1];
        final float[] startY = new float[1];
        final boolean[] tracking = new boolean[1];
        banner.setClickable(true);
        banner.setOnTouchListener((view, event) -> {
            switch (event.getActionMasked()) {
                case MotionEvent.ACTION_DOWN:
                    startX[0] = event.getX();
                    startY[0] = event.getY();
                    tracking[0] = true;
                    return false;
                case MotionEvent.ACTION_MOVE:
                    if (!tracking[0]) {
                        return false;
                    }
                    float moveDx = event.getX() - startX[0];
                    float moveDy = event.getY() - startY[0];
                    if (Math.abs(moveDx) > dp(12) && Math.abs(moveDx) > Math.abs(moveDy) * 1.25f) {
                        view.getParent().requestDisallowInterceptTouchEvent(true);
                    }
                    return false;
                case MotionEvent.ACTION_UP:
                    if (!tracking[0]) {
                        return false;
                    }
                    tracking[0] = false;
                    float dx = event.getX() - startX[0];
                    float dy = event.getY() - startY[0];
                    if (Math.abs(dx) > dp(48) && Math.abs(dx) > Math.abs(dy) * 1.25f) {
                        view.getParent().requestDisallowInterceptTouchEvent(false);
                        showHeroSlideByTouch(slides, kicker, title, line, cta, background, dots, dx < 0 ? 1 : -1, autoRunnable);
                        return true;
                    }
                    view.getParent().requestDisallowInterceptTouchEvent(false);
                    return false;
                case MotionEvent.ACTION_CANCEL:
                    tracking[0] = false;
                    view.getParent().requestDisallowInterceptTouchEvent(false);
                    return false;
                default:
                    return false;
            }
        });
    }

    private void showHeroSlideByTouch(List<Service> slides, TextView kicker, TextView title, TextView line, TextView cta, ImageView background, TextView dots, int direction, Runnable autoRunnable) {
        if (slides == null || slides.isEmpty()) {
            return;
        }
        if (carouselRunnable != null) {
            carouselHandler.removeCallbacks(carouselRunnable);
        }
        bannerIndex = (bannerIndex + direction + slides.size()) % slides.size();
        applyHeroBackgroundSlide(slides, kicker, title, line, cta, background, dots, true);
        carouselHandler.postDelayed(autoRunnable, 3400);
    }

    private void applyHeroBackgroundSlide(List<Service> slides, TextView kicker, TextView title, TextView line, TextView cta, ImageView background, TextView dots, boolean animate) {
        Service service = slides.get(bannerIndex);
        selectedService = service;
        kicker.setText("VERIFIED SERVICE  \u2713");
        title.setText(bannerTitle(service));
        title.setTextSize(compactBannerTitleSize(service));
        title.setSingleLine(true);
        line.setText(bannerLine(service));
        line.setSingleLine(true);
        cta.setText("Book Slot  \u203A");
        cta.setOnClickListener(view -> showBooking(service));
        int bannerImage = bannerServiceImageResource(service);
        int imageResource = bannerImage == 0 ? serviceLogoResource(service) : bannerImage;
        if (imageResource != 0) {
            background.setImageResource(imageResource);
            background.setScaleType(ImageView.ScaleType.CENTER_CROP);
            background.setPadding(0, 0, 0, 0);
        }
        dots.setText(carouselDots(slides.size()));

        if (!animate) {
            return;
        }

        View[] textTargets = {kicker, title, line, cta, dots};
        for (int i = 0; i < textTargets.length; i++) {
            View target = textTargets[i];
            target.animate().cancel();
            target.setAlpha(0f);
            target.setTranslationX(dp(16));
            target.animate()
                    .alpha(1f)
                    .translationX(0f)
                    .setStartDelay(i * 35L)
                    .setDuration(300)
                    .setInterpolator(new AccelerateDecelerateInterpolator())
                    .start();
        }
        background.animate().cancel();
        background.setAlpha(0.35f);
        background.animate()
                .alpha(1f)
                .setDuration(360)
                .setInterpolator(new AccelerateDecelerateInterpolator())
                .start();
    }

