    private void startBannerCarousel(TextView kicker, TextView title, TextView line, TextView cta, ImageView logo, TextView visualTitle, TextView visualMeta, TextView dots) {
        stopBannerCarousel();
        List<Service> slides = carouselServices();
        bannerIndex = 0;
        applyBannerSlide(slides, kicker, title, line, cta, logo, visualTitle, visualMeta, dots, false);
        carouselRunnable = new Runnable() {
            @Override
            public void run() {
                bannerIndex = (bannerIndex + 1) % slides.size();
                applyBannerSlide(slides, kicker, title, line, cta, logo, visualTitle, visualMeta, dots, true);
                carouselHandler.postDelayed(this, 2600);
            }
        };
        carouselHandler.postDelayed(carouselRunnable, 2300);
    }

    private void applyBannerSlide(List<Service> slides, TextView kicker, TextView title, TextView line, TextView cta, ImageView logo, TextView visualTitle, TextView visualMeta, TextView dots, boolean animate) {
        Service service = slides.get(bannerIndex);
        selectedService = service;
        kicker.setText("VERIFIED SERVICE");
        title.setText(bannerTitle(service));
        title.setTextSize(bannerTitleSize(service));
        title.setSingleLine(true);
        line.setText(bannerLine(service));
        line.setSingleLine(true);
        cta.setText("Book Slot  ›");
        cta.setSingleLine(true);
        cta.setOnClickListener(view -> showBooking(service));
        int bannerImage = bannerServiceImageResource(service);
        int logoResource = bannerImage == 0 ? serviceLogoResource(service) : bannerImage;
        if (logoResource != 0) {
            logo.setImageResource(logoResource);
            boolean hasPhoto = bannerImage != 0;
            logo.setScaleType(ImageView.ScaleType.FIT_CENTER);
            int padding = hasPhoto ? dp(2) : dp(10);
            logo.setPadding(padding, padding, padding, padding);
        }
        visualTitle.setText("Verified expert");
        visualMeta.setText(service.getRating() + " ★  •  " + service.getArrival());
        dots.setText(carouselDots(slides.size()));

        if (!animate) {
            return;
        }

        View[] targets = {kicker, title, line, cta, logo, visualTitle, visualMeta, dots};
        for (int i = 0; i < targets.length; i++) {
            View target = targets[i];
            target.animate().cancel();
            target.setAlpha(0f);
            target.setTranslationX(dp(18));
            target.animate()
                    .alpha(1f)
                    .translationX(0f)
                    .setStartDelay(i * 35L)
                    .setDuration(330)
                    .setInterpolator(new AccelerateDecelerateInterpolator())
                    .start();
        }
    }

    private List<Service> carouselServices() {
        List<Service> slides = new ArrayList<>();
        String[] ids = {"ro", "ac", "electrician", "plumbing", "cleaning", "laundry", "roadside", "appliances", "painting", "interior"};
        for (String id : ids) {
            slides.add(serviceById(id));
        }
        return slides;
    }

