    private CharSequence carouselDots(int count) {
        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < count; i++) {
            if (i > 0) {
                builder.append("  ");
            }
            builder.append(i == bannerIndex ? "\u25CF" : "\u25CB");
        }
        SpannableString dots = new SpannableString(builder.toString());
        for (int i = 0; i < dots.length(); i++) {
            char character = dots.charAt(i);
            if (character == '\u25CF') {
                dots.setSpan(new ForegroundColorSpan(BLACK), i, i + 1, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
            } else if (character == '\u25CB') {
                dots.setSpan(new ForegroundColorSpan(Color.rgb(177, 158, 154)), i, i + 1, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
            }
        }
        return dots;
    }

