    private void showServiceSearchDialog() {
        if (!requireFeature(FeatureRegistry.SEARCH, "Search")) return;
        AlertDialog dialog = new AlertDialog.Builder(this).create();
        LinearLayout sheet = vertical();
        sheet.setClipChildren(false);
        sheet.setClipToPadding(false);
        sheet.setPadding(dp(16), dp(16), dp(16), dp(14));
        sheet.setBackground(searchSheetDrawable());
        sheet.setElevation(dp(18));

        LinearLayout searchRow = horizontal();
        searchRow.setGravity(Gravity.CENTER_VERTICAL);
        searchRow.setPadding(dp(12), 0, dp(8), 0);
        searchRow.setBackground(stroke(Color.WHITE, Color.rgb(236, 221, 221), dp(14)));
        searchRow.addView(tintedIcon(R.drawable.ic_search_lens, ORANGE, 8), new LinearLayout.LayoutParams(dp(34), dp(46)));

        EditText input = new EditText(this);
        input.setSingleLine(true);
        input.setHint("Search services...");
        input.setTextSize(16);
        input.setTextColor(BLACK);
        input.setHintTextColor(Color.rgb(148, 143, 143));
        input.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);
        input.setPadding(dp(2), 0, dp(8), 0);
        input.setBackgroundColor(Color.TRANSPARENT);
        searchRow.addView(input, new LinearLayout.LayoutParams(0, -1, 1));

        TextView clearInput = text("\u00D7", 18, Color.rgb(178, 178, 178), true);
        clearInput.setGravity(Gravity.CENTER);
        clearInput.setOnClickListener(view -> {
            if (input.length() > 0) {
                input.setText("");
            } else {
                dialog.dismiss();
            }
        });
        searchRow.addView(clearInput, new LinearLayout.LayoutParams(dp(32), dp(42)));
        sheet.addView(searchRow, margin(-1, 50, 0, 0, 0, 16));

        LinearLayout recentBlock = vertical();
        sheet.addView(recentBlock, margin(-1, -2, 0, 0, 0, 16));
        renderRecentSearchBlock(recentBlock, input);

        TextView helper = text("Popular Services", 14, BLACK, true);
        sheet.addView(helper, margin(-1, -2, 0, 0, 0, 10));

        LinearLayout results = vertical();
        sheet.addView(results);
        renderServiceSearchResults("", results, helper, dialog);

        input.addTextChangedListener(new TextWatcher() {
            @Override
            public void beforeTextChanged(CharSequence s, int start, int count, int after) {
            }

            @Override
            public void onTextChanged(CharSequence s, int start, int before, int count) {
                renderServiceSearchResults(s == null ? "" : s.toString(), results, helper, dialog);
            }

            @Override
            public void afterTextChanged(Editable s) {
            }
        });

        dialog.setView(sheet, 0, 0, 0, 0);
        dialog.setOnShowListener(d -> {
            input.requestFocus();
            android.view.Window window = dialog.getWindow();
            if (window != null) {
                window.setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(Color.TRANSPARENT));
                window.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE | WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_VISIBLE);
                window.setLayout((int) (getResources().getDisplayMetrics().widthPixels * 0.94f), WindowManager.LayoutParams.WRAP_CONTENT);
                WindowManager.LayoutParams params = window.getAttributes();
                params.gravity = Gravity.TOP | Gravity.CENTER_HORIZONTAL;
                params.y = dp(96);
                window.setAttributes(params);
            }
        });
        dialog.show();
    }

    private void renderRecentSearchBlock(LinearLayout block, EditText input) {
        block.removeAllViews();
        List<String> recent = loadRecentServiceSearches();
        if (recent.isEmpty()) {
            block.setVisibility(View.GONE);
            return;
        }
        block.setVisibility(View.VISIBLE);

        LinearLayout header = horizontal();
        header.setGravity(Gravity.CENTER_VERTICAL);
        header.addView(text("Recent Searches", 13, BLACK, true), new LinearLayout.LayoutParams(0, -2, 1));
        TextView clear = text("Clear all", 11, ORANGE, true);
        clear.setGravity(Gravity.CENTER);
        clear.setOnClickListener(view -> {
            saveRecentServiceSearches(new ArrayList<>());
            renderRecentSearchBlock(block, input);
        });
        header.addView(clear);
        block.addView(header, margin(-1, -2, 0, 0, 0, 8));

        LinearLayout row = null;
        for (int index = 0; index < recent.size(); index++) {
            if (index % 3 == 0) {
                row = horizontal();
                block.addView(row, margin(-1, -2, 0, index == 0 ? 0 : 6, 0, 0));
            }
            row.addView(recentSearchChip(recent.get(index), input, block), margin(-2, 34, 0, 0, 8, 0));
        }
    }

    private View recentSearchChip(String label, EditText input, LinearLayout recentBlock) {
        LinearLayout chip = horizontal();
        chip.setGravity(Gravity.CENTER_VERTICAL);
        chip.setPadding(dp(10), 0, dp(7), 0);
        chip.setBackground(stroke(Color.WHITE, Color.rgb(247, 216, 222), dp(17)));
        TextView clock = text("\u25CC", 13, ORANGE, true);
        clock.setGravity(Gravity.CENTER);
        chip.addView(clock, new LinearLayout.LayoutParams(dp(18), dp(28)));
        TextView value = text(label, 11, BLACK, true);
        value.setSingleLine(true);
        chip.addView(value, margin(-2, -2, 4, 0, 6, 0));
        TextView close = text("\u00D7", 12, Color.rgb(108, 101, 101), true);
        close.setGravity(Gravity.CENTER);
        close.setOnClickListener(view -> {
            removeRecentServiceSearch(label);
            renderRecentSearchBlock(recentBlock, input);
        });
        chip.addView(close, new LinearLayout.LayoutParams(dp(18), dp(28)));
        chip.setOnClickListener(view -> {
            input.setText(label);
            input.setSelection(input.length());
        });
        addPressAnimation(chip);
        return chip;
    }

    private void renderServiceSearchResults(String query, LinearLayout results, TextView helper, AlertDialog dialog) {
        results.removeAllViews();
        String clean = normalizeSearch(query);
        List<Service> matches = TextUtils.isEmpty(clean) ? searchPanelPopularServices() : searchServices(query);
        helper.setText("Popular Services");
        int limit = Math.min(TextUtils.isEmpty(clean) ? 7 : 5, matches.size());
        for (int index = 0; index < limit; index++) {
            results.addView(serviceSearchResultRow(matches.get(index), dialog), margin(-1, 58, 0, 0, 0, 8));
        }
        if (limit == 0) {
            results.addView(serviceSearchEmpty(query));
        }
        results.addView(viewAllSearchServicesRow(dialog), margin(-1, 42, 0, 4, 0, 0));
    }

