    private List<String> loadRecentServiceSearches() {
        String saved = getSharedPreferences(PREFS, MODE_PRIVATE).getString(KEY_RECENT_SERVICE_SEARCHES, null);
        List<String> values = new ArrayList<>();
        if (saved == null) {
            values.add("AC repair");
            values.add("Plumber");
            values.add("Electrician");
            values.add("Sofa cleaning");
            return values;
        }
        if (saved.trim().isEmpty()) {
            return values;
        }
        String[] parts = saved.split("\\|");
        for (String part : parts) {
            String value = part.trim();
            if (!value.isEmpty()) {
                values.add(value);
            }
            if (values.size() == 6) {
                break;
            }
        }
        return values;
    }

    private void rememberServiceSearch(String value) {
        if (TextUtils.isEmpty(value)) {
            return;
        }
        List<String> recent = loadRecentServiceSearches();
        List<String> updated = new ArrayList<>();
        updated.add(value);
        String cleanValue = normalizeSearch(value);
        for (String item : recent) {
            if (!normalizeSearch(item).equals(cleanValue)) {
                updated.add(item);
            }
            if (updated.size() == 6) {
                break;
            }
        }
        saveRecentServiceSearches(updated);
    }

    private void removeRecentServiceSearch(String value) {
        List<String> recent = loadRecentServiceSearches();
        List<String> updated = new ArrayList<>();
        String cleanValue = normalizeSearch(value);
        for (String item : recent) {
            if (!normalizeSearch(item).equals(cleanValue)) {
                updated.add(item);
            }
        }
        saveRecentServiceSearches(updated);
    }

    private void saveRecentServiceSearches(List<String> values) {
        StringBuilder builder = new StringBuilder();
        for (String value : values) {
            if (TextUtils.isEmpty(value)) {
                continue;
            }
            if (builder.length() > 0) {
                builder.append("|");
            }
            builder.append(value.replace("|", " ").trim());
        }
        getSharedPreferences(PREFS, MODE_PRIVATE)
                .edit()
                .putString(KEY_RECENT_SERVICE_SEARCHES, builder.toString())
                .apply();
    }

