    private void renderLegacyServiceSearchResults(String query, LinearLayout results, TextView helper, AlertDialog dialog) {
        results.removeAllViews();
        List<Service> matches = searchServices(query);
        String clean = normalizeSearch(query);
        if (TextUtils.isEmpty(clean)) {
            helper.setText("Popular services");
        } else if (!matches.isEmpty() && serviceSearchScore(matches.get(0), clean) < 120) {
            helper.setText("Closest matches for \"" + query.trim() + "\"");
        } else {
            helper.setText("Results for \"" + query.trim() + "\"");
        }
        int limit = Math.min(5, matches.size());
        for (int index = 0; index < limit; index++) {
            Service service = matches.get(index);
            results.addView(serviceSearchResultRow(service, dialog), margin(-1, -2, 0, 0, 0, 9));
        }
        if (limit == 0) {
            results.addView(serviceSearchEmpty(query));
        }
    }

    private List<Service> searchServices(String query) {
        String clean = normalizeSearch(query);
        List<Service> source = new ArrayList<>(services);
        Collections.sort(source, (left, right) -> Integer.compare(serviceSearchScore(right, clean), serviceSearchScore(left, clean)));
        if (TextUtils.isEmpty(clean)) {
            return source.subList(0, Math.min(5, source.size()));
        }
        List<Service> matches = new ArrayList<>();
        for (Service service : source) {
            if (serviceSearchScore(service, clean) >= 45) {
                matches.add(service);
            }
        }
        if (matches.isEmpty() && !source.isEmpty()) {
            matches.add(source.get(0));
        }
        return matches;
    }

    private int serviceSearchScore(Service service, String cleanQuery) {
        if (service == null) {
            return 0;
        }
        if (TextUtils.isEmpty(cleanQuery)) {
            if ("ac".equals(service.getId())) return 100;
            if ("plumbing".equals(service.getId())) return 92;
        if ("electrician".equals(service.getId())) return 88;
        if ("cleaning".equals(service.getId())) return 82;
        if ("laundry".equals(service.getId())) return 80;
        if ("ro".equals(service.getId())) return 78;
        return 70;
        }
        int best = 0;
        String[] haystack = serviceSearchTerms(service);
        for (String term : haystack) {
            String cleanTerm = normalizeSearch(term);
            if (TextUtils.isEmpty(cleanTerm)) {
                continue;
            }
            if (cleanTerm.equals(cleanQuery)) {
                best = Math.max(best, 160);
            } else if (cleanTerm.contains(cleanQuery) || cleanQuery.contains(cleanTerm)) {
                best = Math.max(best, 125 - Math.abs(cleanTerm.length() - cleanQuery.length()));
            } else {
                int distance = editDistance(cleanQuery, cleanTerm);
                int max = Math.max(cleanQuery.length(), cleanTerm.length());
                int score = Math.max(0, 105 - (distance * 100 / Math.max(1, max)));
                best = Math.max(best, score);
            }
        }
        return best;
    }

    private String[] serviceSearchTerms(Service service) {
        String id = service.getId();
        if ("ac".equals(id)) return new String[]{"ac", "ac repair", "air conditioner", "cooling", "gas refill", service.getName(), service.getDescription()};
        if ("plumbing".equals(id)) return new String[]{"plumber", "plumbing", "pipe", "tap", "leakage", "drain", "flush", service.getName(), service.getDescription()};
        if ("electrician".equals(id)) return new String[]{"electrician", "electric", "wiring", "switch", "fan", "mcb", "socket", service.getName(), service.getDescription()};
        if ("carpenter".equals(id)) return new String[]{"carpenter", "wood", "door", "lock", "furniture", "curtain", service.getName(), service.getDescription()};
        if ("cleaning".equals(id)) return new String[]{"cleaning", "clean", "bathroom", "sofa", "deep clean", "home cleaning", service.getName(), service.getDescription()};
        if ("laundry".equals(id)) return new String[]{"laundry", "cloth", "clothes", "washing", "wash", "iron", "ironing", "dry clean", "dry cleaning", service.getName(), service.getDescription()};
        if ("pest".equals(id)) return new String[]{"pest", "cockroach", "termite", "insect", "pest control", service.getName(), service.getDescription()};
        if ("painting".equals(id)) return new String[]{"painting", "paint", "wall", "touch up", "damp", service.getName(), service.getDescription()};
        if ("roadside".equals(id)) return new String[]{"roadside", "tow", "jump start", "tyre", "vehicle", "car help", service.getName(), service.getDescription()};
        if ("ro".equals(id)) return new String[]{"ro", "ro service", "water purifier", "purifier", "filter", "water filter", "aqua", "leakage", "installation", service.getName(), service.getDescription()};
        if ("appliances".equals(id)) return new String[]{"appliance", "washing machine", "fridge", "refrigerator", "microwave", "geyser", "ro", service.getName(), service.getDescription()};
        if ("interior".equals(id)) return new String[]{"interior", "design", "room", "furniture placement", "lighting", service.getName(), service.getDescription()};
        return new String[]{id, service.getName(), service.getCategory(), service.getDescription()};
    }

    private String normalizeSearch(String value) {
        return value == null ? "" : value.toLowerCase(Locale.US).replaceAll("[^a-z0-9]+", "");
    }

    private int editDistance(String left, String right) {
        int[] previous = new int[right.length() + 1];
        int[] current = new int[right.length() + 1];
        for (int j = 0; j <= right.length(); j++) {
            previous[j] = j;
        }
        for (int i = 1; i <= left.length(); i++) {
            current[0] = i;
            for (int j = 1; j <= right.length(); j++) {
                int cost = left.charAt(i - 1) == right.charAt(j - 1) ? 0 : 1;
                current[j] = Math.min(Math.min(current[j - 1] + 1, previous[j] + 1), previous[j - 1] + cost);
            }
            int[] swap = previous;
            previous = current;
            current = swap;
        }
        return previous[right.length()];
    }

