    private void showNotifications() {
        if (!requireFeature(FeatureRegistry.NOTIFICATIONS, "Notifications")) return;
        setCurrentScreen("notifications");
        showAppChrome();
        setActiveNav(null);
        resetScreen();
        floatingFooter.setVisibility(View.GONE);
        addTopBar("Messages", "", view -> handleBackNavigation());

        TextView markAll = text("Mark all as read", 13, ORANGE, true);
        markAll.setGravity(Gravity.RIGHT);
        markAll.setOnClickListener(view -> backendClient.markAllNotificationsRead(new BackendClient.JsonCallback() {
            @Override
            public void onSuccess(JSONObject object) {
                userNotificationUnreadCount = 0;
                showNotifications();
            }

            @Override
            public void onError(String message) {
                Toast.makeText(MainActivity.this, "Could not update messages", Toast.LENGTH_SHORT).show();
            }
        }));
        screenContent.addView(markAll, margin(-1, 40, 20, 0, 20, 10));

        LinearLayout list = vertical();
        list.addView(userNotificationLoadingCard());
        screenContent.addView(list, margin(-1, -2, 20, 4, 20, 22));
        loadUserNotifications(list, 1, false);
    }

    private void loadUserNotifications(LinearLayout list, int page, boolean append) {
        backendClient.fetchNotifications(page, NOTIFICATION_PAGE_SIZE, new BackendClient.JsonCallback() {
            @Override
            public void onSuccess(JSONObject object) {
                userNotificationUnreadCount = object.optInt("unreadCount", 0);
                renderUserNotifications(
                        list,
                        object.optJSONArray("notifications"),
                        append,
                        page,
                        object.optInt("total", 0)
                );
            }

            @Override
            public void onError(String message) {
                if (!append) {
                    list.removeAllViews();
                    list.addView(userNotificationEmptyCard("Messages unavailable", "Messages could not be loaded from the backend. Reopen the app or check your network connection."));
                } else {
                    Toast.makeText(MainActivity.this, "More messages could not be loaded", Toast.LENGTH_SHORT).show();
                }
            }
        });
    }

    private void renderUserNotifications(LinearLayout list, JSONArray notifications, boolean append, int page, int total) {
        View previousLoadMore = list.findViewWithTag("notification_load_more");
        if (previousLoadMore != null) {
            list.removeView(previousLoadMore);
        }
        if (!append) {
            list.removeAllViews();
        }
        if (notifications == null || notifications.length() == 0) {
            if (!append) {
                list.addView(userNotificationEmptyCard("No messages yet", "Booking, payment, and support updates from ApnaServo will appear here."));
            }
            return;
        }
        for (int i = 0; i < notifications.length(); i++) {
            JSONObject item = notifications.optJSONObject(i);
            if (item != null) {
                list.addView(userNotificationRow(item), margin(-1, -2, 0, 0, 0, 12));
            }
        }
        if (page * NOTIFICATION_PAGE_SIZE < total) {
            TextView loadMore = text("Load more", 13, ORANGE, true);
            loadMore.setTag("notification_load_more");
            loadMore.setGravity(Gravity.CENTER);
            loadMore.setBackground(stroke(Color.WHITE, LINE, dp(14)));
            loadMore.setOnClickListener(view -> {
                loadMore.setEnabled(false);
                loadMore.setText("Loading...");
                loadUserNotifications(list, page + 1, true);
            });
            list.addView(loadMore, margin(-1, 46, 0, 4, 0, 12));
        }
    }

