    private void addTopBar(String title, String right, View.OnClickListener backClick) {
        LinearLayout row = horizontal();
        row.setGravity(Gravity.CENTER_VERTICAL);
        row.setPadding(dp(20), dp(18), dp(20), dp(10));
        TextView back = text("\u2039", 34, BLACK, false);
        back.setGravity(Gravity.CENTER);
        back.setOnClickListener(view -> handleBackNavigation());
        row.addView(back, new LinearLayout.LayoutParams(dp(34), dp(42)));
        TextView titleView = text(title, 16, BLACK, true);
        titleView.setGravity(Gravity.CENTER);
        row.addView(titleView, new LinearLayout.LayoutParams(0, -2, 1));
        TextView rightView = text(topBarRightIcon(right), 22, BLACK, true);
        rightView.setGravity(Gravity.CENTER);
        if (right != null && !right.isEmpty()) {
            rightView.setBackground(stroke(Color.WHITE, LINE, dp(16)));
            rightView.setElevation(dp(3));
            addPressAnimation(rightView);
            if ("search".equals(right)) {
                rightView.setOnClickListener(view -> showServiceSearchDialog());
            } else if ("heart".equals(right)) {
                rightView.setOnClickListener(view -> Toast.makeText(this, "Saved to favourites", Toast.LENGTH_SHORT).show());
            }
        }
        row.addView(rightView, new LinearLayout.LayoutParams(dp(42), dp(42)));
        screenContent.addView(row);
    }

    private String topBarRightIcon(String right) {
        if ("search".equals(right)) {
            return "\u2315";
        }
        if ("heart".equals(right)) {
            return "\u2661";
        }
        return right == null ? "" : right;
    }

