    private void addCommercialFlowHeader(String title, String subtitle) {
        LinearLayout header = horizontal();
        header.setGravity(Gravity.CENTER_VERTICAL);
        header.setPadding(dp(18), dp(14), dp(18), dp(6));
        TextView back = text("\u2190", 22, Color.rgb(135, 39, 53), true);
        back.setGravity(Gravity.CENTER);
        back.setOnClickListener(view -> handleBackNavigation());
        addPressAnimation(back);
        header.addView(back, new LinearLayout.LayoutParams(dp(34), dp(38)));
        LinearLayout copy = vertical();
        copy.setGravity(Gravity.CENTER);
        TextView titleView = text(title, 13, BLACK, true);
        titleView.setGravity(Gravity.CENTER);
        copy.addView(titleView);
        if (!TextUtils.isEmpty(subtitle)) {
            TextView subtitleView = text(subtitle, 11, MUTED, false);
            subtitleView.setGravity(Gravity.CENTER);
            subtitleView.setSingleLine(true);
            subtitleView.setEllipsize(TextUtils.TruncateAt.END);
            copy.addView(subtitleView, margin(-1, -2, 0, 1, 0, 0));
        }
        header.addView(copy, new LinearLayout.LayoutParams(0, -2, 1));
        View spacer = new View(this);
        header.addView(spacer, new LinearLayout.LayoutParams(dp(34), dp(38)));
        screenContent.addView(header);
    }

