    private View commercialInput(String label, String hint, int inputType) {
        LinearLayout wrap = vertical();
        wrap.addView(text(label, 11, BLACK, true), margin(-1, -2, 0, 0, 0, 6));
        EditText input = new EditText(this);
        input.setHint(hint);
        input.setSingleLine(true);
        input.setInputType(inputType);
        input.setTextSize(12);
        input.setTextColor(BLACK);
        input.setHintTextColor(Color.rgb(150, 145, 143));
        input.setPadding(dp(12), 0, dp(12), 0);
        input.setBackground(stroke(Color.WHITE, Color.rgb(231, 220, 218), dp(7)));
        wrap.addView(input, new LinearLayout.LayoutParams(-1, dp(42)));
        return marginWrap(wrap, -1, -2, 0, 0, 0, 12);
    }

    private View commercialMultilineInput(String label, String hint, int lines) {
        LinearLayout wrap = vertical();
        wrap.addView(text(label, 11, BLACK, true), margin(-1, -2, 0, 0, 0, 6));
        EditText input = new EditText(this);
        input.setHint(hint);
        input.setGravity(Gravity.TOP);
        input.setMinLines(lines);
        input.setMaxLines(lines);
        input.setSingleLine(false);
        input.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_MULTI_LINE);
        input.setTextSize(12);
        input.setTextColor(BLACK);
        input.setHintTextColor(Color.rgb(150, 145, 143));
        input.setPadding(dp(12), dp(10), dp(12), dp(10));
        input.setBackground(stroke(Color.WHITE, Color.rgb(231, 220, 218), dp(8)));
        wrap.addView(input, new LinearLayout.LayoutParams(-1, -1));
        return wrap;
    }

