    private View commercialSuccessMark(int color) {
        FrameLayout frame = new FrameLayout(this);
        frame.setBackground(successGlowDrawable());
        TextView tick = text("\u2713", 54, Color.WHITE, true);
        tick.setGravity(Gravity.CENTER);
        GradientDrawable ball = new GradientDrawable(
                GradientDrawable.Orientation.TL_BR,
                new int[]{lightenColor(color), color}
        );
        ball.setShape(GradientDrawable.OVAL);
        tick.setBackground(ball);
        FrameLayout.LayoutParams params = new FrameLayout.LayoutParams(dp(82), dp(82), Gravity.CENTER);
        frame.addView(tick, params);
        return frame;
    }

    private int lightenColor(int color) {
        return Color.rgb(
                Math.min(255, Color.red(color) + 48),
                Math.min(255, Color.green(color) + 48),
                Math.min(255, Color.blue(color) + 48)
        );
    }

