    private void addServiceShowcaseSection(String title, String[] ids) {
        LinearLayout titleRow = horizontal();
        titleRow.setGravity(Gravity.CENTER_VERTICAL);
        titleRow.setPadding(dp(18), 0, dp(18), 0);
        titleRow.addView(text(title, 17, BLACK, true), new LinearLayout.LayoutParams(0, -2, 1));

        TextView viewAll = text("View all", 12, ORANGE, true);
        viewAll.setGravity(Gravity.CENTER);
        viewAll.setOnClickListener(view -> showAllServices());
        addPressAnimation(viewAll);
        titleRow.addView(viewAll);
        screenContent.addView(titleRow, margin(-1, -2, 0, 7, 0, 9));

        LinearLayout section = vertical();
        section.setClipChildren(false);
        section.setClipToPadding(false);
        section.setPadding(dp(10), dp(12), dp(10), dp(10));
        section.setBackground(serviceShowcaseBackground());

        for (int index = 0; index < ids.length; index += 3) {
            LinearLayout row = horizontal();
            row.setClipChildren(false);
            row.setClipToPadding(false);
            for (int item = index; item < Math.min(index + 3, ids.length); item++) {
                Service service = serviceById(ids[item]);
                View tile = serviceShowcaseTile(service);
                animateIn(tile, 70 + item * 30);
                row.addView(tile, margin(0, 176, 5, 0, 5, index + 3 < ids.length ? 12 : 0, 1));
            }
            section.addView(row);
        }
        screenContent.addView(section, margin(-1, -2, 14, 0, 14, 16));
    }

    private View serviceShowcaseTile(Service service) {
        LinearLayout item = vertical();
        item.setGravity(Gravity.CENTER_HORIZONTAL);
        item.setClipChildren(false);
        item.setClipToPadding(false);
        item.setPadding(dp(2), 0, dp(2), 0);
        item.setOnClickListener(view -> showBooking(service));
        addPressAnimation(item);

        FrameLayout photo = new FrameLayout(this);
        photo.setClipChildren(true);
        photo.setClipToPadding(true);
        photo.setBackground(stroke(Color.WHITE, Color.rgb(244, 225, 228), dp(8)));
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
            photo.setClipToOutline(true);
        }

        ImageView image = new ImageView(this);
        int resource = servicePhotoResource(service);
        if (resource != 0) {
            image.setImageResource(resource);
        } else {
            image.setImageResource(serviceLogoResource(service));
        }
        image.setAdjustViewBounds(false);
        image.setScaleType(ImageView.ScaleType.CENTER_CROP);
        photo.addView(image, new FrameLayout.LayoutParams(-1, -1));
        item.addView(photo, new LinearLayout.LayoutParams(-1, dp(92)));

        TextView name = text(showcaseServiceTitle(service), 10, BLACK, true);
        name.setGravity(Gravity.CENTER);
        name.setMaxLines(2);
        name.setIncludeFontPadding(false);
        name.setLineSpacing(0, 0.94f);
        item.addView(name, margin(-1, 30, 0, 7, 0, 4));

        TextView book = text("Book", 11, Color.WHITE, true);
        book.setGravity(Gravity.CENTER);
        book.setBackground(bookGlowButtonDrawable());
        book.setElevation(dp(4));
        book.setOnClickListener(view -> showBooking(service));
        addPressAnimation(book);
        item.addView(book, new LinearLayout.LayoutParams(dp(68), dp(29)));
        return item;
    }

