    private void addServiceGrid(String[] ids) {
        for (int index = 0; index < ids.length; index += 3) {
            LinearLayout row = horizontal();
            row.setClipChildren(false);
            row.setClipToPadding(false);
            row.setPadding(dp(16), 0, dp(16), 0);
            for (int itemIndex = index; itemIndex < Math.min(index + 3, ids.length); itemIndex++) {
                Service service = serviceById(ids[itemIndex]);
                View tile = serviceTile(service);
                animateIn(tile, 80 + (itemIndex * 35));
                row.addView(tile, margin(0, 182, 4, 0, 4, 12, 1));
            }
            screenContent.addView(row);
        }
    }

    private View serviceTile(Service service) {
        boolean imageLogo = hasEmbeddedServiceTitle(service);
        boolean photoCard = servicePhotoResource(service) != 0;
        LinearLayout card = cardVertical(imageLogo ? 8 : 12);
        card.setClipChildren(false);
        card.setClipToPadding(false);
        card.setGravity(Gravity.CENTER_HORIZONTAL);
        card.setMinimumHeight(dp(182));
        card.setOnClickListener(view -> showBooking(service));
        addPressAnimation(card);

        int logoHeight = photoCard ? 88 : (imageLogo ? 76 : 42);
        card.addView(photoCard ? servicePhotoView(service) : serviceLogoView(service, logoHeight, false),
                margin(-1, logoHeight, 0, 0, 0, photoCard ? 6 : (imageLogo ? 4 : 6)));

        if (photoCard || !imageLogo) {
            TextView name = text(photoCard ? homeServiceCardTitle(service) : shortName(service), photoCard ? 10 : 13, BLACK, true);
            name.setGravity(Gravity.CENTER);
            name.setMaxLines(2);
            name.setIncludeFontPadding(false);
            name.setLineSpacing(0, photoCard ? 0.95f : 1f);
            card.addView(name, new LinearLayout.LayoutParams(-1, -2));
        }

        TextView hint = text("Book", 12, Color.WHITE, true);
        hint.setGravity(Gravity.CENTER);
        hint.setBackground(bookGlowButtonDrawable());
        hint.setElevation(dp(5));
        hint.setShadowLayer(dp(4), 0, 0, Color.argb(95, 255, 122, 40));
        hint.setPadding(dp(8), 0, dp(8), 0);
        startScalePulse(hint, 1.0f, 1.03f, 1250);
        card.addView(hint, margin(-1, 30, 14, photoCard ? 6 : (imageLogo ? 7 : 8), 14, 4));
        return card;
    }

    private View servicePhotoView(Service service) {
        FrameLayout frame = new FrameLayout(this);
        frame.setClipChildren(true);
        frame.setClipToPadding(true);
        frame.setPadding(0, 0, 0, 0);
        frame.setBackground(stroke(Color.WHITE, Color.rgb(241, 226, 226), dp(10)));
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
            frame.setClipToOutline(true);
        }

        int photo = servicePhotoResource(service);
        if (photo != 0) {
            ImageView image = new ImageView(this);
            image.setImageResource(photo);
            image.setAdjustViewBounds(false);
            image.setScaleType(ImageView.ScaleType.FIT_CENTER);
            image.setBackgroundColor(Color.WHITE);
            int photoInset = dp(4);
            image.setPadding(photoInset, photoInset, photoInset, photoInset);
            frame.addView(image, new FrameLayout.LayoutParams(-1, -1));
        } else {
            View logo = serviceLogoView(service, 46, false);
            FrameLayout.LayoutParams logoParams = new FrameLayout.LayoutParams(dp(46), dp(46), Gravity.CENTER);
            frame.addView(logo, logoParams);
        }
        return frame;
    }

