    private void addHomeTrustStrip() {
        FrameLayout ribbon = new FrameLayout(this);
        ribbon.setClipChildren(true);
        ribbon.setClipToPadding(true);
        ribbon.setPadding(dp(10), dp(5), dp(10), dp(5));
        ribbon.setBackground(stroke(Color.rgb(255, 253, 252), Color.rgb(242, 230, 226), dp(18)));
        ribbon.setElevation(dp(1));

        LinearLayout track = horizontal();
        track.setGravity(Gravity.CENTER_VERTICAL);
        addHomeTrustRibbonSet(track);
        addHomeTrustRibbonSet(track);
        ribbon.addView(track, new FrameLayout.LayoutParams(-2, -1));
        screenContent.addView(ribbon, margin(-1, 46, 16, 0, 16, 14));
        startHomeTrustRibbon(track);
    }

    private void addHomeTrustRibbonSet(LinearLayout track) {
        track.addView(homeTrustItem("\u2713", "Verified Experts", GREEN, Color.rgb(232, 250, 242)));
        track.addView(homeTrustConnector());
        track.addView(homeTrustItem("\u2316", "Auto Location", Color.rgb(45, 122, 218), Color.rgb(232, 241, 255)));
        track.addView(homeTrustConnector());
        track.addView(homeTrustItem("\u25F7", "Flexible Slots", Color.rgb(126, 88, 210), Color.rgb(242, 237, 255)));
        track.addView(homeTrustConnector());
    }

    private void startHomeTrustRibbon(View track) {
        stopHomeTrustRibbon();
        track.post(() -> {
            int distance = Math.max(1, track.getWidth() / 2);
            trustRibbonAnimator = ObjectAnimator.ofFloat(track, View.TRANSLATION_X, 0f, -distance);
            trustRibbonAnimator.setDuration(9000);
            trustRibbonAnimator.setInterpolator(new LinearInterpolator());
            trustRibbonAnimator.setRepeatCount(ValueAnimator.INFINITE);
            trustRibbonAnimator.setRepeatMode(ValueAnimator.RESTART);
            trustRibbonAnimator.start();
        });
    }

    private void stopHomeTrustRibbon() {
        if (trustRibbonAnimator != null) {
            trustRibbonAnimator.cancel();
            trustRibbonAnimator = null;
        }
    }

