    private void addStepper() {
        LinearLayout container = vertical();
        container.setPadding(dp(14), dp(4), dp(14), 0);

        LinearLayout dots = horizontal();
        dots.setGravity(Gravity.CENTER);
        for (int i = 0; i < 4; i++) {
            if (i > 0) {
                View line = new View(this);
                line.setBackgroundColor(i == 1 ? ORANGE : LINE);
                dots.addView(line, new LinearLayout.LayoutParams(0, dp(2), 1));
            }
            TextView circle = text(String.valueOf(i + 1), 14, i == 0 ? Color.WHITE : BLACK, true);
            circle.setGravity(Gravity.CENTER);
            circle.setBackground(round(i == 0 ? ORANGE : Color.rgb(231, 231, 231), dp(19)));
            circle.setElevation(i == 0 ? dp(5) : dp(2));
            circle.setTranslationZ(i == 0 ? dp(3) : dp(1));
            dots.addView(circle, new LinearLayout.LayoutParams(dp(38), dp(38)));
        }
        container.addView(dots, margin(-1, 38, 2, 0, 2, 6));

        LinearLayout labels = horizontal();
        String[] names = {"Service", "Date & Time", "Address", "Confirm"};
        for (int i = 0; i < names.length; i++) {
            TextView label = text(names[i], 13, i == 0 ? ORANGE : MUTED, true);
            label.setGravity(Gravity.CENTER);
            labels.addView(label, new LinearLayout.LayoutParams(0, -2, 1));
        }
        container.addView(labels);
        screenContent.addView(container, margin(-1, -2, 20, 0, 20, 20));
    }

