    private void applyDetectedLocation(Location location, String message) {
        if (addressInput == null) {
            return;
        }
        serviceLat = location.getLatitude();
        serviceLng = location.getLongitude();
        hasServiceLocation = true;
        final double requestedLat = serviceLat;
        final double requestedLng = serviceLng;
        addressInput.setText("Lat " + roundCoordinate(requestedLat) + ", Lng " + roundCoordinate(requestedLng));
        executeGeocoderTask(() -> {
            String resolved = formatLocation(location);
            runOnUiThread(() -> {
                if (isFinishing() || isDestroyed() || addressInput == null) return;
                if (Math.abs(serviceLat - requestedLat) > 0.000001d || Math.abs(serviceLng - requestedLng) > 0.000001d) return;
                addressInput.setText(resolved);
            });
        });
        updateServiceMiniMap("Pinned at " + roundCoordinate(serviceLat) + ", " + roundCoordinate(serviceLng), true);
        setLocationStatus(message, GREEN);
    }

    private String formatLocation(Location location) {
        try {
            Geocoder geocoder = new Geocoder(this, Locale.getDefault());
            List<Address> addresses = geocoder.getFromLocation(location.getLatitude(), location.getLongitude(), 1);
            if (addresses != null && !addresses.isEmpty()) {
                Address address = addresses.get(0);
                String fullAddress = address.getAddressLine(0);
                if (fullAddress != null && !fullAddress.trim().isEmpty()) {
                    return fullAddress;
                }
            }
        } catch (Exception ignored) {
            // Coordinates are still useful when reverse geocoding is unavailable.
        }
        return "Lat " + roundCoordinate(location.getLatitude()) + ", Lng " + roundCoordinate(location.getLongitude());
    }

    private String roundCoordinate(double value) {
        return String.format(Locale.US, "%.6f", value);
    }

    private void setManualLocationFallback(String message) {
        if (addressInput != null && addressInput.getText().toString().trim().toLowerCase(Locale.US).startsWith("detecting")) {
            addressInput.setText("");
        }
        if (addressInput != null) {
            addressInput.setVisibility(View.VISIBLE);
        }
        updateServiceMiniMap("Pin preview is available after address or permission is updated.", false);
        setLocationStatus(message, ORANGE);
    }

    private void setLocationStatus(String message, int color) {
        if (locationStatus != null) {
            locationStatus.setText(message);
            locationStatus.setTextColor(color);
        }
        if (locationStatusIcon != null) {
            locationStatusIcon.setText(color == GREEN ? "\u2713" : "!");
            locationStatusIcon.setTextColor(color);
            locationStatusIcon.setBackground(stroke(Color.WHITE, color, dp(12)));
        }
        refreshBookingStepper(false);
    }

