    private String[] includesFor(Service service) {
        if ("electrician".equals(service.getId())) {
            return new String[]{"Switchboard Check", "Wiring Repair", "Fan Service", "MCB Inspection", "Socket Fix", "Safety Testing"};
        }
        if ("plumbing".equals(service.getId())) {
            return new String[]{"Leak Inspection", "Tap Repair", "Drain Cleaning", "Flush Tank Fix", "Pipe Check", "Water Motor Help"};
        }
        if ("carpenter".equals(service.getId())) {
            return new String[]{"Door Alignment", "Lock Fix", "Furniture Assembly", "Shelf Fitting", "Cabinet Repair", "Hardware Check"};
        }
        if ("cleaning".equals(service.getId())) {
            return new String[]{"Room Cleaning", "Bathroom Cleaning", "Sofa Dusting", "Floor Care", "Kitchen Wipe-down", "Waste Cleanup"};
        }
        if ("laundry".equals(service.getId())) {
            return new String[]{"Clothes Pickup", "Wash & Fold", "Ironing", "Dry Clean Support", "Stain Check", "Doorstep Delivery"};
        }
        if ("pest".equals(service.getId())) {
            return new String[]{"Site Inspection", "Safe Treatment", "Kitchen Coverage", "Bathroom Coverage", "Entry Point Check", "Follow-up Advice"};
        }
        if ("ro".equals(service.getId())) {
            return new String[]{"RO Inspection", "Filter Check", "Leakage Repair", "Water Flow Check", "Installation Help", "Service Report"};
        }
        if ("appliances".equals(service.getId())) {
            return new String[]{"Device Inspection", "Fault Diagnosis", "Basic Repair", "Part Estimate", "Safety Check", "Service Report"};
        }
        return new String[]{"AC Inspection", "Gas Refilling", "AC Cleaning", "Filter Cleaning", "Performance Check", "Repair & Replacement"};
    }

