    private void startShine(View shine) {
        shine.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener() {
            @Override
            public void onViewAttachedToWindow(View attachedView) {
                attachedView.removeOnAttachStateChangeListener(this);
                attachedView.post(() -> {
                    ObjectAnimator animator = ObjectAnimator.ofFloat(attachedView, View.TRANSLATION_X, -dp(120), dp(420));
                    animator.setDuration(1850);
                    animator.setStartDelay(450);
                    animator.setRepeatCount(ValueAnimator.INFINITE);
                    animator.setRepeatMode(ValueAnimator.RESTART);
                    animator.setInterpolator(new AccelerateDecelerateInterpolator());
                    animator.start();
                    cancelOnDetach(attachedView, animator);
                });
            }

            @Override
            public void onViewDetachedFromWindow(View detachedView) {
                detachedView.animate().cancel();
            }
        });
    }

    private View glowWrap(View child, int childHeightDp, int radiusDp) {
        FrameLayout frame = new FrameLayout(this);
        frame.setClipChildren(false);
        frame.setClipToPadding(false);

        View glow = new View(this);
        glow.setBackground(glowDrawable(radiusDp + 8));
        glow.setAlpha(0.55f);
        FrameLayout.LayoutParams glowParams = new FrameLayout.LayoutParams(-1, dp(childHeightDp));
        glowParams.setMargins(dp(8), dp(10), dp(8), 0);
        frame.addView(glow, glowParams);

        child.setElevation(dp(5));
        FrameLayout.LayoutParams childParams = new FrameLayout.LayoutParams(-1, dp(childHeightDp));
        childParams.setMargins(dp(6), 0, dp(6), dp(12));
        frame.addView(child, childParams);

        startPulse(glow, 0.28f, 0.78f, 1350);
        return frame;
    }

    private GradientDrawable glowDrawable(int radiusDp) {
        GradientDrawable drawable = new GradientDrawable(
                GradientDrawable.Orientation.TL_BR,
                new int[]{Color.argb(86, 217, 137, 141), Color.argb(28, 248, 225, 225)}
        );
        drawable.setCornerRadius(dp(radiusDp));
        return drawable;
    }

    private void animateIn(View view, int delayMs) {
        view.animate().cancel();
        view.setAlpha(0f);
        view.setTranslationY(dp(10));
        int startDelay = Math.min(delayMs, 110);
        Runnable startAnimation = () -> view.animate()
                .alpha(1f)
                .translationY(0f)
                .setStartDelay(startDelay)
                .setDuration(230)
                .setInterpolator(new AccelerateDecelerateInterpolator())
                .start();
        if (view.isAttachedToWindow()) {
            view.post(startAnimation);
            return;
        }
        view.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener() {
            @Override
            public void onViewAttachedToWindow(View attachedView) {
                attachedView.removeOnAttachStateChangeListener(this);
                attachedView.post(startAnimation);
            }

            @Override
            public void onViewDetachedFromWindow(View detachedView) {
                detachedView.animate().cancel();
            }
        });
    }

    private void startPulse(View view, float minAlpha, float maxAlpha, long durationMs) {
        ObjectAnimator alpha = ObjectAnimator.ofFloat(view, View.ALPHA, minAlpha, maxAlpha);
        alpha.setDuration(durationMs);
        alpha.setRepeatCount(ValueAnimator.INFINITE);
        alpha.setRepeatMode(ValueAnimator.REVERSE);
        alpha.setInterpolator(new AccelerateDecelerateInterpolator());
        alpha.start();
        cancelOnDetach(view, alpha);
    }

    private void startScalePulse(View view, float from, float to, long durationMs) {
        ObjectAnimator scaleX = ObjectAnimator.ofFloat(view, View.SCALE_X, from, to);
        ObjectAnimator scaleY = ObjectAnimator.ofFloat(view, View.SCALE_Y, from, to);
        for (ObjectAnimator animator : new ObjectAnimator[]{scaleX, scaleY}) {
            animator.setDuration(durationMs);
            animator.setRepeatCount(ValueAnimator.INFINITE);
            animator.setRepeatMode(ValueAnimator.REVERSE);
            animator.setInterpolator(new AccelerateDecelerateInterpolator());
        }
        AnimatorSet pulse = new AnimatorSet();
        pulse.playTogether(scaleX, scaleY);
        pulse.start();
        cancelOnDetach(view, pulse);
    }

    private void cancelOnDetach(View view, Animator animator) {
        view.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener() {
            @Override
            public void onViewAttachedToWindow(View attachedView) {
                // Keep the animation alive while the view is visible.
            }

            @Override
            public void onViewDetachedFromWindow(View detachedView) {
                detachedView.removeOnAttachStateChangeListener(this);
                animator.cancel();
            }
        });
    }

    private void addPressAnimation(View view) {
        view.setOnTouchListener((pressedView, event) -> {
            if (event.getActionMasked() == MotionEvent.ACTION_DOWN) {
                pressedView.animate()
                        .scaleX(0.94f)
                        .scaleY(0.94f)
                        .alpha(0.86f)
                        .setDuration(75)
                        .setInterpolator(new AccelerateDecelerateInterpolator())
                        .start();
            } else if (event.getActionMasked() == MotionEvent.ACTION_UP || event.getActionMasked() == MotionEvent.ACTION_CANCEL) {
                pressedView.animate()
                        .scaleX(1.0f)
                        .scaleY(1.0f)
                        .alpha(1.0f)
                        .setDuration(150)
                        .setInterpolator(new AccelerateDecelerateInterpolator())
                        .start();
            }
            return false;
        });
    }

    private View iconBox(Service service) {
        return serviceLogoView(service, 58, true);
    }

    private ImageView tintedIcon(int resId, int color, int paddingDp) {
        ImageView icon = new ImageView(this);
        Drawable drawable = getDrawable(resId);
        if (drawable != null) {
            drawable = drawable.mutate();
            drawable.setTint(color);
            icon.setImageDrawable(drawable);
        }
        int padding = dp(paddingDp);
        icon.setPadding(padding, padding, padding, padding);
        icon.setScaleType(ImageView.ScaleType.CENTER);
        return icon;
    }

    private View serviceLogoView(Service service, int sizeDp, boolean boxed) {
        int logo = serviceLogoResource(service);
        if (logo != 0) {
            ImageView icon = new ImageView(this);
            icon.setImageResource(logo);
            boolean imageLogo = hasEmbeddedServiceTitle(service);
            if (!imageLogo) {
                icon.setColorFilter(iconColor(service));
            }
            icon.setAdjustViewBounds(false);
            icon.setScaleType(ImageView.ScaleType.FIT_CENTER);
            int padding;
            if (imageLogo) {
                padding = boxed ? (sizeDp >= 70 ? 10 : 8) : (sizeDp <= 40 ? 3 : 5);
            } else {
                padding = boxed ? (sizeDp >= 58 ? 12 : 9) : 5;
            }
            icon.setPadding(dp(padding), dp(padding), dp(padding), dp(padding));
            if (boxed) {
                icon.setBackground(logoBackground(service));
                icon.setElevation(dp(3));
            }
            icon.setMinimumWidth(dp(sizeDp));
            icon.setMinimumHeight(dp(sizeDp));
            return icon;
        }
        TextView icon = text(serviceSymbol(service), boxed ? 25 : 32, iconColor(service), true);
        icon.setGravity(Gravity.CENTER);
        if (boxed) {
            icon.setBackground(logoBackground(service));
            icon.setElevation(dp(3));
        }
        return icon;
    }

    private int serviceLogoResource(Service service) {
        if ("ac".equals(service.getId())) {
            return R.drawable.service_logo_ac;
        }
        if ("plumbing".equals(service.getId())) {
            return R.drawable.service_logo_plumbing;
        }
        if ("electrician".equals(service.getId())) {
            return R.drawable.service_logo_electrician;
        }
        if ("carpenter".equals(service.getId())) {
            return R.drawable.service_home_carpenter;
        }
        if ("painting".equals(service.getId())) {
            return R.drawable.service_home_painting;
        }
        if ("interior".equals(service.getId())) {
            return R.drawable.service_home_interior;
        }
        if ("roadside".equals(service.getId())) {
            return R.drawable.service_home_roadside;
        }
        if ("cleaning".equals(service.getId())) {
            return R.drawable.service_logo_cleaning;
        }
        if ("laundry".equals(service.getId())) {
            return R.drawable.service_home_laundry;
        }
        if ("pest".equals(service.getId())) {
            return R.drawable.ic_service_pest_logo;
        }
        if ("ro".equals(service.getId())) {
            return R.drawable.ro_service_logo;
        }
        if ("appliances".equals(service.getId())) {
            return R.drawable.service_logo_appliances;
        }
        return 0;
    }

    private boolean hasEmbeddedServiceTitle(Service service) {
        return "ac".equals(service.getId())
                || "plumbing".equals(service.getId())
                || "electrician".equals(service.getId())
                || "carpenter".equals(service.getId())
                || "painting".equals(service.getId())
                || "interior".equals(service.getId())
                || "roadside".equals(service.getId())
                || "cleaning".equals(service.getId())
                || "laundry".equals(service.getId())
                || "ro".equals(service.getId())
                || "pest".equals(service.getId())
                || "appliances".equals(service.getId());
    }

